def init_db():
    fresh = not os.path.exists(DB_PATH)
    conn = get_db()
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL CHECK(role IN ('owner','employee')),
            name TEXT NOT NULL,
            job_role TEXT,
            phone TEXT,
            start_date TEXT,
            status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),
            pay_rate TEXT,
            pay_type TEXT,
            notes TEXT,
            account_claimed INTEGER NOT NULL DEFAULT 1,
            invite_token TEXT,
            created_at TEXT NOT NULL,
            skills TEXT,
            emergency_contact_name TEXT,
            emergency_contact_phone TEXT,
            emergency_contact_relationship TEXT,
            reset_token TEXT,
            reset_token_expires_at TEXT
        );

        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            title TEXT NOT NULL,
            filename TEXT NOT NULL,
            uploaded_at TEXT NOT NULL,
            expiry_date TEXT
        );

        CREATE TABLE IF NOT EXISTS shopping_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT,
            store TEXT,
            bought INTEGER NOT NULL DEFAULT 0,
            added_by_user_id INTEGER REFERENCES users(id),
            created_at TEXT NOT NULL,
            bought_at TEXT
        );

        CREATE TABLE IF NOT EXISTS breakfast_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            low_stock INTEGER NOT NULL DEFAULT 0,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS breakfast_checklist_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            item_id INTEGER NOT NULL REFERENCES breakfast_items(id) ON DELETE CASCADE,
            checklist_date TEXT NOT NULL,
            checked_by_user_id INTEGER REFERENCES users(id),
            checked_at TEXT NOT NULL,
            UNIQUE(item_id, checklist_date)
        );

        CREATE TABLE IF NOT EXISTS login_throttle (
            ip_address TEXT PRIMARY KEY,
            failed_count INTEGER NOT NULL DEFAULT 0,
            locked_until TEXT
        );

        CREATE TABLE IF NOT EXISTS submission_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ip_address TEXT NOT NULL,
            action TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS notifications (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            kind TEXT NOT NULL,
            title TEXT NOT NULL,
            body TEXT,
            link TEXT,
            related_task_id INTEGER REFERENCES tasks(id) ON DELETE SET NULL,
            read_at TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS push_subscriptions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            endpoint TEXT NOT NULL UNIQUE,
            p256dh TEXT NOT NULL,
            auth TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS hr_notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            body TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','handled')),
            created_at TEXT NOT NULL,
            handled_at TEXT,
            response TEXT,
            responded_at TEXT
        );

        CREATE TABLE IF NOT EXISTS check_in_notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS pay_rate_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            old_pay_rate TEXT,
            new_pay_rate TEXT,
            old_pay_type TEXT,
            new_pay_type TEXT,
            changed_by_user_id INTEGER REFERENCES users(id),
            changed_at TEXT NOT NULL
        );

        -- What somebody is actually paid, as a number.
        --
        -- users.pay_rate and users.pay_type are free text, on purpose: they
        -- hold whatever the contract says, including "SMIC + 5%" and "12,50
        -- €/h net". That is the right place for prose and the wrong place to
        -- cost a season from, so estimated_hourly_cost() regexes a number out
        -- of it and gives up whenever it cannot — which means a monthly-
        -- salaried chef contributed exactly nothing to the wage bill.
        --
        -- One row per change, never edited in place, so last month's labour
        -- cost does not move when somebody gets a rise this month. Same
        -- reasoning as the stock ledger: the figure is derived from history,
        -- and history is append-only.
        CREATE TABLE IF NOT EXISTS wage_records (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            effective_from TEXT NOT NULL,
            basis TEXT NOT NULL CHECK(basis IN ('hourly','monthly')),
            gross_amount REAL NOT NULL,
            employer_rate REAL,
            note TEXT,
            created_by_user_id INTEGER REFERENCES users(id),
            created_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_wage_records_person
            ON wage_records(user_id, effective_from);

        CREATE TABLE IF NOT EXISTS onboarding_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            label TEXT NOT NULL,
            done INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS candidates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT,
            phone TEXT,
            role_applied TEXT,
            status TEXT NOT NULL DEFAULT 'new'
                CHECK(status IN ('new','interviewing','offered','hired','rejected')),
            notes TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT
        );

        CREATE TABLE IF NOT EXISTS equipment_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            label TEXT NOT NULL,
            notes TEXT,
            issued_at TEXT NOT NULL,
            returned_at TEXT
        );

        CREATE TABLE IF NOT EXISTS offboarding_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            label TEXT NOT NULL,
            done INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS time_entries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            clock_in_at TEXT NOT NULL,
            clock_out_at TEXT,
            auto_closed INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS breaks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            time_entry_id INTEGER NOT NULL REFERENCES time_entries(id) ON DELETE CASCADE,
            start_at TEXT NOT NULL,
            end_at TEXT
        );

        CREATE TABLE IF NOT EXISTS company_info (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            legal_name TEXT,
            registration_number TEXT,
            vat_number TEXT,
            registered_address TEXT,
            incorporation_date TEXT,
            accountant_name TEXT,
            accountant_phone TEXT,
            accountant_email TEXT,
            insurance_broker_name TEXT,
            insurance_broker_phone TEXT,
            insurance_broker_email TEXT,
            updated_at TEXT
        );

        CREATE TABLE IF NOT EXISTS bank_details (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label TEXT NOT NULL,
            bank_name TEXT,
            account_holder TEXT,
            currency TEXT,
            notes TEXT,
            sensitive_encrypted TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS recurring_costs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label TEXT NOT NULL,
            amount REAL NOT NULL DEFAULT 0,
            frequency TEXT NOT NULL DEFAULT 'monthly' CHECK(frequency IN ('monthly','annual')),
            category TEXT,
            next_due_date TEXT,
            notes TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS waitlist_entries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            phone TEXT,
            desired_arrival TEXT,
            desired_departure TEXT,
            party_size INTEGER,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','contacted','booked','closed')),
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_booking_id INTEGER REFERENCES workshop_bookings(id) ON DELETE SET NULL,
            guest_name TEXT NOT NULL,
            rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
            comment TEXT,
            featured INTEGER NOT NULL DEFAULT 0,
            submitted_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS guest_feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
            guest_name TEXT NOT NULL,
            rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
            comment TEXT,
            submitted_at TEXT NOT NULL
        );

        -- Every refund ever issued, across all four booking types. The house
        -- policy is non-refundable, so refunds are always a deliberate,
        -- case-by-case decision by the owner -- which is exactly why each one
        -- needs a reason and an attributable name against it.
        --
        -- booking_id is deliberately not a foreign key: it points into one of
        -- four different tables depending on `category`, which SQLite can't
        -- express. Look it up via the category.
        CREATE TABLE IF NOT EXISTS refunds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL CHECK(category IN ('room','restaurant','workshop','event')),
            booking_id INTEGER NOT NULL,
            reference_code TEXT,
            guest_name TEXT,
            guest_email TEXT,
            amount REAL NOT NULL,
            reason TEXT NOT NULL,
            method TEXT NOT NULL DEFAULT 'stripe'
                CHECK(method IN ('stripe','bank_transfer','cash','other')),
            stripe_refund_id TEXT,
            refunded_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Individual payments received against a stay. bookings.amount_paid is
        -- the running total; this is what made it up. A stay can be paid more
        -- than once -- a deposit, then a balance, then a night added later --
        -- so a single stripe_session_id column on bookings cannot record them.
        -- The UNIQUE session id is what makes recording idempotent: Stripe
        -- retries webhooks and guests reload the success page, and crediting
        -- the same payment twice would send somebody home believing they had
        -- paid when they had not.
        CREATE TABLE IF NOT EXISTS booking_payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            booking_id INTEGER NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
            amount REAL NOT NULL,
            method TEXT NOT NULL DEFAULT 'stripe',
            stripe_session_id TEXT UNIQUE,
            created_at TEXT NOT NULL
        );

        -- Training, tickets and certificates a staff member holds. Separate
        -- from `documents` (which is a filing cabinet): these have an issuer
        -- and expire, and in French hospitality some of them are legally
        -- required to be current -- food hygiene for anyone near the kitchen,
        -- first aid, a licence for whoever drives the guest transfers.
        -- One row per monitored inbox. The château runs an inbox per business
        -- area and that list grows, so this is a table rather than a fixed
        -- list in code: the owner can add an inbox and point it at whoever
        -- handles that area, and flagged mail routes itself on arrival
        -- instead of waiting to be triaged by hand.
        -- How long each kind of HR item may sit before someone is chased, and
        -- how long before it goes over their head. One row per item type,
        -- editable by the owner -- an unsigned contract is not the same
        -- urgency as an expired food-hygiene certificate.
        CREATE TABLE IF NOT EXISTS hr_escalation_rules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            item_type TEXT NOT NULL UNIQUE,
            sla_days REAL NOT NULL DEFAULT 3,
            escalate_after_days REAL NOT NULL DEFAULT 7,
            active INTEGER NOT NULL DEFAULT 1,
            updated_at TEXT NOT NULL
        );

        -- The state of a single outstanding HR item as it ages. Separate from
        -- the source tables so nothing has to grow escalation columns, and so
        -- a reminder fires once rather than every time the job runs.
        CREATE TABLE IF NOT EXISTS hr_escalations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            item_type TEXT NOT NULL,
            item_id TEXT NOT NULL,
            subject_user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
            summary TEXT,
            due_at TEXT,
            first_seen_at TEXT NOT NULL,
            reminded_at TEXT,
            escalated_at TEXT,
            resolved_at TEXT,
            UNIQUE(item_type, item_id)
        );

        CREATE TABLE IF NOT EXISTS mailbox_routing (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            mailbox TEXT NOT NULL UNIQUE,
            label TEXT,
            default_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            route_to_on_shift INTEGER NOT NULL DEFAULT 0,
            escalate_hours REAL NOT NULL DEFAULT 48,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS certifications (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            name TEXT NOT NULL,
            issuer TEXT,
            reference TEXT,
            issued_date TEXT,
            expiry_date TEXT,
            required INTEGER NOT NULL DEFAULT 0,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        -- When someone is normally free to work. Recurring weekday pattern;
        -- one row per weekday they've said something about. Absence of a row
        -- means "no preference stated", not "unavailable".
        CREATE TABLE IF NOT EXISTS availability_rules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),
            available INTEGER NOT NULL DEFAULT 1,
            from_time TEXT,
            to_time TEXT,
            note TEXT,
            updated_at TEXT NOT NULL,
            UNIQUE(user_id, weekday)
        );

        -- One-off exceptions to the pattern above: "can't do the 14th",
        -- or "actually free that Sunday".
        CREATE TABLE IF NOT EXISTS availability_exceptions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            on_date TEXT NOT NULL,
            available INTEGER NOT NULL DEFAULT 0,
            note TEXT,
            created_at TEXT NOT NULL,
            UNIQUE(user_id, on_date)
        );

        -- Unplanned absence, deliberately NOT the same thing as booked leave:
        -- annual leave is requested and approved in advance, this is what
        -- actually happened on the day. Kept apart so a sickness pattern
        -- doesn't hide inside holiday.
        CREATE TABLE IF NOT EXISTS absences (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            kind TEXT NOT NULL DEFAULT 'sick'
                CHECK(kind IN ('sick','emergency','unpaid','unauthorised','other')),
            reason TEXT,
            self_certified INTEGER NOT NULL DEFAULT 1,
            doctor_note_filename TEXT,
            return_to_work_note TEXT,
            return_to_work_done_at TEXT,
            recorded_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Structured review, building on the informal check-in notes. The
        -- acknowledgement step matters: it is the record that the employee
        -- actually saw what was written about them.
        CREATE TABLE IF NOT EXISTS performance_reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            reviewer_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            review_date TEXT NOT NULL,
            period_start TEXT,
            period_end TEXT,
            overall_rating INTEGER CHECK(overall_rating BETWEEN 1 AND 5),
            strengths TEXT,
            improvements TEXT,
            goals TEXT,
            employee_comments TEXT,
            status TEXT NOT NULL DEFAULT 'draft'
                CHECK(status IN ('draft','shared','acknowledged')),
            shared_at TEXT,
            acknowledged_at TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            actor_user_id INTEGER REFERENCES users(id),
            action TEXT NOT NULL,
            target TEXT,
            details TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS vendors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            contact_person TEXT,
            phone TEXT,
            email TEXT,
            payment_terms TEXT,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS insurance_policies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            provider TEXT NOT NULL,
            policy_number TEXT,
            coverage_type TEXT,
            premium REAL,
            premium_frequency TEXT DEFAULT 'annual' CHECK(premium_frequency IN ('monthly','annual')),
            expiry_date TEXT,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS vehicles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            vehicle_type TEXT,
            fuel_type TEXT,
            license_plate TEXT,
            cleanliness TEXT NOT NULL DEFAULT 'clean' CHECK(cleanliness IN ('clean','dirty')),
            fuel_level TEXT NOT NULL DEFAULT 'ok' CHECK(fuel_level IN ('ok','low')),
            next_service_due TEXT,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS vehicle_maintenance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
            title TEXT NOT NULL,
            description TEXT,
            reported_by_user_id INTEGER REFERENCES users(id),
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),
            created_at TEXT NOT NULL,
            resolved_at TEXT
        );

        CREATE TABLE IF NOT EXISTS vehicle_usage (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
            user_id INTEGER REFERENCES users(id),
            purpose TEXT,
            checked_out_at TEXT NOT NULL,
            checked_in_at TEXT
        );

        CREATE TABLE IF NOT EXISTS vehicle_transfers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
            guest_name TEXT,
            direction TEXT CHECK(direction IN ('pickup','dropoff')),
            scheduled_at TEXT NOT NULL,
            driver_user_id INTEGER REFERENCES users(id),
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS company_documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            filename TEXT NOT NULL,
            uploaded_by_user_id INTEGER REFERENCES users(id),
            uploaded_at TEXT NOT NULL,
            expiry_date TEXT
        );

        CREATE TABLE IF NOT EXISTS vault_entries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            username TEXT,
            url TEXT,
            secret_encrypted TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            updated_by_user_id INTEGER REFERENCES users(id)
        );

        CREATE TABLE IF NOT EXISTS manual_sections (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            body TEXT NOT NULL DEFAULT '',
            sort_order INTEGER NOT NULL DEFAULT 0
        );

        -- Posting an announcement and everybody having read it are different
        -- facts, and only the first was recorded. Seen, not agreed: the manual
        -- has its own "read and understood" tick and this must not stand in
        -- for it.
        CREATE TABLE IF NOT EXISTS announcement_reads (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            announcement_id INTEGER NOT NULL REFERENCES announcements(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            seen_at TEXT NOT NULL,
            UNIQUE(announcement_id, user_id)
        );

        CREATE TABLE IF NOT EXISTS manual_acknowledgments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
            acknowledged_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            role TEXT,
            phone TEXT,
            notes TEXT,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS announcements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            posted_by_user_id INTEGER REFERENCES users(id),
            title TEXT NOT NULL,
            body TEXT NOT NULL DEFAULT '',
            expires_date TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS social_posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            platform TEXT NOT NULL DEFAULT 'Instagram',
            caption TEXT NOT NULL DEFAULT '',
            post_type TEXT,
            scheduled_date TEXT,
            scheduled_time TEXT,
            status TEXT NOT NULL DEFAULT 'idea' CHECK(status IN ('idea','drafted','scheduled','posted')),
            assigned_to_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            link TEXT,
            notes TEXT,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL,
            posted_at TEXT
        );

        -- A standing commitment to post: "Instagram, Tuesdays at 10, the
        -- restaurant". The plan is the rule; social_posts rows are what the
        -- rule produced, and they are ordinary editable posts once made.
        CREATE TABLE IF NOT EXISTS social_plans (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            platform TEXT NOT NULL DEFAULT 'Instagram',
            cadence TEXT NOT NULL DEFAULT 'weekly'
                CHECK(cadence IN ('weekly','fortnightly','monthly')),
            weekday INTEGER,              -- 0=Mon..6=Sun, for weekly/fortnightly
            day_of_month INTEGER,         -- 1..28, for monthly
            post_time TEXT,               -- '10:00', local
            theme TEXT,                   -- what this slot is for
            brief TEXT,                   -- the standing instruction to whoever writes it
            post_type TEXT,
            assigned_to_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            -- How far ahead the task appears. Writing a caption on the morning
            -- it goes out is how a slot gets skipped.
            lead_days INTEGER NOT NULL DEFAULT 3,
            active INTEGER NOT NULL DEFAULT 1,
            -- The high-water mark. Nothing is ever generated on or before this
            -- date, so deleting a post the plan made does not bring it back on
            -- the next run.
            generated_through TEXT,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Work the house needs on a rhythm, rather than when something breaks.
        -- Room issues and vehicle maintenance are both reactive: somebody
        -- reports a problem. A chimney nobody has swept does not report
        -- itself, and the first anyone hears of it may be an insurer asking
        -- for the certificate after a fire.
        CREATE TABLE IF NOT EXISTS maintenance_schedules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'building',
            location TEXT,
            every_months INTEGER NOT NULL DEFAULT 12,
            -- When it was last actually done, and when it is next owed. Kept
            -- separately: an owner who knows the boiler was serviced in March
            -- can say so without having to work out the next date themselves.
            last_done_on TEXT,
            next_due_on TEXT,
            -- How much warning. A chimney sweep needs booking; a light bulb
            -- does not.
            lead_days INTEGER NOT NULL DEFAULT 21,
            assigned_to_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            vendor_id INTEGER REFERENCES vendors(id) ON DELETE SET NULL,
            -- Whether something outside the house requires it. Set by the
            -- owner, never assumed: what an insurer or a commune demands
            -- varies, and inventing a legal requirement into their data would
            -- be worse than leaving it blank.
            required_by TEXT NOT NULL DEFAULT 'none'
                CHECK(required_by IN ('none', 'insurance', 'law', 'both')),
            insurance_policy_id INTEGER REFERENCES insurance_policies(id) ON DELETE SET NULL,
            notes TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            generated_through TEXT,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Each time the work was actually done. The certificate matters as
        -- much as the date: proof is the thing an insurer asks for.
        CREATE TABLE IF NOT EXISTS maintenance_visits (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            schedule_id INTEGER NOT NULL REFERENCES maintenance_schedules(id) ON DELETE CASCADE,
            done_on TEXT NOT NULL,
            done_by TEXT,
            cost REAL,
            certificate_filename TEXT,
            notes TEXT,
            task_id INTEGER REFERENCES tasks(id) ON DELETE SET NULL,
            recorded_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS room_issues (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            reported_by_user_id INTEGER REFERENCES users(id),
            title TEXT NOT NULL,
            description TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),
            created_at TEXT NOT NULL,
            resolved_at TEXT
        );

        -- A per-PERSON guest profile, NOT a per-stay record. Stay dates,
        -- party size and room live on `bookings`, which is the single source
        -- of truth for who is actually in residence; this table holds only
        -- what stays true between visits.
        CREATE TABLE IF NOT EXISTS guests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT,
            phone TEXT,
            dietary_notes TEXT,
            preferences TEXT,
            vip INTEGER NOT NULL DEFAULT 0,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS expenses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL CHECK(kind IN ('supplier_invoice','staff_expense')),
            submitted_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            vendor_name TEXT,
            description TEXT NOT NULL,
            amount REAL NOT NULL DEFAULT 0,
            filename TEXT,
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','paid')),
            owner_note TEXT,
            submitted_at TEXT NOT NULL,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS app_settings (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshops (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT NOT NULL DEFAULT '',
            instructor_name TEXT,
            instructor_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            price_per_person REAL NOT NULL DEFAULT 0,
            default_capacity INTEGER NOT NULL DEFAULT 10,
            active INTEGER NOT NULL DEFAULT 1,
            sort_order INTEGER NOT NULL DEFAULT 0,
            photo_filename TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_id INTEGER NOT NULL REFERENCES workshops(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            capacity INTEGER NOT NULL DEFAULT 10,
            notes TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_bookings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id INTEGER NOT NULL REFERENCES workshop_sessions(id) ON DELETE CASCADE,
            reference_code TEXT UNIQUE NOT NULL,
            manage_token TEXT UNIQUE NOT NULL,
            guest_name TEXT NOT NULL,
            guest_email TEXT NOT NULL,
            guest_phone TEXT,
            party_size INTEGER NOT NULL DEFAULT 1,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled')),
            total_price REAL,
            booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS workshop_booking_guests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_booking_id INTEGER NOT NULL REFERENCES workshop_bookings(id) ON DELETE CASCADE,
            guest_name TEXT NOT NULL,
            is_lead INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_transactions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_booking_id INTEGER NOT NULL REFERENCES workshop_bookings(id) ON DELETE CASCADE,
            kind TEXT NOT NULL CHECK(kind IN ('charge','discount','payment','refund')),
            description TEXT NOT NULL,
            amount REAL NOT NULL,
            method TEXT,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_custom_fields (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_id INTEGER NOT NULL REFERENCES workshops(id) ON DELETE CASCADE,
            label TEXT NOT NULL,
            field_type TEXT NOT NULL DEFAULT 'text' CHECK(field_type IN ('text','textarea','select','checkbox')),
            options TEXT,
            required INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_custom_field_responses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_booking_id INTEGER NOT NULL REFERENCES workshop_bookings(id) ON DELETE CASCADE,
            custom_field_id INTEGER NOT NULL REFERENCES workshop_custom_fields(id) ON DELETE CASCADE,
            value TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS workshop_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            workshop_booking_id INTEGER NOT NULL REFERENCES workshop_bookings(id) ON DELETE CASCADE,
            subject TEXT NOT NULL,
            recipient TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'sent',
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS email_templates (
            template_key TEXT PRIMARY KEY,
            label TEXT NOT NULL,
            subject TEXT NOT NULL,
            body TEXT NOT NULL,
            updated_at TEXT
        );

        -- Owner-written email templates for campaigns and announcements, as
        -- opposed to `email_templates` above which holds the fixed system
        -- messages (booking confirmed, balance due). These are created and
        -- named by the owner, grouped by area, and reused.
        CREATE TABLE IF NOT EXISTS campaign_templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            area TEXT NOT NULL DEFAULT 'general',
            category TEXT,
            subject TEXT NOT NULL,
            body TEXT NOT NULL,
            -- Optional automation: send this many days before/after a guest's
            -- arrival or departure instead of being sent by hand.
            trigger_event TEXT CHECK(trigger_event IN ('arrival','departure','workshop_start')),
            trigger_offset_days INTEGER,
            trigger_active INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT
        );

        -- Every campaign send, one row per recipient. This is the record of
        -- who was emailed what, and the thing that stops an automated
        -- template mailing the same guest the same message twice.
        CREATE TABLE IF NOT EXISTS campaign_sends (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            template_id INTEGER REFERENCES campaign_templates(id) ON DELETE SET NULL,
            template_name TEXT,
            recipient_email TEXT NOT NULL,
            recipient_name TEXT,
            subject TEXT,
            status TEXT NOT NULL DEFAULT 'sent' CHECK(status IN ('sent','failed','skipped','test')),
            detail TEXT,
            dedupe_key TEXT,
            sent_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Guests who have asked not to receive campaign email. Checked on
        -- every bulk and automated send; transactional mail (their own
        -- booking confirmation) is unaffected.
        -- Workplace accidents and guest incidents in one register. A French
        -- employer must keep a record of workplace accidents including minor
        -- ones; guest incidents are kept alongside because the follow-up (and
        -- often the insurer) is the same. `kind` separates them for reporting.
        CREATE TABLE IF NOT EXISTS incidents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL DEFAULT 'workplace'
                CHECK(kind IN ('workplace','guest','property','near_miss')),
            occurred_at TEXT NOT NULL,
            location TEXT,
            summary TEXT NOT NULL,
            detail TEXT,
            severity TEXT NOT NULL DEFAULT 'minor'
                CHECK(severity IN ('near_miss','minor','significant','serious')),
            affected_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            affected_person TEXT,
            reported_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            witnesses TEXT,
            first_aid_given INTEGER NOT NULL DEFAULT 0,
            medical_attention INTEGER NOT NULL DEFAULT 0,
            work_days_lost INTEGER,
            insurance_policy_id INTEGER REFERENCES insurance_policies(id) ON DELETE SET NULL,
            reported_to_insurer_at TEXT,
            action_taken TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','actioned','closed')),
            closed_at TEXT,
            created_at TEXT NOT NULL
        );

        -- Who holds which key, gate code or alarm PIN. Offboarding needs to be
        -- able to ask "what does this person actually hold" rather than relying
        -- on a generic checklist item that says "return keys".
        CREATE TABLE IF NOT EXISTS access_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label TEXT NOT NULL,
            kind TEXT NOT NULL DEFAULT 'key'
                CHECK(kind IN ('key','code','alarm','fob','vehicle_key','other')),
            location TEXT,
            notes TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        -- One row per issue. Returning sets returned_at rather than deleting,
        -- so "who had the cellar key in August" is still answerable later.
        CREATE TABLE IF NOT EXISTS access_holdings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            access_item_id INTEGER NOT NULL REFERENCES access_items(id) ON DELETE CASCADE,
            user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
            holder_name TEXT,
            issued_at TEXT NOT NULL,
            issued_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            returned_at TEXT,
            notes TEXT
        );

        -- Extras actually SOLD, as line items. They used to be flattened into
        -- bookings.extras_summary (a text blob) at booking time, which meant an
        -- extra could never be added afterwards, never counted, and never tied
        -- to anything — so "how many bottles did we sell in July" and "does
        -- selling one reduce stock" were both unanswerable.
        CREATE TABLE IF NOT EXISTS booking_extras (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL DEFAULT 'room'
                CHECK(category IN ('room','restaurant','workshop','event')),
            booking_id INTEGER NOT NULL,
            extra_id INTEGER REFERENCES extras(id) ON DELETE SET NULL,
            -- Name and price are COPIED, not looked up: the catalogue price
            -- changes, and a line on last year's booking must keep saying what
            -- was actually charged.
            name TEXT NOT NULL,
            unit_price REAL NOT NULL DEFAULT 0,
            quantity INTEGER NOT NULL DEFAULT 1,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'confirmed'
                CHECK(status IN ('requested','confirmed','delivered','cancelled')),
            scheduled_for TEXT,
            added_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Restaurant POS. An order is a TAB: opened when people sit down, added
        -- to through service, settled at the end. It is deliberately separate
        -- from restaurant_bookings — plenty of covers are walk-ins with no
        -- reservation, and a reservation that never turns up has no order.
        CREATE TABLE IF NOT EXISTS pos_orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            table_label TEXT NOT NULL,
            covers INTEGER NOT NULL DEFAULT 1,
            restaurant_booking_id INTEGER REFERENCES restaurant_bookings(id) ON DELETE SET NULL,
            -- Set when the tab is charged to a room instead of paid on the spot.
            room_booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
            status TEXT NOT NULL DEFAULT 'open'
                CHECK(status IN ('open','paid','charged_to_room','void')),
            payment_method TEXT
                CHECK(payment_method IN ('cash','card_terminal','card_link','room','comp')),
            payment_reference TEXT,
            stripe_session_id TEXT,
            -- The totals are FROZEN onto the order when it is settled. Menu
            -- prices change; a closed tab must keep saying what was charged.
            settled_total REAL,
            notes TEXT,
            opened_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            opened_at TEXT NOT NULL,
            closed_at TEXT
        );

        CREATE TABLE IF NOT EXISTS pos_order_lines (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_id INTEGER NOT NULL REFERENCES pos_orders(id) ON DELETE CASCADE,
            extra_id INTEGER REFERENCES extras(id) ON DELETE SET NULL,
            name TEXT NOT NULL,
            unit_price REAL NOT NULL DEFAULT 0,
            quantity INTEGER NOT NULL DEFAULT 1,
            notes TEXT,
            voided INTEGER NOT NULL DEFAULT 0,
            added_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- Things the château keeps a quantity of. The level is NOT stored here:
        -- it is derived from stock_movements, so it can always be reconciled
        -- and never silently drifts out of step with its own history.
        CREATE TABLE IF NOT EXISTS stock_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'other'
                CHECK(category IN ('drinks','food','cleaning','linen','maintenance','guest_supplies','other')),
            unit TEXT NOT NULL DEFAULT 'each',
            reorder_level REAL NOT NULL DEFAULT 0,
            unit_cost REAL,
            vendor_id INTEGER REFERENCES vendors(id) ON DELETE SET NULL,
            location TEXT,
            notes TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        -- Append-only ledger. Every change to a stock level is a row here with
        -- a reason and, where there is one, a link to the invoice or booking
        -- that caused it. Nothing edits or deletes a movement; a mistake is
        -- corrected by a further movement, so the history stays truthful.
        CREATE TABLE IF NOT EXISTS stock_movements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            stock_item_id INTEGER NOT NULL REFERENCES stock_items(id) ON DELETE CASCADE,
            delta REAL NOT NULL,
            reason TEXT NOT NULL
                CHECK(reason IN ('purchase','sale','wastage','stocktake','correction','opening')),
            unit_cost REAL,
            expense_id INTEGER REFERENCES expenses(id) ON DELETE SET NULL,
            booking_extra_id INTEGER REFERENCES booking_extras(id) ON DELETE SET NULL,
            note TEXT,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        -- What the château owns. Distinct from `equipment_items` (kit issued to
        -- a person) and `access_items` (keys): this is the furniture, art and
        -- fixed equipment an insurer asks about, and that a claim has to be
        -- evidenced from. `value_source` matters more than the number — an
        -- owner's guess and a written valuation are not the same evidence.
        CREATE TABLE IF NOT EXISTS assets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'furniture'
                CHECK(category IN ('furniture','art','antique','equipment','fixture','vehicle','other')),
            location TEXT,
            description TEXT,
            acquired_on TEXT,
            acquired_from TEXT,
            purchase_price REAL,
            estimated_value REAL,
            value_source TEXT DEFAULT 'estimate'
                CHECK(value_source IN ('estimate','purchase','valuation','insurer')),
            valued_on TEXT,
            insurance_policy_id INTEGER REFERENCES insurance_policies(id) ON DELETE SET NULL,
            serial_number TEXT,
            condition TEXT DEFAULT 'good'
                CHECK(condition IN ('excellent','good','fair','poor','damaged')),
            photo_filename TEXT,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'held'
                CHECK(status IN ('held','on_loan','sold','lost','destroyed')),
            disposed_on TEXT,
            created_at TEXT NOT NULL
        );

        -- What a job role REQUIRES. Certifications and documents were tracked
        -- per person with no notion of what the role demands, so "who cannot
        -- legally work this week" was never answerable — only "what expires".
        CREATE TABLE IF NOT EXISTS role_requirements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            job_role TEXT NOT NULL,
            requirement TEXT NOT NULL,
            requirement_type TEXT NOT NULL DEFAULT 'certification'
                CHECK(requirement_type IN ('certification','document')),
            notes TEXT,
            created_at TEXT NOT NULL,
            UNIQUE(job_role, requirement, requirement_type)
        );

        -- A local copy of Pennylane's chart of accounts.
        --
        -- The real chart is ~1,500 accounts, most of them per-guest customer
        -- accounts in class 4. Fetching that on every page load would be slow
        -- and would break whenever their API is down, so it is synced and kept
        -- here. `account_class` is the first digit, which in the French plan
        -- comptable says what the account is FOR: 6 = expenses, 7 = revenue.
        -- That is what turns 1,500 rows into a usable picker.
        -- A guest's way into their own account.
        --
        -- There is no guest password by design. To show someone EVERY booking
        -- on an email address, that address has to be proved — otherwise
        -- typing a stranger's email would list their stays. So: they ask, we
        -- email a one-time link, and the link is the proof.
        --
        -- Short-lived and single-use. A booking's own manage_token stays valid
        -- indefinitely because it only ever exposes that one booking; this
        -- exposes everything, so it is held to a higher standard.
        CREATE TABLE IF NOT EXISTS guest_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL,
            token TEXT NOT NULL UNIQUE,
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            used_at TEXT,
            requested_ip TEXT
        );

        CREATE TABLE IF NOT EXISTS pennylane_accounts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            pennylane_id INTEGER,
            number TEXT NOT NULL UNIQUE,
            label TEXT NOT NULL DEFAULT '',
            account_class TEXT NOT NULL DEFAULT '',
            synced_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS email_optouts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL UNIQUE,
            reason TEXT,
            created_at TEXT NOT NULL
        );

        -- The public gallery, in the sections the site's menu already links to.
        --
        -- The menu links /gallery#inside, #grounds, #restoration, #life and
        -- #views. Those anchors did not exist and the page rendered a fixed
        -- empty list, so all five went to the same blank page — which is why
        -- the sections are a table with a `slug` rather than free-form: the
        -- slug IS the anchor the menu is already pointing at, so a section
        -- cannot quietly stop matching its link.
        --
        -- Photos reuse ROOM_PHOTO_DIR and the existing room_photo route. A
        -- second upload directory would need its own serving route, its own
        -- backup entry and its own permissions, to hold the same kind of file.
        CREATE TABLE IF NOT EXISTS gallery_sections (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT NOT NULL UNIQUE,
            title TEXT NOT NULL,
            blurb TEXT,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS gallery_photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_id INTEGER NOT NULL REFERENCES gallery_sections(id) ON DELETE CASCADE,
            filename TEXT NOT NULL,
            caption TEXT,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        -- What's on locally: the markets, and one-off things worth walking to.
        --
        -- Two shapes in one table, and exactly one of them per row: `weekday`
        -- for the standing markets, which repeat forever, or `event_date` for
        -- a one-off. Storing a market as fifty-two dated rows a year would
        -- mean somebody has to remember to add next year's.
        --
        -- `season_from`/`season_to` are 'MM-DD' with no year, so a winter
        -- entry written once keeps working — and the comparison wraps, since
        -- December-to-March is a perfectly ordinary season here.
        CREATE TABLE IF NOT EXISTS whats_on (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            location TEXT,
            distance TEXT,
            weekday INTEGER,
            event_date TEXT,
            start_time TEXT,
            end_time TEXT,
            season_from TEXT,
            season_to TEXT,
            is_active INTEGER NOT NULL DEFAULT 1,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL DEFAULT (datetime('now'))
        );

        -- Newsletter subscribers, from the box in the public site's menu panel.
        --
        -- Double opt-in: a row exists from the moment somebody types their
        -- address, but `confirmed_at` stays NULL until they click the link in
        -- the email. Only confirmed rows are a mailing list. Anyone can type
        -- somebody else's address into a public form, so without this the
        -- château would be mailing people who never asked — which is both
        -- rude and, under GDPR, not consent.
        --
        -- `token` is the credential in the confirmation link, exactly as
        -- campaign_sends.unsubscribe_token is for unsubscribing: random and
        -- per-subscriber, so the address never travels in the URL and no
        -- token can be walked to reach anybody else.
        CREATE TABLE IF NOT EXISTS newsletter_subscribers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL UNIQUE,
            token TEXT NOT NULL UNIQUE,
            source TEXT NOT NULL DEFAULT 'site',
            confirmed_at TEXT,
            unsubscribed_at TEXT,
            created_at TEXT NOT NULL
        );

        -- Mail that could not be sent, kept so it can go out later.
        --
        -- Without this every undelivered message vanished into a console
        -- print: a guest could pay for a stay and receive nothing, and there
        -- was no record that a confirmation was ever owed. That is the worst
        -- shape a failure can take here, because the guest has already paid
        -- and neither side knows anything is missing.
        --
        -- Password resets and staff invitations are deliberately NOT stored
        -- (see send_email): their body is a working credential, and one that
        -- expires — retrying a stale reset link days later is useless, while
        -- keeping it in a table is a real exposure.
        CREATE TABLE IF NOT EXISTS email_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            to_address TEXT NOT NULL,
            subject TEXT NOT NULL,
            body TEXT NOT NULL,
            ics_content TEXT,
            ics_filename TEXT,
            reason TEXT NOT NULL,
            attempts INTEGER NOT NULL DEFAULT 0,
            last_error TEXT,
            created_at TEXT NOT NULL,
            sent_at TEXT
        );

        -- Who can see which parts of the business.
        --
        -- Before this there were two levels: the owner saw all 302 admin pages
        -- and an employee saw almost none. Fine for two people, and wrong the
        -- moment somebody runs the restaurant but has no business reading
        -- payroll, or keeps the books but does not need the guest register.
        --
        -- A preset is a named bundle of areas rather than a per-page checklist.
        -- Three hundred tick-boxes is not something anyone will maintain, and a
        -- half-ticked list is how a person ends up able to refund a booking but
        -- unable to see it.
        CREATE TABLE IF NOT EXISTS access_presets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            description TEXT,
            -- comma-separated area keys from NAV_AREAS, or '*' for everything
            areas TEXT NOT NULL DEFAULT '',
            is_full_access INTEGER NOT NULL DEFAULT 0,
            built_in INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        -- Staff messaging. Announcements were the only way to say anything to
        -- the team, and they go one way only: the owner posts, nobody replies.
        -- This is the missing half.
        --
        -- Two kinds of channel. 'area' channels are open to every member of
        -- staff and are fixed (kitchen, housekeeping and so on) so a message
        -- always has an obvious home. 'dm' channels are private to their
        -- members. One table rather than two, because the read-state and unread
        -- arithmetic are identical for both and duplicating that is how the two
        -- drift apart.
        CREATE TABLE IF NOT EXISTS chat_channels (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            kind TEXT NOT NULL DEFAULT 'area' CHECK(kind IN ('area','dm')),
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        -- Only populated for DMs. An area channel deliberately has no member
        -- rows: everyone is in it, and materialising that would mean a row per
        -- new employee, or silently leaving them out of the kitchen channel.
        CREATE TABLE IF NOT EXISTS chat_members (
            channel_id INTEGER NOT NULL REFERENCES chat_channels(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            PRIMARY KEY (channel_id, user_id)
        );

        CREATE TABLE IF NOT EXISTS chat_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            channel_id INTEGER NOT NULL REFERENCES chat_channels(id) ON DELETE CASCADE,
            user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        -- How far each person has read in each channel. The message id rather
        -- than a timestamp, so unread counts cannot be thrown off by clock skew
        -- and a message posted while someone was reading is not marked as seen.
        CREATE TABLE IF NOT EXISTS chat_reads (
            channel_id INTEGER NOT NULL REFERENCES chat_channels(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            last_read_message_id INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (channel_id, user_id)
        );

        CREATE TABLE IF NOT EXISTS workshop_waitlist (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id INTEGER NOT NULL REFERENCES workshop_sessions(id) ON DELETE CASCADE,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            phone TEXT,
            party_size INTEGER,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','contacted','booked','closed')),
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS event_inquiries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            reference_code TEXT UNIQUE NOT NULL,
            manage_token TEXT UNIQUE NOT NULL,
            event_type TEXT NOT NULL,
            contact_name TEXT NOT NULL,
            contact_email TEXT NOT NULL,
            contact_phone TEXT,
            preferred_date TEXT,
            alternate_date TEXT,
            guest_count INTEGER,
            message TEXT,
            status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','quoted','confirmed','declined','cancelled')),
            quoted_price REAL,
            owner_note TEXT,
            created_at TEXT NOT NULL,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS email_flags (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            graph_message_id TEXT UNIQUE NOT NULL,
            conversation_id TEXT,
            from_name TEXT,
            from_address TEXT,
            subject TEXT,
            preview TEXT,
            web_link TEXT,
            received_at TEXT NOT NULL,
            unanswered INTEGER NOT NULL DEFAULT 0,
            price_conflict INTEGER NOT NULL DEFAULT 0,
            availability_conflict INTEGER NOT NULL DEFAULT 0,
            conflict_category TEXT,
            extracted_price REAL,
            computed_price REAL,
            extracted_dates TEXT,
            detail_note TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','dismissed')),
            resolved_at TEXT,
            resolved_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS promo_codes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT UNIQUE NOT NULL,
            description TEXT,
            discount_type TEXT NOT NULL DEFAULT 'percent' CHECK(discount_type IN ('percent','fixed')),
            discount_value REAL NOT NULL,
            max_discount_amount REAL,
            applies_to TEXT NOT NULL DEFAULT 'all' CHECK(applies_to IN ('all','room','restaurant','workshop')),
            min_spend REAL,
            max_redemptions INTEGER,
            redemption_count INTEGER NOT NULL DEFAULT 0,
            valid_from TEXT,
            valid_until TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS promo_code_redemptions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            promo_code_id INTEGER NOT NULL REFERENCES promo_codes(id) ON DELETE CASCADE,
            category TEXT NOT NULL CHECK(category IN ('room','restaurant','workshop')),
            booking_reference TEXT,
            guest_email TEXT,
            original_amount REAL,
            discount_amount REAL,
            final_amount REAL,
            redeemed_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS menu_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            category TEXT NOT NULL DEFAULT 'main' CHECK(category IN ('starter','main','dessert','drink')),
            dietary_tags TEXT,
            price REAL,
            active INTEGER NOT NULL DEFAULT 1,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS restaurant_settings (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            opening_date TEXT,
            dinner_time TEXT NOT NULL DEFAULT '19:30',
            capacity INTEGER NOT NULL DEFAULT 20,
            price_per_person REAL,
            lead_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            profit_share_percent REAL NOT NULL DEFAULT 50,
            enabled INTEGER NOT NULL DEFAULT 1,
            updated_at TEXT
        );

        CREATE TABLE IF NOT EXISTS restaurant_shifts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            dinner_date TEXT NOT NULL,
            role_note TEXT,
            estimated_hours REAL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS restaurant_waitlist (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            phone TEXT,
            desired_date TEXT,
            party_size INTEGER,
            notes TEXT,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','contacted','booked','closed')),
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS restaurant_bookings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            reference_code TEXT UNIQUE NOT NULL,
            manage_token TEXT UNIQUE NOT NULL,
            guest_name TEXT NOT NULL,
            guest_email TEXT NOT NULL,
            guest_phone TEXT,
            party_size INTEGER NOT NULL DEFAULT 2,
            dinner_date TEXT NOT NULL,
            dietary_notes TEXT,
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled')),
            total_price REAL,
            booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
            created_at TEXT NOT NULL,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS extras (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            price REAL NOT NULL DEFAULT 0,
            active INTEGER NOT NULL DEFAULT 1,
            sort_order INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS automation_runs (
            job_name TEXT PRIMARY KEY,
            last_ran_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assigned_to_user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
            title TEXT NOT NULL,
            notes TEXT,
            room_note TEXT,
            due_date TEXT,
            priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done')),
            created_at TEXT NOT NULL,
            completed_at TEXT,
            repeat_weekly INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS rooms (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT NOT NULL DEFAULT '',
            max_occupancy INTEGER NOT NULL DEFAULT 2,
            price_per_night REAL NOT NULL DEFAULT 0,
            active INTEGER NOT NULL DEFAULT 1,
            export_token TEXT NOT NULL,
            sort_order INTEGER NOT NULL DEFAULT 0,
            photo_filename TEXT,
            amenities TEXT
        );

        CREATE TABLE IF NOT EXISTS room_rate_overrides (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            price_per_night REAL NOT NULL,
            label TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS deposit_rules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL CHECK(category IN ('restaurant','workshop')),
            start_date TEXT,
            end_date TEXT,
            min_party_size INTEGER,
            deposit_percent REAL NOT NULL,
            label TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS restaurant_rate_overrides (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            price_per_person REAL NOT NULL,
            label TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS room_photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            filename TEXT NOT NULL,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS ical_sources (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            label TEXT NOT NULL,
            url TEXT NOT NULL,
            last_synced_at TEXT,
            last_sync_error TEXT
        );

        CREATE TABLE IF NOT EXISTS blocked_dates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            ical_source_id INTEGER REFERENCES ical_sources(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS shifts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            shift_date TEXT NOT NULL,
            start_time TEXT,
            end_time TEXT,
            role_note TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS timesheet_corrections (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            time_entry_id INTEGER NOT NULL REFERENCES time_entries(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            note TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','resolved','dismissed')),
            created_at TEXT NOT NULL,
            resolved_at TEXT
        );

        CREATE TABLE IF NOT EXISTS shift_swaps (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            shift_id INTEGER NOT NULL REFERENCES shifts(id) ON DELETE CASCADE,
            requested_by_user_id INTEGER NOT NULL REFERENCES users(id),
            offered_to_user_id INTEGER NOT NULL REFERENCES users(id),
            status TEXT NOT NULL DEFAULT 'pending'
                CHECK(status IN ('pending','accepted','declined','approved','rejected')),
            note TEXT,
            requested_at TEXT NOT NULL,
            responded_at TEXT,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS leave_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            reason TEXT,
            leave_type TEXT NOT NULL DEFAULT 'vacation',
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined','cancelled')),
            owner_note TEXT,
            requested_at TEXT NOT NULL,
            decided_at TEXT
        );

        CREATE TABLE IF NOT EXISTS ical_sync_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ical_source_id INTEGER NOT NULL REFERENCES ical_sources(id) ON DELETE CASCADE,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            ran_at TEXT NOT NULL,
            success INTEGER NOT NULL,
            added INTEGER NOT NULL DEFAULT 0,
            removed INTEGER NOT NULL DEFAULT 0,
            unchanged INTEGER NOT NULL DEFAULT 0,
            error TEXT
        );

        CREATE TABLE IF NOT EXISTS room_blocks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            reason TEXT,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS bookings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL REFERENCES rooms(id),
            reference_code TEXT UNIQUE NOT NULL,
            manage_token TEXT UNIQUE NOT NULL,
            guest_name TEXT NOT NULL,
            guest_email TEXT NOT NULL,
            guest_phone TEXT,
            arrival_date TEXT NOT NULL,
            departure_date TEXT NOT NULL,
            party_size INTEGER NOT NULL DEFAULT 1,
            special_requests TEXT,
            status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled')),
            total_price REAL,
            owner_note TEXT,
            created_at TEXT NOT NULL,
            decided_at TEXT,
            linked_guest_id INTEGER REFERENCES guests(id) ON DELETE SET NULL,
            checked_out_at TEXT,
            extras_summary TEXT,
            payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')),
            stripe_session_id TEXT,
            stripe_payment_intent_id TEXT
        );
        """
    )
