def role_compliance(conn, today):
    """Who does not hold what their job role requires.

    Certifications and documents were already tracked per person, but nothing
    said what a ROLE demands — so the system could answer "what expires soon"
    and never "who cannot legally work this week". Requirements are matched on
    name, case-insensitively, because that is how they are actually typed in.

    Each person gets one row per unmet requirement, with `state` one of
    missing / expired / expiring, worst first.
    """
    reqs = conn.execute("SELECT * FROM role_requirements ORDER BY job_role, requirement").fetchall()
    if not reqs:
        return []
    by_role = {}
    for r in reqs:
        by_role.setdefault((r["job_role"] or "").strip().lower(), []).append(r)

    people = conn.execute(
        "SELECT id, name, job_role FROM users WHERE role = 'employee' AND status = 'active'"
    ).fetchall()
    horizon = (today + timedelta(days=30)).isoformat()
    out = []
    for p in people:
        needed = by_role.get((p["job_role"] or "").strip().lower())
        if not needed:
            continue
        certs = {(" ".join((c["name"] or "").split())).lower(): c for c in conn.execute(
            "SELECT name, expiry_date FROM certifications WHERE user_id = ?", (p["id"],)).fetchall()}
        docs = {(" ".join((d["title"] or "").split())).lower(): d for d in conn.execute(
            "SELECT title, expiry_date FROM documents WHERE user_id = ?", (p["id"],)).fetchall()}
        for req in needed:
            pool = certs if req["requirement_type"] == "certification" else docs
            held = pool.get((" ".join((req["requirement"] or "").split())).lower())
            if not held:
                state, detail = "missing", "not on file"
            elif held["expiry_date"] and held["expiry_date"] < today.isoformat():
                state, detail = "expired", f"expired {held['expiry_date']}"
            elif held["expiry_date"] and held["expiry_date"] <= horizon:
                state, detail = "expiring", f"expires {held['expiry_date']}"
            else:
                continue
            out.append({"user_id": p["id"], "name": p["name"], "job_role": p["job_role"],
                        "requirement": req["requirement"],
                        "requirement_type": req["requirement_type"],
                        "state": state, "detail": detail})
    order = {"missing": 0, "expired": 1, "expiring": 2}
    return sorted(out, key=lambda x: (order[x["state"]], x["name"]))


# ---------------------------------------------------------------------------
# The rota against everything else the system already knows.
#
# Each of these is one fact checked against another fact, both of which were
# already recorded and never compared. Leave gets approved and the rota still
# shows the person on. An absence is entered and the shift it covers stays
# assigned. A certificate lapses on the 14th and somebody is rostered to work
# a role that requires it on the 15th.
#
# None of that fails loudly. The rota renders, the shift looks staffed, and
# the first anyone knows is the morning nobody arrives — or an inspection.
# ---------------------------------------------------------------------------

ROTA_CONFLICT_KINDS = {
    "leave": "Approved leave",
    "absence": "Recorded absence",
    "certification": "Cannot legally work this",
}


def rota_conflicts(conn, start, end):
    """Shifts that clash with something else on record, soonest first.

    `start`/`end` are inclusive dates. Returns one row per clash, carrying
    the shift, the person and what it collides with, so a caller can render
    it without going back to the database.

    Deliberately reads the rota rather than worked time: the point is to
    catch this BEFORE the day, while there is still time to move somebody.
    The working-time checker does the opposite job, after the fact.
    """
    if isinstance(start, str):
        start = parse_date(start)
    if isinstance(end, str):
        end = parse_date(end)
    if not start or not end or end < start:
        return []

    shifts = conn.execute(
        """SELECT shifts.*, users.name AS employee_name, users.job_role
             FROM shifts JOIN users ON users.id = shifts.user_id
            WHERE shifts.shift_date >= ? AND shifts.shift_date <= ?
            ORDER BY shifts.shift_date, shifts.start_time""",
        (start.isoformat(), end.isoformat()),
    ).fetchall()
    if not shifts:
        return []

    lo, hi = start.isoformat(), end.isoformat()

    # Approved leave only. A pending request is not yet a clash — declining it
    # is a perfectly good resolution, and flagging it would train people to
    # ignore the list.
    leave = conn.execute(
        """SELECT * FROM leave_requests
            WHERE status = 'approved' AND start_date <= ? AND end_date >= ?""",
        (hi, lo),
    ).fetchall()
    absences = conn.execute(
        """SELECT * FROM absences WHERE start_date <= ? AND end_date >= ?""",
        (hi, lo),
    ).fetchall()

    by_user_leave, by_user_absence = {}, {}
    for r in leave:
        by_user_leave.setdefault(r["user_id"], []).append(r)
    for r in absences:
        by_user_absence.setdefault(r["user_id"], []).append(r)

    # Compliance is asked as at the SHIFT's date, not today: a certificate
    # that is valid now and expires on the 14th does not cover the 15th, and
    # asking "is this person compliant today" would miss exactly that.
    # Memoised because a month of shifts shares very few distinct dates.
    compliance_on = {}

    def unmet_on(day):
        key = day.isoformat()
        if key not in compliance_on:
            by_person = {}
            for row in role_compliance(conn, day):
                # 'expiring' is a warning about the future, not a bar on
                # working. Only missing and expired stop somebody.
                if row["state"] in ("missing", "expired"):
                    by_person.setdefault(row["user_id"], []).append(row)
            compliance_on[key] = by_person
        return compliance_on[key]

    def covers(row, day):
        return (row["start_date"] or "") <= day <= (row["end_date"] or "")

    out = []
    for sh in shifts:
        day = sh["shift_date"]
        base = {
            "shift_id": sh["id"], "user_id": sh["user_id"],
            "employee_name": sh["employee_name"], "job_role": sh["job_role"],
            "shift_date": day, "start_time": sh["start_time"],
            "end_time": sh["end_time"], "role_note": sh["role_note"],
        }

        for lv in by_user_leave.get(sh["user_id"], []):
            if covers(lv, day):
                out.append(dict(base, kind="leave", severity="blocker",
                                detail=(f"{sh['employee_name']} has approved "
                                        f"{(lv['leave_type'] or 'leave').replace('_', ' ')} "
                                        f"from {lv['start_date']} to {lv['end_date']}."),
                                ref_id=lv["id"]))

        for ab in by_user_absence.get(sh["user_id"], []):
            if covers(ab, day):
                out.append(dict(base, kind="absence", severity="blocker",
                                detail=(f"{sh['employee_name']} is recorded absent "
                                        f"({(ab['kind'] or 'absence').replace('_', ' ')}) "
                                        f"from {ab['start_date']} to {ab['end_date']}."),
                                ref_id=ab["id"]))

        d = parse_date(day)
        if d:
            for req in unmet_on(d).get(sh["user_id"], []):
                out.append(dict(base, kind="certification", severity="blocker",
                                detail=(f"{req['requirement']} is {req['detail']} — "
                                        f"required for {req['job_role']}."),
                                ref_id=req.get("user_id")))

    order = {"certification": 0, "leave": 1, "absence": 2}
    out.sort(key=lambda r: (r["shift_date"], order.get(r["kind"], 9),
                            r["employee_name"] or ""))
    return out


# The French standard week. Hours beyond it are majorées, which is a payroll
# matter this app deliberately does not compute — see the note in the page.
STANDARD_WEEK_HOURS = 35.0

# Long weeks in a row before it stops being a bad week and starts being how
# the house runs. Three is a judgement, not a rule, and it is stated as one.
CHRONIC_WEEKS = 3


def overtime_history(conn, *, weeks=12, today=None, threshold=STANDARD_WEEK_HOURS):
    """Week by week: who went past the standard week, and what was on.

    Weeks are Monday-start local, matching how a rota is written and how
    week_overtime already counts, so the two can never disagree about which
    week a Sunday night belongs to.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    this_monday = today - timedelta(days=today.weekday())
    first_monday = this_monday - timedelta(weeks=weeks - 1)

    start_utc = datetime.combine(first_monday, datetime.min.time(),
                                 tzinfo=LOCAL_TZ).astimezone(timezone.utc)
    end_utc = datetime.combine(this_monday + timedelta(days=7), datetime.min.time(),
                               tzinfo=LOCAL_TZ).astimezone(timezone.utc)

    rows = conn.execute(
        """SELECT time_entries.*, users.name AS employee_name FROM time_entries
             JOIN users ON users.id = time_entries.user_id
            WHERE clock_in_at >= ? AND clock_in_at < ? AND clock_out_at IS NOT NULL
              AND users.role = 'employee'""",
        (start_utc.isoformat(), end_utc.isoformat())).fetchall()
    hours_by_entry = net_hours_for_entries(conn, rows)

    # {monday_iso: {user_id: {"name": .., "hours": ..}}}
    by_week = {}
    for r in rows:
        started = parse_datetime_iso(r["clock_in_at"])
        if not started:
            continue
        local_day = started.astimezone(LOCAL_TZ).date()
        monday = local_day - timedelta(days=local_day.weekday())
        bucket = by_week.setdefault(monday.isoformat(), {})
        person = bucket.setdefault(r["user_id"],
                                   {"name": r["employee_name"], "hours": 0.0})
        person["hours"] += hours_by_entry.get(r["id"], 0.0)

    out = []
    for i in range(weeks):
        monday = first_monday + timedelta(weeks=i)
        iso = monday.isoformat()
        sunday = monday + timedelta(days=6)
        people = by_week.get(iso, {})
        over = [{"user_id": uid, "name": v["name"], "hours": round(v["hours"], 2),
                 "extra": round(v["hours"] - threshold, 2)}
                for uid, v in people.items() if v["hours"] > threshold]
        over.sort(key=lambda p: -p["extra"])
        out.append({
            "week_start": iso, "week_end": sunday.isoformat(),
            "over": over,
            "extra_hours": round(sum(p["extra"] for p in over), 2),
            "worked_hours": round(sum(v["hours"] for v in people.values()), 2),
            "on": week_activity(conn, monday, sunday),
        })

    # Somebody long several weeks running is a different problem from somebody
    # long once, and only one of them is fixed by a conversation.
    chronic, run = {}, {}
    for week in out:
        long_this_week = {p["user_id"] for p in week["over"]}
        for uid in list(run):
            if uid not in long_this_week:
                run.pop(uid)
        for p in week["over"]:
            run[p["user_id"]] = run.get(p["user_id"], 0) + 1
            if run[p["user_id"]] >= CHRONIC_WEEKS:
                chronic[p["user_id"]] = {"name": p["name"],
                                         "weeks": run[p["user_id"]]}

    return {
        "weeks": out,
        "total_extra": round(sum(w["extra_hours"] for w in out), 2),
        "weeks_with_any": len([w for w in out if w["over"]]),
        "chronic": sorted(chronic.values(), key=lambda c: -c["weeks"]),
        "threshold": threshold,
    }


def week_activity(conn, monday, sunday):
    """What the house was doing in a week, in one short line.

    Correlation and nothing more: a busy week and a long week appearing
    together does not prove one caused the other, and the page says so. It is
    here so somebody who knows the house can recognise the pattern.
    """
    lo, hi = monday.isoformat(), sunday.isoformat()
    bits = []
    beds = conn.execute(
        """SELECT COUNT(*) AS n FROM bookings
            WHERE status = 'confirmed' AND arrival_date <= ? AND departure_date >= ?""",
        (hi, lo)).fetchone()["n"]
    if beds:
        bits.append(f"{beds} stay{'s' if beds != 1 else ''}")
    covers = conn.execute(
        """SELECT COALESCE(SUM(party_size), 0) AS c FROM restaurant_bookings
            WHERE status = 'confirmed' AND dinner_date BETWEEN ? AND ?""",
        (lo, hi)).fetchone()["c"]
    if covers:
        bits.append(f"{covers} covers")
    for r in conn.execute(
        """SELECT workshops.title FROM workshop_sessions
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_sessions.start_date <= ?
              AND COALESCE(workshop_sessions.end_date, workshop_sessions.start_date) >= ?""",
            (hi, lo)).fetchall():
        bits.append(r["title"])
    events = conn.execute(
        """SELECT COUNT(*) AS n FROM event_inquiries
            WHERE status = 'confirmed'
              AND COALESCE(preferred_date, '') BETWEEN ? AND ?""",
        (lo, hi)).fetchone()["n"]
    if events:
        bits.append(f"{events} event{'s' if events != 1 else ''}")
    return ", ".join(bits)


def _guest_key(email):
    """The one place an email becomes a guest identity.

    Normalised, because "Ben@Chateau.com" and "ben@chateau.com " are one
    person and were two — which for a repeat guest splits their history and
    halves their spend on every figure that touches it.
    """
    return " ".join((email or "").split()).casefold()


# Long enough that a normal loan is not nagged about, short enough that a
# forgotten one surfaces while somebody still remembers issuing it.
LOAN_STALE_DAYS = 90


def things_still_out(conn, *, today=None):
    """Keys, fobs and kit issued and not returned, worst first.

    "Worst" is not oldest. A key held by somebody who has left the house
    outranks a laptop lent last week however long each has been gone, because
    one is a person who can still open a door.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    out = []

    def age(stamp):
        d = parse_datetime_iso(stamp) or (parse_date((stamp or "")[:10]) and
                                          datetime.combine(parse_date(stamp[:10]),
                                                           datetime.min.time(),
                                                           tzinfo=timezone.utc))
        if not d:
            return None
        return (today - d.astimezone(LOCAL_TZ).date()).days

    for r in conn.execute(
        """SELECT access_holdings.id, access_holdings.issued_at, access_holdings.notes,
                  access_holdings.holder_name, access_items.label, access_items.kind,
                  users.id AS user_id, users.name AS holder, users.status AS holder_status
             FROM access_holdings
             JOIN access_items ON access_items.id = access_holdings.access_item_id
             LEFT JOIN users ON users.id = access_holdings.user_id
            WHERE access_holdings.returned_at IS NULL""").fetchall():
        out.append({
            "sort": "access", "id": r["id"], "what": r["label"],
            "kind": r["kind"] or "access",
            "who": r["holder"] or r["holder_name"] or "—",
            "user_id": r["user_id"],
            "gone": bool(r["user_id"]) and r["holder_status"] != "active",
            "days": age(r["issued_at"]), "issued_at": r["issued_at"],
            "note": r["notes"],
        })

    for r in conn.execute(
        """SELECT equipment_items.id, equipment_items.label, equipment_items.notes,
                  equipment_items.issued_at, users.id AS user_id, users.name AS holder,
                  users.status AS holder_status
             FROM equipment_items
             JOIN users ON users.id = equipment_items.user_id
            WHERE equipment_items.returned_at IS NULL""").fetchall():
        out.append({
            "sort": "equipment", "id": r["id"], "what": r["label"], "kind": "kit",
            "who": r["holder"] or "—", "user_id": r["user_id"],
            "gone": r["holder_status"] != "active",
            "days": age(r["issued_at"]), "issued_at": r["issued_at"],
            "note": r["notes"],
        })

    for row in out:
        row["stale"] = bool(row["days"] and row["days"] > LOAN_STALE_DAYS)

    out.sort(key=lambda r: (not r["gone"], -(r["days"] or 0)))
    return {
        # "lent" rather than "items": in Jinja, data.items on a dict resolves
        # to the dict's own .items method and renders as a bound method
        # repr — or, in a for loop, iterates key/value pairs. It fails in a
        # way that looks like a template bug rather than a naming one.
        "lent": out,
        "with_leavers": [r for r in out if r["gone"]],
        "stale": [r for r in out if r["stale"] and not r["gone"]],
        "people": len({r["user_id"] for r in out if r["user_id"]}),
    }


def offboarding_contradictions(conn):
    """People whose leaving checklist says returned, while the register says out.

    offboarding_items is free text with no link to either register, so ticking
    "hand back keys" proves only that somebody ticked it. Where the two
    disagree the register is the one to believe: it names the specific fob.

    Matched on the words in the checklist line, which is as good as free text
    allows and no better — a line worded "sort out the office" covers a laptop
    and this will not know.
    """
    words = {"key", "keys", "fob", "fobs", "badge", "alarm", "code", "codes",
             "laptop", "phone", "kit", "equipment", "uniform", "access"}
    still_out = things_still_out(conn)
    by_user = {}
    for r in still_out["lent"]:
        if r["user_id"]:
            by_user.setdefault(r["user_id"], []).append(r)
    if not by_user:
        return []

    marks = ",".join("?" * len(by_user))
    out = []
    for r in conn.execute(
        f"""SELECT offboarding_items.user_id, offboarding_items.label,
                   users.name, users.status
              FROM offboarding_items JOIN users ON users.id = offboarding_items.user_id
             WHERE offboarding_items.done = 1
               AND offboarding_items.user_id IN ({marks})""",
            list(by_user)).fetchall():
        label = (r["label"] or "").casefold()
        if not any(w in label.split() or w in label for w in words):
            continue
        out.append({
            "user_id": r["user_id"], "name": r["name"],
            "status": r["status"], "ticked": r["label"],
            "still_out": by_user[r["user_id"]],
        })
    # One row per person, however many checklist lines they ticked.
    seen, unique = set(), []
    for r in out:
        if r["user_id"] in seen:
            continue
        seen.add(r["user_id"])
        unique.append(r)
    return unique


def room_economics(conn, *, months=12, today=None):
    """Per room: nights sold, what the room itself earned, and how full it was.

    Nights are counted inside the window rather than by whole stay, so a
    booking spanning the boundary contributes only the nights that fall in
    it — otherwise a long stay in January would land entirely in whichever
    month the report happened to start.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    start = _add_months(today.replace(day=1), -months + 1)
    end = today
    if end < start:
        return {"rooms": [], "window": (start.isoformat(), end.isoformat())}
    window_nights = (end - start).days or 1

    rooms = {r["id"]: {
        "id": r["id"], "name": r["name"], "price_per_night": r["price_per_night"],
        "active": bool(r["active"]), "nights": 0, "room_revenue": 0.0,
        "extras_revenue": 0.0, "stays": 0, "guests": 0, "open_faults": 0,
    } for r in conn.execute("SELECT * FROM rooms").fetchall()}

    # Extras per booking, so the room's own earnings can be separated from
    # what was sold alongside it.
    extras = {}
    for r in conn.execute(
        """SELECT booking_id, COALESCE(SUM(unit_price * COALESCE(quantity, 1)), 0) AS total
             FROM booking_extras
            WHERE COALESCE(status, '') != 'cancelled'
            GROUP BY booking_id""").fetchall():
        extras[r["booking_id"]] = r["total"] or 0.0

    for b in conn.execute(
        """SELECT id, room_id, arrival_date, departure_date, party_size,
                  COALESCE(total_price, 0) AS total_price
             FROM bookings
            WHERE status = 'confirmed' AND departure_date >= ? AND arrival_date <= ?""",
        (start.isoformat(), end.isoformat())).fetchall():
        room = rooms.get(b["room_id"])
        if not room:
            continue
        a, z = parse_date(b["arrival_date"]), parse_date(b["departure_date"])
        if not (a and z) or z <= a:
            continue
        stay_nights = (z - a).days
        # Only the nights inside the window.
        counted = (min(z, end + timedelta(days=1)) - max(a, start)).days
        if counted <= 0:
            continue

        extras_total = extras.get(b["id"], 0.0)
        room_total = max(0.0, b["total_price"] - extras_total)
        share = counted / stay_nights

        room["nights"] += counted
        room["room_revenue"] += room_total * share
        room["extras_revenue"] += extras_total * share
        room["stays"] += 1
        room["guests"] += (b["party_size"] or 0)

    for r in conn.execute(
        "SELECT room_id, COUNT(*) AS n FROM room_issues WHERE status = 'open' GROUP BY room_id"
    ).fetchall():
        if r["room_id"] in rooms:
            rooms[r["room_id"]]["open_faults"] = r["n"]

    out = []
    for room in rooms.values():
        room["room_revenue"] = round(room["room_revenue"], 2)
        room["extras_revenue"] = round(room["extras_revenue"], 2)
        room["nightly"] = (round(room["room_revenue"] / room["nights"], 2)
                           if room["nights"] else None)
        room["occupancy"] = round(100 * room["nights"] / window_nights, 1)
        # What it would have earned at the asking price every night it sold.
        # Not a target — the gap is discounts, seasons and negotiated rates,
        # and it is only interesting next to the other rooms.
        room["list_rate"] = room["price_per_night"]
        out.append(room)

    out.sort(key=lambda r: -r["room_revenue"])
    live = [r for r in out if r["active"]]
    return {
        "rooms": out,
        "window": (start.isoformat(), end.isoformat()),
        "window_nights": window_nights,
        "room_revenue": round(sum(r["room_revenue"] for r in out), 2),
        "extras_revenue": round(sum(r["extras_revenue"] for r in out), 2),
        "nights": sum(r["nights"] for r in out),
        "never_sold": [r for r in live if not r["nights"]],
    }


def repeat_guests(conn, *, today=None, min_stays=2):
    """Everyone who has stayed more than once, and whether they are overdue.

    Spend covers rooms, the table and ateliers, because a guest who comes for
    one night and eats here four times is a regular by any reading that
    matters.
    """
    today = today or datetime.now(LOCAL_TZ).date()

    people = {}

    def entry(email, name):
        key = _guest_key(email)
        e = people.setdefault(key, {
            "key": key, "email": email, "name": name, "stays": [],
            "spend": 0.0, "dinners": 0, "workshops": 0, "ratings": [],
            "spellings": set(),
        })
        if email:
            e["spellings"].add(email.strip())
        # The most recently seen spelling of a name wins; people marry, and
        # the newest is the one to greet them by.
        if name:
            e["name"] = name
        return e

    for r in conn.execute(
        """SELECT guest_email, guest_name, arrival_date, departure_date,
                  COALESCE(total_price, 0) AS price
             FROM bookings
            WHERE status = 'confirmed' AND guest_email IS NOT NULL
            ORDER BY arrival_date""").fetchall():
        e = entry(r["guest_email"], r["guest_name"])
        e["stays"].append({"arrival": r["arrival_date"],
                           "departure": r["departure_date"],
                           "price": r["price"]})
        e["spend"] += r["price"]

    for r in conn.execute(
        """SELECT guest_email, guest_name, COALESCE(total_price, 0) AS price
             FROM restaurant_bookings
            WHERE status = 'confirmed' AND guest_email IS NOT NULL""").fetchall():
        e = entry(r["guest_email"], r["guest_name"])
        e["dinners"] += 1
        e["spend"] += r["price"]

    for r in conn.execute(
        """SELECT guest_email, guest_name, COALESCE(total_price, 0) AS price
             FROM workshop_bookings
            WHERE status NOT IN ('declined', 'cancelled')
              AND guest_email IS NOT NULL""").fetchall():
        e = entry(r["guest_email"], r["guest_name"])
        e["workshops"] += 1
        e["spend"] += r["price"]

    for r in conn.execute(
        """SELECT bookings.guest_email, guest_feedback.rating
             FROM guest_feedback JOIN bookings ON bookings.id = guest_feedback.booking_id
            WHERE guest_feedback.rating IS NOT NULL""").fetchall():
        key = _guest_key(r["guest_email"])
        if key in people:
            people[key]["ratings"].append(r["rating"])

    out = []
    for e in people.values():
        if len(e["stays"]) < min_stays:
            continue
        arrivals = sorted(parse_date(s["arrival"]) for s in e["stays"]
                          if parse_date(s["arrival"]))
        if not arrivals:
            continue
        last = arrivals[-1]
        gaps = [(b - a).days for a, b in zip(arrivals, arrivals[1:])]
        # Median, not mean: one unusual gap should not redefine the rhythm.
        typical = sorted(gaps)[len(gaps) // 2] if gaps else None
        since = (today - last).days

        # Overdue against their own habit, with a margin so somebody a
        # fortnight late is not chased. Only ever said about a guest with a
        # rhythm to be late against.
        overdue = bool(typical and since > typical * 1.5 and since > 180)

        out.append({
            "key": e["key"], "email": e["email"], "name": e["name"],
            "stays": len(e["stays"]), "spend": round(e["spend"], 2),
            "dinners": e["dinners"], "workshops": e["workshops"],
            "first": arrivals[0].isoformat(), "last": last.isoformat(),
            "days_since": since, "typical_gap": typical,
            "overdue": overdue,
            "rating": (round(sum(e["ratings"]) / len(e["ratings"]), 1)
                       if e["ratings"] else None),
            "spellings": sorted(e["spellings"]),
        })

    out.sort(key=lambda g: (-g["stays"], -g["spend"]))
    return {
        "guests": out,
        "overdue": [g for g in out if g["overdue"]],
        "total_spend": round(sum(g["spend"] for g in out), 2),
        "split_emails": [g for g in out if len(g["spellings"]) > 1],
    }


def parse_skills(text):
    """Free text to a list of (key, display) pairs, in the order written.

    Split on commas and newlines only. Splitting on spaces as well would turn
    "pool chemicals" into two skills nobody has.
    """
    if not text:
        return []
    out, seen = [], set()
    for piece in re.split(r"[,;\n]", text):
        display = " ".join(piece.split())
        if not display:
            continue
        key = display.casefold()
        if key in seen:
            continue
        seen.add(key)
        out.append((key, display))
    return out


def skill_matrix(conn, *, include_inactive=False):
    """Every skill anybody has, and who has it.

    `spellings` carries each distinct way a skill has been typed. One skill
    written three ways is one row here with three spellings listed, because
    hiding that would make a typo look like a colleague.
    """
    where = "" if include_inactive else "AND users.status = 'active'"
    rows = conn.execute(
        f"""SELECT id, name, job_role, skills FROM users
             WHERE role = 'employee' {where.replace('users.', '')}
             ORDER BY name""").fetchall()

    skills = {}
    for r in rows:
        for key, display in parse_skills(r["skills"]):
            entry = skills.setdefault(key, {"people": [], "spellings": {}})
            entry["people"].append({"id": r["id"], "name": r["name"],
                                    "job_role": r["job_role"]})
            entry["spellings"][display] = entry["spellings"].get(display, 0) + 1

    out = []
    for key, entry in skills.items():
        # The most common spelling wins, ties broken alphabetically. Taking
        # whichever was encountered first makes the label depend on the order
        # people happen to be listed in, so the same page can name a skill two
        # different ways between loads — the exact bug the supplier report had.
        display = sorted(entry["spellings"].items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
        out.append({"key": key, "display": display,
                    "people": entry["people"], "count": len(entry["people"]),
                    "spellings": sorted(entry["spellings"])})
    out.sort(key=lambda s: (s["count"], s["display"].casefold()))
    return {
        "skills": out,
        "people": len(rows),
        "without_any": [r["name"] for r in rows if not parse_skills(r["skills"])],
        # The question the field was always able to answer and never asked:
        # if this person is away, nobody can do this at all.
        "held_by_one": [s for s in out if s["count"] == 1],
    }


def who_could_cover(conn, day, *, skill=None):
    """Active employees with nothing on the rota that day, and free to work it.

    Not a recommendation — it does not know who is willing, who is nearby, or
    whose day off it is by arrangement rather than by record. It answers the
    narrower question the app can actually answer: who is not already booked,
    not on leave and not recorded absent.
    """
    if isinstance(day, str):
        day = parse_date(day)
    if not day:
        return []
    iso = day.isoformat()

    busy = {r["user_id"] for r in conn.execute(
        "SELECT DISTINCT user_id FROM shifts WHERE shift_date = ?", (iso,)).fetchall()}
    for table, extra in (("leave_requests", "AND status = 'approved'"),
                         ("absences", "")):
        for r in conn.execute(
            f"""SELECT user_id FROM {table}
                 WHERE start_date <= ? AND end_date >= ? {extra}""",
                (iso, iso)).fetchall():
            busy.add(r["user_id"])

    want = (skill or "").strip().casefold() or None
    out = []
    for r in conn.execute(
        """SELECT id, name, job_role, skills FROM users
            WHERE role = 'employee' AND status = 'active' ORDER BY name""").fetchall():
        if r["id"] in busy:
            continue
        theirs = parse_skills(r["skills"])
        if want and want not in {k for k, _d in theirs}:
            continue
        out.append({"user_id": r["id"], "name": r["name"], "job_role": r["job_role"],
                    "skills": [d for _k, d in theirs]})
    return out


def rota_vs_clock(conn, start, end, *, today=None):
    """Days where the rota and the clock tell different stories.

    Past days only: a shift tomorrow is not yet anything. Days the person
    was on approved leave or recorded absent are skipped — the rota being
    wrong about those is already the rota-clash page's job, and saying it
    twice in different words trains people to ignore both.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    if isinstance(start, str):
        start = parse_date(start)
    if isinstance(end, str):
        end = parse_date(end)
    if not start or not end:
        return []
    end = min(end, today - timedelta(days=1))      # yesterday at the latest
    if end < start:
        return []
    lo, hi = start.isoformat(), end.isoformat()

    rostered = {}
    for r in conn.execute(
        """SELECT shifts.*, users.name AS employee_name FROM shifts
             JOIN users ON users.id = shifts.user_id
            WHERE shifts.shift_date BETWEEN ? AND ?""", (lo, hi)).fetchall():
        rostered.setdefault((r["user_id"], r["shift_date"]), []).append(r)

    # Clock entries bucketed by the LOCAL day they started on, because a
    # shift is planned in local time and clock_in_at is stored in UTC — an
    # evening shift would otherwise land on the following day.
    worked = {}
    for r in conn.execute(
        """SELECT time_entries.*, users.name AS employee_name FROM time_entries
             JOIN users ON users.id = time_entries.user_id
            WHERE time_entries.clock_in_at >= ? AND time_entries.clock_in_at < ?""",
        (start.isoformat(), (end + timedelta(days=2)).isoformat())).fetchall():
        started = parse_datetime_iso(r["clock_in_at"])
        if not started:
            continue
        day = started.astimezone(LOCAL_TZ).date()
        if lo <= day.isoformat() <= hi:
            worked.setdefault((r["user_id"], day.isoformat()), []).append(r)

    # Anybody legitimately away. Their rota being wrong is a clash, not a
    # missing clock-in, and it is already reported as one.
    away = set()
    for table, s_col, e_col, extra in (
            ("leave_requests", "start_date", "end_date", "AND status = 'approved'"),
            ("absences", "start_date", "end_date", "")):
        for r in conn.execute(
            f"""SELECT user_id, {s_col} AS a, {e_col} AS b FROM {table}
                 WHERE {s_col} <= ? AND {e_col} >= ? {extra}""", (hi, lo)).fetchall():
            a, b = parse_date(r["a"]), parse_date(r["b"])
            if not (a and b):
                continue
            d = max(a, start)
            while d <= min(b, end):
                away.add((r["user_id"], d.isoformat()))
                d += timedelta(days=1)

    out = []
    for key, shifts in rostered.items():
        if key in worked or key in away:
            continue
        sh = shifts[0]
        out.append({
            "kind": "no_clock", "user_id": key[0], "date": key[1],
            "employee_name": sh["employee_name"],
            "planned": f"{sh['start_time'] or '?'}–{sh['end_time'] or '?'}",
            "role_note": sh["role_note"],
            "detail": "Rostered, but the clock has no entry for that day.",
        })

    for key, entries in worked.items():
        if key in rostered:
            continue
        e = entries[0]
        hours = sum(net_hours_for_entries(conn, entries).values())
        out.append({
            "kind": "no_shift", "user_id": key[0], "date": key[1],
            "employee_name": e["employee_name"],
            "planned": None, "role_note": None,
            "hours": round(hours, 2),
            "detail": (f"Clocked {hours:.1f}h with nothing on the rota for that day."
                       if hours else "Clocked in with nothing on the rota for that day."),
        })

    out.sort(key=lambda r: (r["date"], r["employee_name"] or ""), reverse=True)
    return out


def cover_gaps(conn, start, end):
    """What is happening each day, and who is actually on to do it.

    One row per day that has work. `people` counts distinct rostered staff,
    `blocked` those whose shift clashes with leave, absence or a lapsed
    requirement, and `effective` is what is left. A day with work and an
    effective count of zero is the gap.
    """
    if isinstance(start, str):
        start = parse_date(start)
    if isinstance(end, str):
        end = parse_date(end)
    if not start or not end or end < start:
        return []

    lo, hi = start.isoformat(), end.isoformat()
    days = {}

    def day(d):
        return days.setdefault(d, {
            "date": d, "arrivals": 0, "departures": 0, "in_house": 0,
            "covers": 0, "dinners": 0, "workshops": [], "people": set(),
            "blocked": set(), "shifts": [],
        })

    for r in conn.execute(
        """SELECT arrival_date, departure_date, party_size FROM bookings
            WHERE status = 'confirmed' AND departure_date >= ? AND arrival_date <= ?""",
        (lo, hi)).fetchall():
        a, dep = parse_date(r["arrival_date"]), parse_date(r["departure_date"])
        if a and lo <= r["arrival_date"] <= hi:
            day(r["arrival_date"])["arrivals"] += 1
        if dep and lo <= r["departure_date"] <= hi:
            day(r["departure_date"])["departures"] += 1
        # Guests already in the house still need somebody there, which is the
        # case a page built only on arrivals quietly misses.
        if a and dep:
            cur = max(a, start)
            while cur < min(dep, end + timedelta(days=1)):
                day(cur.isoformat())["in_house"] += r["party_size"] or 1
                cur += timedelta(days=1)

    for r in conn.execute(
        """SELECT dinner_date, COUNT(*) AS n, COALESCE(SUM(party_size), 0) AS covers
             FROM restaurant_bookings
            WHERE status = 'confirmed' AND dinner_date BETWEEN ? AND ?
            GROUP BY dinner_date""", (lo, hi)).fetchall():
        d = day(r["dinner_date"])
        d["dinners"] += r["n"]
        d["covers"] += r["covers"]

    for r in conn.execute(
        """SELECT workshops.title, workshop_sessions.start_date, workshop_sessions.end_date
             FROM workshop_sessions JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_sessions.start_date <= ?
              AND COALESCE(workshop_sessions.end_date, workshop_sessions.start_date) >= ?""",
        (hi, lo)).fetchall():
        a = parse_date(r["start_date"])
        z = parse_date(r["end_date"] or r["start_date"])
        if not (a and z):
            continue
        cur = max(a, start)
        while cur <= min(z, end):
            day(cur.isoformat())["workshops"].append(r["title"])
            cur += timedelta(days=1)

    for r in conn.execute(
        """SELECT shifts.*, users.name AS employee_name FROM shifts
             JOIN users ON users.id = shifts.user_id
            WHERE shifts.shift_date BETWEEN ? AND ?""", (lo, hi)).fetchall():
        d = day(r["shift_date"])
        d["people"].add(r["user_id"])
        d["shifts"].append({"user_id": r["user_id"], "name": r["employee_name"],
                            "start_time": r["start_time"], "end_time": r["end_time"]})

    # Rostered but unable to work it is not cover. Reuses the clash engine so
    # the two pages can never disagree about who is actually available.
    for c in rota_conflicts(conn, start, end):
        if c["shift_date"] in days:
            days[c["shift_date"]]["blocked"].add(c["user_id"])

    out = []
    for key in sorted(days):
        d = days[key]
        d["work"] = (d["arrivals"] + d["departures"] + d["dinners"]
                     + len(d["workshops"]) + (1 if d["in_house"] else 0))
        if not d["work"]:
            continue
        d["people_count"] = len(d["people"])
        d["blocked_count"] = len(d["blocked"] & d["people"])
        d["effective"] = d["people_count"] - d["blocked_count"]
        d["uncovered"] = d["effective"] <= 0
        d["workshops"] = sorted(set(d["workshops"]))
        d["people"], d["blocked"] = sorted(d["people"]), sorted(d["blocked"])
        out.append(d)
    return out


def rooms_sold_with_a_fault(conn, *, today=None, days=30):
    """Confirmed arrivals into a room that has an unresolved fault logged.

    Both halves are recorded and never compared: somebody logs that a shutter
    is broken, somebody else confirms a booking into that room, and the two
    facts sit in different tables until the guest finds out.

    Only unresolved faults, and only bookings that are actually confirmed —
    a pending request is not yet a promise, and flagging it would bury the
    ones that are.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    horizon = (today + timedelta(days=days)).isoformat()
    rows = conn.execute(
        """SELECT bookings.id AS booking_id, bookings.reference_code,
                  bookings.guest_name, bookings.arrival_date, bookings.departure_date,
                  rooms.id AS room_id, rooms.name AS room_name,
                  room_issues.id AS issue_id, room_issues.title, room_issues.description,
                  room_issues.created_at AS reported_at,
                  users.name AS reported_by
             FROM room_issues
             JOIN rooms ON rooms.id = room_issues.room_id
             JOIN bookings ON bookings.room_id = rooms.id
             LEFT JOIN users ON users.id = room_issues.reported_by_user_id
            WHERE room_issues.status = 'open'
              AND bookings.status = 'confirmed'
              AND bookings.departure_date >= ?
              AND bookings.arrival_date <= ?
            ORDER BY bookings.arrival_date, rooms.name""",
        (today.isoformat(), horizon),
    ).fetchall()
    out = []
    for r in rows:
        arrival = parse_date(r["arrival_date"])
        out.append(dict(r, days_away=(arrival - today).days if arrival else None,
                        in_house=bool(arrival and arrival <= today)))
    return out


# ---------------------------------------------------------------------------
# Money that was always recorded and never totalled.
# ---------------------------------------------------------------------------

def spend_by_vendor(conn, *, start=None, end=None):
    """What each supplier has actually been paid, most first.

    expenses.vendor_name is free text while vendors is a table, so the two are
    matched on a normalised name rather than a key. That match is reported
    rather than assumed: a supplier typed three ways is three rows here, and
    saying so is the only honest option — silently merging them would invent
    a total nobody can check, and silently splitting them hides the real one.
    """
    where, params = ["status IN ('approved', 'paid')"], []
    if start:
        where.append("submitted_at >= ?")
        params.append(start if isinstance(start, str) else start.isoformat())
    if end:
        where.append("submitted_at < ?")
        params.append(end if isinstance(end, str) else end.isoformat())

    rows = conn.execute(
        # vendor_name is taken from the row carrying MAX(submitted_at) — SQLite's
        # bare-column rule. Without that, the spelling shown for a supplier typed
        # more than one way is whichever row the group happened to yield, so the
        # same page can name them differently between two loads. The most recent
        # spelling is at least a decision somebody made.
        f"""SELECT vendor_name, COUNT(*) AS invoices,
                   COALESCE(SUM(amount), 0) AS total,
                   MIN(submitted_at) AS first_seen, MAX(submitted_at) AS last_seen
              FROM expenses
             WHERE {' AND '.join(where)}
             GROUP BY LOWER(TRIM(COALESCE(vendor_name, '')))
             ORDER BY total DESC""",
        params,
    ).fetchall()

    known = {(" ".join((v["name"] or "").split())).lower(): v
             for v in conn.execute("SELECT id, name FROM vendors").fetchall()}

    out, unnamed = [], None
    for r in rows:
        name = (r["vendor_name"] or "").strip()
        key = " ".join(name.split()).lower()
        display = known[key]["name"] if key in known else name
        row = {"vendor_name": display or "(not named)", "invoices": r["invoices"],
               "total": r["total"] or 0.0, "first_seen": r["first_seen"],
               "last_seen": r["last_seen"],
               "vendor_id": known[key]["id"] if key in known else None,
               "on_file": key in known}
        if not name:
            unnamed = row
        else:
            out.append(row)
    if unnamed:
        out.append(unnamed)

    # Standing costs are money going to the same suppliers and were invisible
    # here: an invoice gets totalled, a subscription that renews itself never
    # did. Reported alongside rather than added in — one is what has been paid,
    # the other is what will be, and adding them would answer neither question.
    committed = {}
    for r in conn.execute(
        """SELECT vendors.id, vendors.name, recurring_costs.label,
                  recurring_costs.amount, recurring_costs.frequency
             FROM recurring_costs
             JOIN vendors ON vendors.id = recurring_costs.vendor_id
            WHERE recurring_costs.active = 1""").fetchall():
        key = " ".join((r["name"] or "").split()).lower()
        yearly = (r["amount"] or 0) * (12 if r["frequency"] == "monthly" else 1)
        c = committed.setdefault(key, {"name": r["name"], "yearly": 0.0, "items": []})
        c["yearly"] += yearly
        c["items"].append(f"{r['label']} ({r['frequency']})")
    for row in out:
        c = committed.get(" ".join(row["vendor_name"].split()).lower())
        row["standing_yearly"] = c["yearly"] if c else 0.0
        row["standing_items"] = c["items"] if c else []

    total = sum(r["total"] for r in out)
    return {"rows": out, "total": total,
            "standing_total": sum(c["yearly"] for c in committed.values()),
            "vendors": len([r for r in out if r["vendor_name"] != "(not named)"]),
            "unmatched": [r for r in out if not r["on_file"]
                          and r["vendor_name"] != "(not named)"],
            "unnamed_total": unnamed["total"] if unnamed else 0.0}


def discount_cost(conn, *, start=None, end=None):
    """What was given away, by code — revenue that was earned and not taken.

    Read from promo_code_redemptions, which records the amount at the moment
    it was applied. bookings.discount_amount also exists, but a booking that
    was later edited no longer proves what the code was worth on the day, and
    a discount given without a code is not this report's subject.
    """
    where, params = ["1=1"], []
    if start:
        where.append("promo_code_redemptions.redeemed_at >= ?")
        params.append(start if isinstance(start, str) else start.isoformat())
    if end:
        where.append("promo_code_redemptions.redeemed_at < ?")
        params.append(end if isinstance(end, str) else end.isoformat())

    rows = conn.execute(
        f"""SELECT promo_codes.id, promo_codes.code, promo_codes.description,
                   promo_codes.discount_type, promo_codes.discount_value,
                   promo_codes.active, promo_codes.valid_until,
                   COUNT(promo_code_redemptions.id) AS uses,
                   COALESCE(SUM(promo_code_redemptions.discount_amount), 0) AS given,
                   COALESCE(SUM(promo_code_redemptions.original_amount), 0) AS gross,
                   COALESCE(SUM(promo_code_redemptions.final_amount), 0) AS net,
                   MAX(promo_code_redemptions.redeemed_at) AS last_used
              FROM promo_code_redemptions
              JOIN promo_codes ON promo_codes.id = promo_code_redemptions.promo_code_id
             WHERE {' AND '.join(where)}
             GROUP BY promo_codes.id
             ORDER BY given DESC""",
        params,
    ).fetchall()

    out = []
    for r in rows:
        gross = r["gross"] or 0.0
        out.append(dict(r, share=(r["given"] / gross * 100) if gross else 0.0))

    # Codes that exist and have never been used. Worth showing: an unused code
    # is either dead weight or a campaign that never reached anybody.
    unused = conn.execute(
        """SELECT code, description, valid_until, active FROM promo_codes
            WHERE id NOT IN (SELECT DISTINCT promo_code_id FROM promo_code_redemptions)
            ORDER BY code"""
    ).fetchall()

    return {"rows": out, "unused": unused,
            "given": sum(r["given"] or 0.0 for r in out),
            "gross": sum(r["gross"] or 0.0 for r in out),
            "net": sum(r["net"] or 0.0 for r in out),
            "uses": sum(r["uses"] or 0 for r in out)}


def money_held_not_earned(conn, *, today=None):
    """Cash taken for something that has not happened yet.

    It is in the account, and it is not income. Until the guest stays, the
    dinner is served or the atelier runs, it is money owed back if the thing
    does not happen — a liability sitting in the same balance as revenue.

    Money Ahead deliberately counts this as incoming, because for cash-flow
    that is exactly right. This is the other question about the same euros,
    and the two must not be added together.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    iso = today.isoformat()
    out = {"rooms": [], "workshops": [], "restaurant": []}

    for r in conn.execute(
        """SELECT id, reference_code, guest_name, arrival_date, departure_date,
                  COALESCE(total_price, 0) AS total_price,
                  COALESCE(amount_paid, 0) AS paid
             FROM bookings
            WHERE status = 'confirmed' AND arrival_date > ?
              AND COALESCE(amount_paid, 0) > 0
            ORDER BY arrival_date""", (iso,)).fetchall():
        out["rooms"].append(dict(r, on=r["arrival_date"], label=r["guest_name"]))

    for r in conn.execute(
        """SELECT workshop_bookings.id, workshop_bookings.guest_name,
                  workshops.title, workshop_sessions.start_date,
                  COALESCE(workshop_bookings.total_price, 0) AS total_price,
                  COALESCE(workshop_bookings.deposit_amount, 0) AS deposit,
                  workshop_bookings.deposit_paid_at,
                  COALESCE(workshop_bookings.balance_amount, 0) AS balance,
                  workshop_bookings.balance_paid_at
             FROM workshop_bookings
             JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_bookings.status NOT IN ('declined', 'cancelled')
              AND workshop_sessions.start_date > ?
            ORDER BY workshop_sessions.start_date""", (iso,)).fetchall():
        paid = (r["deposit"] if r["deposit_paid_at"] else 0.0) + \
               (r["balance"] if r["balance_paid_at"] else 0.0)
        if paid > 0:
            out["workshops"].append(dict(r, paid=paid, on=r["start_date"],
                                         label=f"{r['guest_name']} — {r['title']}"))

    for r in conn.execute(
        """SELECT id, reference_code, guest_name, dinner_date, party_size,
                  COALESCE(deposit_amount, 0) AS paid,
                  COALESCE(total_price, 0) AS total_price
             FROM restaurant_bookings
            WHERE status = 'confirmed' AND dinner_date > ?
              AND COALESCE(deposit_amount, 0) > 0
            ORDER BY dinner_date""", (iso,)).fetchall():
        out["restaurant"].append(dict(r, on=r["dinner_date"], label=r["guest_name"]))

    totals = {k: sum(r["paid"] for r in v) for k, v in out.items()}
    everything = out["rooms"] + out["workshops"] + out["restaurant"]

    # When it stops being a liability and becomes income: the month the thing
    # actually happens. An owner asking "is this a good year" needs to know
    # how much of the balance belongs to next year.
    by_month = {}
    for r in everything:
        d = parse_date(r["on"])
        if d:
            by_month[d.replace(day=1).isoformat()] = \
                by_month.get(d.replace(day=1).isoformat(), 0.0) + r["paid"]

    return {"rooms": out["rooms"], "workshops": out["workshops"],
            "restaurant": out["restaurant"], "totals": totals,
            "total": sum(totals.values()), "count": len(everything),
            "by_month": sorted(by_month.items()),
            "furthest": max((r["on"] for r in everything), default=None)}


def rota_conflict_summary(conn, start, end):
    """Counts by kind, for a band or a badge, without the rows."""
    rows = rota_conflicts(conn, start, end)
    counts = {k: 0 for k in ROTA_CONFLICT_KINDS}
    for r in rows:
        counts[r["kind"]] = counts.get(r["kind"], 0) + 1
    return {"total": len(rows), "counts": counts,
            "people": len({r["user_id"] for r in rows})}


EXTRA_CATEGORIES = {
    "drinks": "Drinks",
    "food": "Food & hampers",
    "activity": "Activities & excursions",
    "transfer": "Transfers",
    "wellness": "Wellness",
    "celebration": "Celebrations",
    "other": "Other",
}
STOCK_CATEGORIES = {
    "drinks": "Drinks", "food": "Food", "cleaning": "Cleaning",
    "linen": "Linen", "maintenance": "Maintenance",
    "guest_supplies": "Guest supplies", "other": "Other",
}
STOCK_REASONS = {
    "purchase": "Delivered / bought in",
    "sale": "Sold to a guest",
    "wastage": "Broken, spoiled or written off",
    "stocktake": "Counted — adjusted to match",
    "correction": "Correction",
    "opening": "Opening balance",
}


def stock_levels(conn, item_ids=None):
    """{stock_item_id: level} summed from the movement ledger.

    The level is never stored on the item. A stored counter and a ledger
    disagree the first time anything goes wrong, and then nobody knows which to
    believe; summing means the number on screen is always exactly what the
    history says it is.
    """
    sql = """SELECT stock_item_id, COALESCE(SUM(delta), 0) AS level
             FROM stock_movements"""
    params = []
    if item_ids:
        ids = list(item_ids)
        sql += " WHERE stock_item_id IN ({})".format(",".join("?" * len(ids)))
        params = ids
    sql += " GROUP BY stock_item_id"
    return {r["stock_item_id"]: r["level"] for r in conn.execute(sql, params).fetchall()}


def record_stock_movement(conn, stock_item_id, delta, reason, *, unit_cost=None,
                          expense_id=None, booking_extra_id=None, note=None,
                          user_id=None):
    """Append one movement. Callers commit — so a sale and the stock it consumes
    land together or not at all."""
    if reason not in STOCK_REASONS:
        raise ValueError(f"unknown stock reason {reason!r}")
    conn.execute(
        """INSERT INTO stock_movements (stock_item_id, delta, reason, unit_cost,
           expense_id, booking_extra_id, note, created_by_user_id, created_at)
           VALUES (?,?,?,?,?,?,?,?,?)""",
        (stock_item_id, delta, reason, unit_cost, expense_id, booking_extra_id,
         note, user_id, datetime.now(timezone.utc).isoformat()),
    )


def stock_overview(conn):
    """Everything the stock page needs, in two queries rather than one per item."""
    items = conn.execute(
        "SELECT * FROM stock_items WHERE active = 1 ORDER BY category, name").fetchall()
    levels = stock_levels(conn, [i["id"] for i in items])
    rows, low, value = [], [], 0.0
    for i in items:
        level = levels.get(i["id"], 0)
        value += level * (i["unit_cost"] or 0)
        row = {"item": i, "level": level,
               "short_by": max(0, (i["reorder_level"] or 0) - level),
               "is_low": level <= (i["reorder_level"] or 0)}
        rows.append(row)
        if row["is_low"]:
            low.append(row)
    return {"rows": rows, "low": low, "value": value, "count": len(items)}


def add_booking_extra(conn, category, booking_id, extra, quantity=1, *,
                      unit_price=None, notes=None, user_id=None,
                      scheduled_for=None, status="confirmed"):
    """Sell an extra against a booking, and take it out of stock if it maps to
    something we hold.

    `extra` may be a catalogue row or a plain name — the POS and the admin form
    both need to sell a one-off that isn't in the catalogue. Returns the new
    line-item id.
    """
    if isinstance(extra, str):
        name, extra_id, stock_item_id, per_unit = extra, None, None, 0
        price = unit_price or 0
    else:
        name = extra["name"]
        extra_id = extra["id"]
        stock_item_id = extra["stock_item_id"] if "stock_item_id" in extra.keys() else None
        per_unit = (extra["stock_qty_per_unit"]
                    if "stock_qty_per_unit" in extra.keys() else 1) or 0
        price = unit_price if unit_price is not None else (extra["price"] or 0)

    conn.execute(
        """INSERT INTO booking_extras (category, booking_id, extra_id, name, unit_price,
           quantity, notes, status, scheduled_for, added_by_user_id, created_at)
           VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (category, booking_id, extra_id, name, price, quantity, notes, status,
         scheduled_for, user_id, datetime.now(timezone.utc).isoformat()),
    )
    line_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]

    # Cancelled lines never consumed anything, so they must not deplete stock.
    if stock_item_id and per_unit and status != "cancelled":
        record_stock_movement(
            conn, stock_item_id, -abs(per_unit * quantity), "sale",
            booking_extra_id=line_id, user_id=user_id,
            note=f"{quantity} x {name}")
    return line_id


def cancel_booking_extra(conn, line_id, user_id=None):
    """Cancel a sold line and put back whatever it took out of stock.

    The original sale movement is left alone and a matching positive one is
    added — the ledger is append-only, so a mistake is corrected by a further
    entry rather than by rewriting history.
    """
    line = conn.execute("SELECT * FROM booking_extras WHERE id = ?", (line_id,)).fetchone()
    if not line or line["status"] == "cancelled":
        return False
    taken = conn.execute(
        """SELECT COALESCE(SUM(delta), 0) AS d FROM stock_movements
           WHERE booking_extra_id = ?""", (line_id,)).fetchone()["d"]
    if taken:
        mv = conn.execute(
            "SELECT stock_item_id FROM stock_movements WHERE booking_extra_id = ? LIMIT 1",
            (line_id,)).fetchone()
        record_stock_movement(conn, mv["stock_item_id"], -taken, "correction",
                              booking_extra_id=line_id, user_id=user_id,
                              note=f"cancelled: {line['name']}")
    conn.execute("UPDATE booking_extras SET status = 'cancelled' WHERE id = ?", (line_id,))
    return True


def extras_for_booking(conn, category, booking_id):
    return conn.execute(
        """SELECT * FROM booking_extras WHERE category = ? AND booking_id = ?
           ORDER BY created_at""", (category, booking_id)).fetchall()


def extras_total(rows, include_cancelled=False):
    return round(sum((r["unit_price"] or 0) * (r["quantity"] or 0)
                     for r in rows if include_cancelled or r["status"] != "cancelled"), 2)


def booking_bill(conn, booking_id):
    """What a stay costs, what has been received, and what is still owed.

    A room booking had none of this. `payment_status` could only say
    unpaid/paid/refunded, which cannot express "paid the deposit" or "added a
    night and owes the difference" — so there was nowhere to put the cost of
    anything a guest might add later, which is why they could not add anything.
    Workshops already worked this way; this brings stays into line.

    The room line is recomputed from the rates rather than trusted from
    total_price, so a stay whose dates changed prices correctly. Extras are
    real line items. Refunds come off what was received, not off the total —
    the stay still cost what it cost, and a bill that hides a refund is a bill
    somebody has to reconcile by hand.
    """
    booking = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id WHERE bookings.id = ?""",
        (booking_id,)).fetchone()
    if not booking:
        return None

    arrival, departure = parse_date(booking["arrival_date"]), parse_date(booking["departure_date"])
    nights = (departure - arrival).days if (arrival and departure) else 0
    room = conn.execute("SELECT * FROM rooms WHERE id = ?", (booking["room_id"],)).fetchone()
    room_total = compute_room_total(conn, room, arrival, departure) if (room and nights) else 0.0

    lines = []
    if room_total:
        lines.append({
            "label": f"{booking['room_name']} — {nights} night{'' if nights == 1 else 's'}",
            "amount": room_total, "kind": "room"})

    extras = extras_for_booking(conn, "room", booking_id)
    for extra in extras:
        if extra["status"] == "cancelled":
            continue
        amount = round((extra["unit_price"] or 0) * (extra["quantity"] or 0), 2)
        qty = extra["quantity"] or 1
        lines.append({
            "label": extra["name"] + (f" × {qty}" if qty > 1 else ""),
            "amount": amount, "kind": "extra"})

    total = round(sum(l["amount"] for l in lines), 2)
    refunded = conn.execute(
        """SELECT COALESCE(SUM(amount), 0) AS t FROM refunds
           WHERE category = 'room' AND booking_id = ?""", (booking_id,)).fetchone()["t"] or 0.0
    paid = round((booking["amount_paid"] or 0) - refunded, 2)
    return {
        "booking": booking,
        "lines": lines,
        "nights": nights,
        "total": total,
        "paid": max(paid, 0.0),
        "refunded": round(refunded, 2),
        "owed": round(max(total - paid, 0.0), 2),
        "overpaid": round(max(paid - total, 0.0), 2),
    }


def record_booking_payment(conn, booking_id, amount, reference=None):
    """Add to what has been received on a stay.

    Additive rather than a flag, so a deposit followed by a balance — or a night
    added and paid for later — accumulates instead of overwriting. Also keeps
    payment_status roughly in step for the older code that reads it.
    """
    conn.execute(
        "UPDATE bookings SET amount_paid = COALESCE(amount_paid, 0) + ? WHERE id = ?",
        (round(amount or 0, 2), booking_id))
    bill = booking_bill(conn, booking_id)
    if bill and bill["owed"] <= 0.005:
        conn.execute("UPDATE bookings SET payment_status = 'paid' WHERE id = ?", (booking_id,))
    if reference:
        conn.execute(
            "UPDATE bookings SET stripe_payment_intent_id = COALESCE(stripe_payment_intent_id, ?) "
            "WHERE id = ?", (reference, booking_id))
    return bill


def start_booking_stripe_payment(conn, booking_id):
    """Checkout URL for whatever is still owed on a stay, or None.

    Workshop guests have been able to settle online since the start; room
    guests could only be told "we'll take this on arrival", even after adding
    an extra or a night to their own booking. That leaves the château carrying
    every stay to the door and a guest who wants to pay unable to.

    The amount comes from booking_bill() at the moment the guest clicks, not
    from total_price — a stay that gained an extra, lost a night or took a
    part payment has to charge what is actually left.
    """
    if not stripe_enabled():
        return None
    bill = booking_bill(conn, booking_id)
    if not bill:
        return None
    booking = bill["booking"]
    if booking["status"] in ("declined", "cancelled") or bill["owed"] <= 0:
        return None
    try:
        checkout_session = stripe.checkout.Session.create(
            mode="payment",
            payment_method_types=["card"],
            line_items=[{
                "price_data": {
                    "currency": "eur",
                    "product_data": {"name": f"{booking['room_name']} ({booking['reference_code']})"},
                    "unit_amount": int(round(bill["owed"] * 100)),
                },
                "quantity": 1,
            }],
            customer_email=booking["guest_email"],
            success_url=url_for("booking_stripe_success", manage_token=booking["manage_token"],
                                _external=True) + "&session_id={CHECKOUT_SESSION_ID}",
            cancel_url=url_for("manage_booking", manage_token=booking["manage_token"], _external=True),
            metadata={"booking_id": str(booking_id), "kind": "room_balance"},
        )
    except Exception:
        return None
    return checkout_session.url


def mark_booking_payment_paid(conn, session):
    """Record a room-stay payment, once, whichever of the success redirect or
    the webhook arrives first.

    Stripe retries webhooks and the guest may reload the success page, so the
    same Checkout Session can arrive several times. The session id is written
    into a payments row and checked first — recording twice would take the
    money off what they owe twice and send them home thinking they had paid.
    """
    meta = smeta(session)
    if meta.get("kind") != "room_balance":
        return
    booking_id = meta.get("booking_id")
    if not booking_id:
        return
    booking_id = int(booking_id)
    session_id = session["id"]
    already = conn.execute(
        "SELECT 1 FROM booking_payments WHERE stripe_session_id = ?", (session_id,)).fetchone()
    if already:
        return
    amount = (sval(session, "amount_total") or 0) / 100
    if amount <= 0:
        return
    try:
        conn.execute(
            """INSERT INTO booking_payments (booking_id, amount, method, stripe_session_id, created_at)
               VALUES (?, ?, 'stripe', ?, ?)""",
            (booking_id, round(amount, 2), session_id, datetime.now(timezone.utc).isoformat()))
    except sqlite3.IntegrityError:
        # The success redirect and the webhook can be in flight at the same
        # moment and both clear the check above. The UNIQUE session id is the
        # real guarantee; losing the race is the correct outcome, not an error
        # the guest should see as a 500 immediately after paying.
        return
    record_booking_payment(conn, booking_id, amount, reference=sval(session, "payment_intent"))
    booking = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id WHERE bookings.id = ?""",
        (booking_id,)).fetchone()
    # Commit before the receipt goes out. With no email provider configured
    # send_email falls back to email_outbox on its own connection, which cannot
    # take a write lock while this transaction is open — the same way a
    # workshop deposit receipt was being lost to "database is locked".
    conn.commit()
    if booking:
        bill = booking_bill(conn, booking_id)
        portal_token = guest_portal_token(conn, booking["guest_email"])
        conn.commit()
        account_line = ""
        if portal_token:
            account_line = ("\nYour bookings and balances are always here:\n"
                            f"{url_for('guest_portal', token=portal_token, _external=True)}\n")
        send_email(
            booking["guest_email"],
            f"Payment received — {booking['room_name']}",
            f"Hi {booking['guest_name']},\n\n"
            f"We've received €{amount:.2f} for your stay ({booking['reference_code']}).\n"
            + (f"Still to pay: €{bill['owed']:.2f}.\n" if bill and bill["owed"] > 0
               else "Your stay is now paid in full.\n")
            + account_line
            + f"\n— Château de Gudanes",
        )


