@app.route("/admin/emails/<int:template_id>/send", methods=["POST"])
@owner_required
def send_campaign_template(template_id):
    """Send a campaign. Deliberately two-step: a test send goes only to the
    owner, and the real send needs the recipient count typed back, because
    this is the one action here that can't be undone."""
    conn = get_db()
    template = conn.execute(
        "SELECT * FROM campaign_templates WHERE id = ?", (template_id,)).fetchone()
    if not template:
        conn.close()
        abort(404)

    segments = request.form.getlist("segments")
    months_raw = request.form.get("since_months", "").strip()
    since_iso = None
    if months_raw.isdigit() and int(months_raw) > 0:
        since_iso = (datetime.now(timezone.utc).date()
                     - timedelta(days=30 * int(months_raw))).isoformat()

    user = current_user()
    if request.form.get("mode") == "test":
        owner_email = user["email"]
        result = send_campaign(conn, template, {owner_email: user["name"]}, user["id"], as_test=True)
        conn.close()
        flash(f"Test sent to {owner_email}." if result["sent"]
              else "Test send failed — check the email settings.",
              "success" if result["sent"] else "error")
        return redirect(url_for("edit_campaign_template", template_id=template_id))

    if not segments:
        conn.close()
        flash("Choose at least one audience.", "error")
        return redirect(url_for("edit_campaign_template", template_id=template_id))

    audience = campaign_audience(conn, segments, since_iso)
    typed = request.form.get("confirm_count", "").strip()
    if typed != str(len(audience)):
        conn.close()
        flash(f"Type {len(audience)} into the confirm box to send to {len(audience)} "
              f"recipient{'' if len(audience) == 1 else 's'}.", "error")
        return redirect(url_for("edit_campaign_template", template_id=template_id))

    result = send_campaign(conn, template, audience, user["id"])
    log_audit(conn, "campaign_sent", target=template["name"],
              details=f"{result['sent']} sent, {result['failed']} failed")
    conn.commit()
    conn.close()
    flash(f"Sent to {result['sent']} recipient(s)"
          + (f", {result['failed']} failed" if result["failed"] else "") + ".",
          "success" if not result["failed"] else "error")
    return redirect(url_for("edit_campaign_template", template_id=template_id))


@app.route("/unsubscribe/<token>", methods=["GET", "POST"])
@csrf.exempt
def campaign_unsubscribe(token):
    """The guest's own way out of campaign email.

    No login: the token IS the credential, and it's per-send and random, so it
    identifies one recipient without ever putting their address in the URL and
    can't be walked to reach anybody else. GET only shows the page — mail
    clients and link scanners routinely fetch every URL in a message, so
    unsubscribing on GET would silently opt people out who never clicked.
    The POST does the work.

    CSRF-exempt because the recipient arrives from their inbox with no session;
    the worst a forged POST can do is unsubscribe someone from marketing email,
    which is the safe direction and reversible by the owner.
    """
    conn = get_db()
    row = conn.execute(
        "SELECT recipient_email, recipient_name FROM campaign_sends WHERE unsubscribe_token = ?",
        (token,),
    ).fetchone()
    if not row:
        conn.close()
        return render_template("unsubscribe.html", state="unknown"), 404

    email = (row["recipient_email"] or "").strip().lower()
    if request.method == "POST":
        conn.execute(
            "INSERT OR IGNORE INTO email_optouts (email, reason, created_at) VALUES (?, ?, ?)",
            (email, "Unsubscribed from a campaign email",
             datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
        conn.close()
        return render_template("unsubscribe.html", state="done", email=email)

    already = conn.execute(
        "SELECT 1 FROM email_optouts WHERE email = ?", (email,)
    ).fetchone() is not None
    conn.close()
    return render_template("unsubscribe.html",
                           state="already" if already else "confirm",
                           email=email, name=row["recipient_name"], token=token)


@app.route("/admin/gallery")
@owner_required
def admin_gallery():
    conn = get_db()
    sections = conn.execute(
        "SELECT * FROM gallery_sections ORDER BY sort_order, id").fetchall()
    photos = conn.execute(
        "SELECT * FROM gallery_photos ORDER BY section_id, sort_order, id").fetchall()
    subs = conn.execute(
        """SELECT COUNT(*) AS confirmed FROM newsletter_subscribers
           WHERE confirmed_at IS NOT NULL AND unsubscribed_at IS NULL""").fetchone()["confirmed"]
    pending = conn.execute(
        """SELECT COUNT(*) AS c FROM newsletter_subscribers
           WHERE confirmed_at IS NULL AND unsubscribed_at IS NULL""").fetchone()["c"]
    conn.close()
    by_section = {}
    for p in photos:
        by_section.setdefault(p["section_id"], []).append(p)
    overview = [
        overview_cell("Sections", len(sections)),
        overview_cell("Photographs", len(photos)),
        overview_cell("Newsletter", subs, sub=f"{pending} unconfirmed" if pending else None),
    ]
    return render_template("admin_gallery.html", sections=sections,
                           by_section=by_section, overview=overview)


@app.route("/admin/gallery/<int:section_id>/photos", methods=["POST"])
@owner_required
def add_gallery_photos(section_id):
    conn = get_db()
    section = conn.execute(
        "SELECT * FROM gallery_sections WHERE id = ?", (section_id,)).fetchone()
    if not section:
        conn.close()
        abort(404)
    stored = save_room_photos_multi(request.files.getlist("photos"))
    if not stored:
        conn.close()
        flash("No usable image was uploaded — PNG or JPG only.", "error")
        return redirect(url_for("admin_gallery"))
    start = conn.execute(
        "SELECT COALESCE(MAX(sort_order), -1) + 1 AS n FROM gallery_photos WHERE section_id = ?",
        (section_id,)).fetchone()["n"]
    for i, name in enumerate(stored):
        conn.execute(
            """INSERT INTO gallery_photos (section_id, filename, sort_order, created_at)
               VALUES (?, ?, ?, ?)""",
            (section_id, name, start + i, datetime.now(timezone.utc).isoformat()))
    log_audit(conn, "gallery_photos_added", target=section["slug"])
    conn.commit()
    conn.close()
    flash(f"Added {len(stored)} photograph(s) to {section['title']}.", "success")
    return redirect(url_for("admin_gallery"))


@app.route("/admin/gallery/photo/<int:photo_id>", methods=["POST"])
@owner_required
def edit_gallery_photo(photo_id):
    """Caption, and position within the section.

    Moving is by swap rather than by rewriting every row's sort_order: two
    photographs exchange places and nothing else in the section is touched, so
    two people reordering different pairs at once cannot renumber each other's
    work. An empty caption is stored as NULL, not "", so the template's
    `{% if caption %}` stays the single test for "is there a caption".
    """
    conn = get_db()
    photo = conn.execute("SELECT * FROM gallery_photos WHERE id = ?", (photo_id,)).fetchone()
    if not photo:
        conn.close()
        abort(404)

    move = (request.form.get("move", "") or "").strip()
    if move in ("up", "down"):
        op, order = ("<", "DESC") if move == "up" else (">", "ASC")
        neighbour = conn.execute(
            f"""SELECT id, sort_order FROM gallery_photos
                WHERE section_id = ? AND (sort_order {op} ? OR (sort_order = ? AND id {op} ?))
                ORDER BY sort_order {order}, id {order} LIMIT 1""",
            (photo["section_id"], photo["sort_order"], photo["sort_order"], photo_id)).fetchone()
        if neighbour:
            conn.execute("UPDATE gallery_photos SET sort_order = ? WHERE id = ?",
                         (neighbour["sort_order"], photo_id))
            conn.execute("UPDATE gallery_photos SET sort_order = ? WHERE id = ?",
                         (photo["sort_order"], neighbour["id"]))
            conn.commit()
    else:
        conn.execute("UPDATE gallery_photos SET caption = ? WHERE id = ?",
                     ((request.form.get("caption", "") or "").strip() or None, photo_id))
        conn.commit()
    conn.close()
    return redirect(url_for("admin_gallery"))


@app.route("/admin/gallery/photo/<int:photo_id>/delete", methods=["POST"])
@owner_required
def delete_gallery_photo(photo_id):
    conn = get_db()
    photo = conn.execute(
        "SELECT * FROM gallery_photos WHERE id = ?", (photo_id,)).fetchone()
    if not photo:
        conn.close()
        abort(404)
    conn.execute("DELETE FROM gallery_photos WHERE id = ?", (photo_id,))
    log_audit(conn, "gallery_photo_deleted")
    conn.commit()
    conn.close()
    # The file itself goes too, but only after the row: an orphaned row shows a
    # broken image to guests, while an orphaned file merely wastes disk.
    path = os.path.join(ROOM_PHOTO_DIR, photo["filename"])
    if os.path.exists(path):
        try:
            os.remove(path)
        except OSError:
            pass
    flash("Photograph removed.", "success")
    return redirect(url_for("admin_gallery"))


