@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user():
        return redirect(url_for("dashboard"))
    if request.method == "POST":
        email = request.form.get("email", "").strip().lower()
        password = request.form.get("password", "")
        ip = request.remote_addr or "unknown"
        conn = get_db()
        throttle = conn.execute("SELECT * FROM login_throttle WHERE ip_address = ?", (ip,)).fetchone()
        if throttle and throttle["locked_until"] and parse_datetime_iso(throttle["locked_until"]) > datetime.now(timezone.utc):
            conn.close()
            flash("Too many failed sign-in attempts from this connection. Try again in a few minutes.", "error")
            return render_template("login.html")

        user = conn.execute("SELECT * FROM users WHERE email = ?", (email,)).fetchone()
        if user and check_password_hash(user["password_hash"], password):
            if user["status"] == "inactive":
                conn.close()
                flash("This account is inactive. Contact the owner.", "error")
                return render_template("login.html")
            conn.execute("DELETE FROM login_throttle WHERE ip_address = ?", (ip,))
            session.permanent = True
            session["user_id"] = user["id"]
            conn.commit()
            conn.close()
            return redirect(url_for("dashboard"))

        new_count = (throttle["failed_count"] if throttle else 0) + 1
        locked_until = None
        if new_count >= LOGIN_LOCKOUT_THRESHOLD:
            locked_until = (datetime.now(timezone.utc) + timedelta(minutes=LOGIN_LOCKOUT_MINUTES)).isoformat()
            log_audit(conn, "login_lockout", target=ip, details=f"{new_count} failed attempts")
        conn.execute(
            """INSERT INTO login_throttle (ip_address, failed_count, locked_until) VALUES (?, ?, ?)
               ON CONFLICT(ip_address) DO UPDATE SET failed_count = excluded.failed_count, locked_until = excluded.locked_until""",
            (ip, new_count, locked_until),
        )
        conn.commit()
        conn.close()
        flash("Incorrect email or password.", "error")
    return render_template("login.html")


@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))


@app.route("/clock/in", methods=["POST"])
@login_required
def clock_in_action():
    user = current_user()
    conn = get_db()
    if open_shift(conn, user["id"]):
        flash("You're already clocked in.", "error")
    else:
        clock_in(conn, user["id"])
        flash(f"Clocked in at {local_time_str(datetime.now(timezone.utc).isoformat())}.", "success")
    conn.close()
    return redirect(request.referrer or url_for("dashboard"))


@app.route("/clock/out", methods=["POST"])
@login_required
def clock_out_action():
    user = current_user()
    conn = get_db()
    shift = open_shift(conn, user["id"])
    if not shift:
        flash("You're not currently clocked in.", "error")
    else:
        clock_out(conn, user["id"])
        hours = net_hours(conn.execute("SELECT * FROM time_entries WHERE user_id = ? ORDER BY id DESC LIMIT 1", (user["id"],)).fetchone(), conn)
        flash(f"Clocked out — {hours:.2f}h worked this shift.", "success")
    conn.close()
    return redirect(request.referrer or url_for("dashboard"))


@app.route("/forgot-password", methods=["GET", "POST"])
def forgot_password():
    if request.method == "POST":
        if not email_enabled():
            flash("Email isn't set up for this site yet — ask the owner to reset your password directly.", "error")
            return render_template("forgot_password.html", email_enabled=email_enabled())
        email = request.form.get("email", "").strip().lower()
        conn = get_db()
        # Login has its own lockout; this had nothing. Somebody who knows a
        # staff address could have the site mail them a reset link as often as
        # they liked. The message below stays identical either way, so a
        # throttled attempt still says nothing about who has an account.
        if rate_limited(conn, "forgot_password", PASSWORD_RESET_LIMIT_PER_HOUR):
            conn.commit()
            conn.close()
            flash("If that email has an account, a reset link is on its way.", "success")
            return redirect(url_for("login"))
        person = conn.execute("SELECT * FROM users WHERE email = ?", (email,)).fetchone()
        if person:
            token = secrets.token_urlsafe(32)
            expires = (datetime.now(timezone.utc) + timedelta(hours=1)).isoformat()
            conn.execute(
                "UPDATE users SET reset_token = ?, reset_token_expires_at = ? WHERE id = ?",
                (token, expires, person["id"]),
            )
            conn.commit()
            reset_url = url_for("reset_password", token=token, _external=True)
            send_email(
                person["email"], "Reset your password",
                f"Hi {person['name'].split(' ')[0]},\n\n"
                f"Click this link to set a new password (valid for 1 hour):\n{reset_url}\n\n"
                f"If you didn't request this, you can ignore this email.\n\n— Château de Gudanes",
                keep=False,   # the body is a live credential, and expires in an hour
            )
        conn.close()
        # Same message whether or not the email matched — don't reveal who has an account.
        flash("If that email has an account, a reset link is on its way.", "success")
        return redirect(url_for("login"))
    return render_template("forgot_password.html", email_enabled=email_enabled())


@app.route("/reset-password/<token>", methods=["GET", "POST"])
def reset_password(token):
    conn = get_db()
    person = conn.execute("SELECT * FROM users WHERE reset_token = ?", (token,)).fetchone()
    if not person or not person["reset_token_expires_at"] or parse_datetime_iso(person["reset_token_expires_at"]) < datetime.now(timezone.utc):
        conn.close()
        flash("That reset link is invalid or has expired — request a new one.", "error")
        return redirect(url_for("forgot_password"))

    if request.method == "POST":
        password = request.form.get("password", "")
        confirm = request.form.get("confirm_password", "")
        if len(password) < 8:
            conn.close()
            flash("Password must be at least 8 characters.", "error")
            return render_template("reset_password.html", token=token)
        if password != confirm:
            conn.close()
            flash("Passwords don't match.", "error")
            return render_template("reset_password.html", token=token)
        conn.execute(
            "UPDATE users SET password_hash = ?, reset_token = NULL, reset_token_expires_at = NULL WHERE id = ?",
            (generate_password_hash(password), person["id"]),
        )
        conn.commit()
        conn.close()
        flash("Password updated — sign in with your new password.", "success")
        return redirect(url_for("login"))

    conn.close()
    return render_template("reset_password.html", token=token)


@app.route("/change-password", methods=["GET", "POST"])
@login_required
def change_password():
    if request.method == "POST":
        current = request.form.get("current_password", "")
        new = request.form.get("new_password", "")
        confirm = request.form.get("confirm_password", "")
        user = current_user()
        if not check_password_hash(user["password_hash"], current):
            flash("Current password is incorrect.", "error")
        elif len(new) < 8:
            flash("New password must be at least 8 characters.", "error")
        elif new != confirm:
            flash("New passwords don't match.", "error")
        else:
            conn = get_db()
            conn.execute(
                "UPDATE users SET password_hash = ? WHERE id = ?",
                (generate_password_hash(new), user["id"]),
            )
            log_audit(conn, "password_changed", target=user["name"])
            conn.commit()
            conn.close()
            flash("Password updated.", "success")
            return redirect(url_for("dashboard"))
    return render_template("change_password.html")


@app.route("/my-contact-info", methods=["GET", "POST"])
@login_required
def edit_own_contact_info():
    """Self-service editing limited to phone + emergency contact — job role,
    pay, status, and skills stay owner-controlled via edit_employee."""
    user = current_user()
    if request.method == "POST":
        phone = request.form.get("phone", "").strip()
        emergency_contact_name = request.form.get("emergency_contact_name", "").strip()
        emergency_contact_phone = request.form.get("emergency_contact_phone", "").strip()
        emergency_contact_relationship = request.form.get("emergency_contact_relationship", "").strip()
        conn = get_db()
        conn.execute(
            """UPDATE users SET phone = ?, emergency_contact_name = ?,
               emergency_contact_phone = ?, emergency_contact_relationship = ? WHERE id = ?""",
            (phone, emergency_contact_name, emergency_contact_phone,
             emergency_contact_relationship, user["id"]),
        )
        conn.commit()
        conn.close()
        flash("Contact info updated.", "success")
        return redirect(url_for("profile", user_id=user["id"]))
    return render_template("edit_own_contact_info.html", person=user)


# ---------------------------------------------------------------------------
# Owner home — the redesigned dashboard
#
# One screen answering four questions in order: what needs my decision, what
# happens next, is the house full, is the money on track. Everything here is
# derived from data the app already holds; nothing is sample data.
#
# The design's figure sparklines are seven real daily values, computed per
# figure rather than stored — there is no history table, and adding one to draw
# a 22px bar chart would be a migration in service of decoration. Seven cheap
# COUNT queries is the honest trade, and it means the line never disagrees with
# the figure above it.
# ---------------------------------------------------------------------------

# Revenue is charted against a monthly target the owner sets. Held in
# app_settings rather than hardcoded: a budget nobody chose is a line on a
# chart that means nothing, and the dashed line is labelled with whatever this
# says. Unset means no line is drawn at all, which is honest — the chart still
# shows six real months.
REVENUE_BUDGET_SETTING = "monthly_revenue_budget"


def _spark(values):
    """Seven values as percentage bar heights, tallest at 100.

    Percentages rather than raw numbers because the sparkline is 22px tall and
    unitless; a flat series renders as a flat row of short bars rather than
    nothing, so 'no change' still reads as data rather than as missing.
    """
    top = max(values) if values and max(values) > 0 else 1
    return [max(6, round(v / top * 100)) for v in values]


def _last_seven_days(today):
    return [today - timedelta(days=i) for i in range(6, -1, -1)]


def owner_home_figures(conn, today):
    """The five figures across the top, each with a real seven-day series."""
    days = _last_seven_days(today)

    rooms_total = conn.execute(
        "SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"] or 0
    occupied = []
    for d in days:
        occupied.append(conn.execute(
            """SELECT COUNT(DISTINCT room_id) AS c FROM bookings
               WHERE status = 'confirmed' AND arrival_date <= ? AND departure_date > ?""",
            (d.isoformat(), d.isoformat())).fetchone()["c"] or 0)
    rooms_now = occupied[-1]
    last_night = occupied[-2] if len(occupied) > 1 else rooms_now
    room_delta = rooms_now - last_night

    arrivals = []
    for d in days:
        arrivals.append(conn.execute(
            """SELECT COUNT(*) AS c FROM bookings
               WHERE status = 'confirmed' AND arrival_date = ?""",
            (d.isoformat(),)).fetchone()["c"] or 0)
    departures_today = conn.execute(
        """SELECT COUNT(*) AS c FROM bookings
           WHERE status = 'confirmed' AND departure_date = ?""",
        (today.isoformat(),)).fetchone()["c"] or 0
    next_arrival = conn.execute(
        """SELECT estimated_arrival_time FROM bookings
           WHERE status = 'confirmed' AND arrival_date = ?
             AND estimated_arrival_time IS NOT NULL AND estimated_arrival_time <> ''
           ORDER BY estimated_arrival_time LIMIT 1""",
        (today.isoformat(),)).fetchone()

    covers = []
    for d in days:
        covers.append(conn.execute(
            """SELECT COALESCE(SUM(party_size), 0) AS c FROM restaurant_bookings
               WHERE status = 'confirmed' AND dinner_date = ?""",
            (d.isoformat(),)).fetchone()["c"] or 0)
    dietary_tonight = conn.execute(
        """SELECT COUNT(*) AS c FROM restaurant_bookings
           WHERE status = 'confirmed' AND dinner_date = ?
             AND COALESCE(TRIM(dietary_notes), '') <> ''""",
        (today.isoformat(),)).fetchone()["c"] or 0

    staff_total = conn.execute(
        "SELECT COUNT(*) AS c FROM users WHERE role <> 'owner' AND status = 'active'").fetchone()["c"] or 0
    on_shift = conn.execute(
        "SELECT COUNT(*) AS c FROM time_entries WHERE clock_out_at IS NULL").fetchone()["c"] or 0
    shift_series = []
    for d in days:
        shift_series.append(conn.execute(
            "SELECT COUNT(*) AS c FROM time_entries WHERE DATE(clock_in_at) = ?",
            (d.isoformat(),)).fetchone()["c"] or 0)

    decisions, decisions_value, stale = owner_queue_totals(conn, today)
    decision_series = []
    for d in days:
        decision_series.append(conn.execute(
            """SELECT (SELECT COUNT(*) FROM expenses WHERE DATE(submitted_at) <= ? AND status = 'pending')
                    + (SELECT COUNT(*) FROM leave_requests WHERE DATE(requested_at) <= ? AND status = 'pending')
                      AS c""", (d.isoformat(), d.isoformat())).fetchone()["c"] or 0)

    return [
        {"label": "Rooms occupied", "value": rooms_now, "unit": f"/ {rooms_total}",
         "trend": _spark(occupied),
         "delta": (f"+{room_delta} on last night" if room_delta > 0 else
                   f"{room_delta} on last night" if room_delta < 0 else "same as last night"),
         "delta_tone": "good" if room_delta > 0 else ("bad" if room_delta < 0 else "neutral")},
        {"label": "Arrivals today", "value": arrivals[-1],
         "unit": f"in · {departures_today} out", "trend": _spark(arrivals),
         "delta": (f"next at {next_arrival['estimated_arrival_time']}" if next_arrival
                   else "no times given"), "delta_tone": "neutral"},
        {"label": "Dinner tonight", "value": covers[-1], "unit": "covers",
         "trend": _spark(covers),
         "delta": (f"{dietary_tonight} with dietary notes" if dietary_tonight
                   else "no dietary notes"), "delta_tone": "neutral"},
        {"label": "Staff on shift", "value": on_shift, "unit": f"of {staff_total}",
         "trend": _spark(shift_series),
         "delta": "nobody clocked in" if not on_shift else f"{on_shift} clocked in now",
         "delta_tone": "neutral"},
        {"label": "Your decisions", "value": decisions,
         "unit": (f"· €{decisions_value:,.0f}" if decisions_value else ""),
         "trend": _spark(decision_series),
         "delta": (f"{stale} older than 5 days" if stale else "none waiting long"),
         "delta_tone": "bad" if stale else "neutral"},
    ]


def owner_queue_totals(conn, today):
    """(count, money value, how many are over five days old) across the queue."""
    cutoff = (today - timedelta(days=5)).isoformat()
    row = conn.execute(
        """SELECT
             (SELECT COUNT(*) FROM expenses WHERE status = 'pending')
           + (SELECT COUNT(*) FROM leave_requests WHERE status = 'pending')
           + (SELECT COUNT(*) FROM timesheet_corrections WHERE status = 'pending') AS n,
             (SELECT COALESCE(SUM(amount), 0) FROM expenses WHERE status = 'pending') AS v,
             (SELECT COUNT(*) FROM expenses WHERE status = 'pending' AND DATE(submitted_at) < ?)
           + (SELECT COUNT(*) FROM leave_requests WHERE status = 'pending' AND DATE(requested_at) < ?)
             AS old""", (cutoff, cutoff)).fetchone()
    return row["n"] or 0, row["v"] or 0.0, row["old"] or 0


def owner_home_queue(conn):
    """Everything waiting on the owner, as one ordered list.

    Money first and oldest first within each kind, because an unpaid supplier
    invoice is the item with a deadline attached. A timesheet correction is
    never marked bulk-eligible: approving one rewrites a pay record, and that
    needs a person to look at it.
    """
    out = []
    for e in conn.execute(
            """SELECT expenses.*, users.name AS who FROM expenses
               LEFT JOIN users ON users.id = expenses.submitted_by_user_id
               WHERE expenses.status = 'pending'
               ORDER BY expenses.submitted_at""").fetchall():
        out.append({
            "kind": "Claim" if e["submitted_by_user_id"] else "Invoice",
            "who": e["who"] or e["vendor_name"] or "—",
            "title": e["vendor_name"] or e["who"] or e["description"] or "Expense",
            "detail": e["description"] or "",
            "amount": f"€{(e['amount'] or 0):,.2f}",
            "age": (e["submitted_at"] or "")[:10],
            "tone": "money", "ok_label": "Approve", "no_label": "Reject",
            "bulk_eligible": (e["amount"] or 0) < 100,
            "endpoint": url_for("decide_expense", expense_id=e["id"]) if "decide_expense" in app.view_functions else None,
        })
    for l in conn.execute(
            """SELECT leave_requests.*, users.name AS who FROM leave_requests
               JOIN users ON users.id = leave_requests.user_id
               WHERE leave_requests.status = 'pending'
               ORDER BY leave_requests.requested_at""").fetchall():
        days = 1
        s, e2 = parse_date(l["start_date"]), parse_date(l["end_date"])
        if s and e2:
            days = (e2 - s).days + 1
        out.append({
            "kind": "Time off", "who": l["who"], "title": l["who"],
            "detail": f"{l['start_date']} – {l['end_date']}",
            "amount": f"{days} day{'s' if days != 1 else ''}",
            "age": (l["requested_at"] or "")[:10],
            "tone": "people", "ok_label": "Approve", "no_label": "Decline",
            "bulk_eligible": False, "endpoint": None,
        })
    for c in conn.execute(
            """SELECT timesheet_corrections.*, users.name AS who FROM timesheet_corrections
               LEFT JOIN users ON users.id = timesheet_corrections.user_id
               WHERE timesheet_corrections.status = 'pending'
               ORDER BY timesheet_corrections.created_at""").fetchall():
        out.append({
            "kind": "Timesheet", "who": c["who"] or "—", "title": c["who"] or "Timesheet",
            "detail": c["note"] or "needs checking",
            "amount": "—", "age": (c["created_at"] or "")[:10],
            # Never bulk: a timesheet edit rewrites a pay record.
            "tone": "people", "ok_label": "Fix", "no_label": "Dismiss",
            "bulk_eligible": False, "endpoint": None,
        })
    return out


# Two days. The backup email runs daily, so one missed run is a hiccup and two
# is nobody watching.
BACKUP_STALE_HOURS = 48


def backup_age_hours(conn):
    """Hours since a backup last left the building, or None if none ever has.

    Read from the audit log rather than from a file on disk on purpose: what
    counts is that a copy went somewhere else, not that one was written to the
    same volume that would be lost along with it.
    """
    last = conn.execute(
        "SELECT created_at FROM audit_log WHERE action IN ('backup_downloaded', "
        "'backup_auto_sent') ORDER BY created_at DESC LIMIT 1").fetchone()
    stamp = parse_datetime_iso(last["created_at"]) if last else None
    if stamp is None:
        return None
    return (datetime.now(timezone.utc) - stamp).total_seconds() / 3600


def backup_job_failure_note(conn):
    """Why it is not arriving, if the job knows -- so one task carries both
    halves, instead of the owner reading the age here and the reason elsewhere.

    Returns "" when the job has never failed, which is its own signal: nothing
    is failing, so either nothing is scheduled or it is switched off.
    """
    row = conn.execute(
        """SELECT last_message, consecutive_failures AS fails FROM automation_runs
            WHERE job_name = 'backup_email' AND last_status = 'failed'""").fetchone()
    if not row:
        return ""
    return (f"The scheduled backup has failed {row['fails']} run(s) in a row. "
            f"It reports: {row['last_message'] or 'no message'}\n\n")


def backup_gap_detail(age_h):
    """One sentence, so the panel and the task it raises cannot word it
    differently and read as two separate problems."""
    if age_h is None:
        return "none has ever been taken"
    return f"last one {age_h / 24:.0f} days ago"


def owner_home_warnings(conn, today):
    """Things nobody has told the owner, each linking to the page that says more.

    Short window on purpose. A clash five weeks out is real but not urgent,
    and a homepage that lists everything eventually gets scrolled past — the
    point of this section is that it is short enough to read every morning.

    Measured, not guessed: this adds about 16ms to the owner home, taking a
    seeded season (10 staff, 360 shifts, 40 bookings) from 30ms to 46ms. Most
    of it is rota_conflicts asking role_compliance once per distinct shift
    date. If that ever matters, the fix is to memoise across the two callers
    rather than to shorten the window — a fortnight is already the minimum
    that is any use.
    """
    out = []
    horizon = today + timedelta(days=14)

    def add(severity, title, detail, count, endpoint):
        out.append({"severity": severity, "title": title, "detail": detail,
                    "count": count, "href": url_for(endpoint)})

    clashes = rota_conflicts(conn, today, horizon)
    certs = [c for c in clashes if c["kind"] == "certification"]
    if certs:
        add("blocker", "Rostered without a current certificate",
            f"{certs[0]['employee_name']} on {certs[0]['shift_date']}"
            + (f", and {len(certs) - 1} more" if len(certs) > 1 else ""),
            len(certs), "rota_clashes_page")
    other = [c for c in clashes if c["kind"] != "certification"]
    if other:
        add("warn", "Rostered while away",
            f"{other[0]['employee_name']} on {other[0]['shift_date']}"
            + (f", and {len(other) - 1} more" if len(other) > 1 else ""),
            len(other), "rota_clashes_page")

    gaps = [g for g in cover_gaps(conn, today, horizon) if g["uncovered"]]
    if gaps:
        with_guests = [g for g in gaps if g["in_house"] or g["arrivals"]]
        add("blocker" if with_guests else "warn", "Days with nobody on",
            (f"{with_guests[0]['date']} has guests and nobody rostered"
             if with_guests else f"first is {gaps[0]['date']}"),
            len(gaps), "cover_gaps_page")

    faults = rooms_sold_with_a_fault(conn, today=today, days=14)
    if faults:
        here = [f for f in faults if f["in_house"]]
        add("blocker" if here else "warn", "Rooms sold with an open fault",
            (f"{here[0]['guest_name']} is in {here[0]['room_name']} now"
             if here else f"{faults[0]['room_name']}, {faults[0]['guest_name']} arriving"),
            len(faults), "room_faults_page")

    # A key held by somebody who has left belongs on the front page, not on a
    # screen you have to remember to open.
    lent = things_still_out(conn, today=today)
    if lent["with_leavers"]:
        worst = lent["with_leavers"][0]
        add("blocker", "Somebody who has left still holds a key",
            f"{worst['who']} — {worst['what']}"
            + (f", and {len(lent['with_leavers']) - 1} more"
               if len(lent["with_leavers"]) > 1 else ""),
            len(lent["with_leavers"]), "still_out_page")

    insurer = incidents_awaiting_insurer(conn)
    if insurer["overdue"]:
        worst = insurer["overdue"][0]
        add("blocker", "The insurer has not been told",
            f"{worst['summary'][:50]} — {worst['age_days']:.0f} days ago",
            len(insurer["overdue"]), "admin_incidents")

    # The one that costs the business its records rather than a service.
    age_h = backup_age_hours(conn)
    if age_h is None or age_h > BACKUP_STALE_HOURS:
        add("blocker", "No backup is arriving", backup_gap_detail(age_h),
            1, "admin_readiness")

    order = {"blocker": 0, "warn": 1}
    out.sort(key=lambda w: (order.get(w["severity"], 9), -w["count"]))
    return out


def owner_home_day(conn, today, user):
    """Today, in the order it happens. Arrivals, departures, dinner, tasks."""
    rows = []
    for b in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
               JOIN rooms ON rooms.id = bookings.room_id
               WHERE bookings.status = 'confirmed' AND bookings.arrival_date = ?""",
            (today.isoformat(),)).fetchall():
        rows.append({"time": b["estimated_arrival_time"] or "", "kind": "arrival",
                     "title": f"{b['guest_name']} arriving",
                     "detail": f"{b['room_name']} · party of {b['party_size']}",
                     "assignee": None, "done": bool(b["arrival_prepped_at"])})
    for b in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
               JOIN rooms ON rooms.id = bookings.room_id
               WHERE bookings.status = 'confirmed' AND bookings.departure_date = ?""",
            (today.isoformat(),)).fetchall():
        rows.append({"time": "", "kind": "departure",
                     "title": f"{b['guest_name']} departing",
                     "detail": b["room_name"], "assignee": None,
                     "done": bool(b["checked_out_at"])})
    covers = conn.execute(
        """SELECT COALESCE(SUM(party_size), 0) AS c FROM restaurant_bookings
           WHERE status = 'confirmed' AND dinner_date = ?""",
        (today.isoformat(),)).fetchone()["c"] or 0
    if covers:
        rows.append({"time": "19:30", "kind": "dinner", "title": "Dinner service",
                     "detail": f"{covers} covers", "assignee": None, "done": False})
    for t in conn.execute(
            """SELECT tasks.*, users.name AS who FROM tasks
               LEFT JOIN users ON users.id = tasks.assigned_to_user_id
               WHERE tasks.due_date = ? ORDER BY tasks.status, tasks.id""",
            (today.isoformat(),)).fetchall():
        rows.append({"time": "", "kind": "task", "title": t["title"],
                     "detail": t["room_note"] or "",
                     "assignee": "Mine" if t["assigned_to_user_id"] == user["id"] else t["who"],
                     "done": t["status"] == "done"})
    # Timed things first, in clock order; untimed after, since "no time given"
    # is not the same as midnight and must not sort to the top of the day.
    rows.sort(key=lambda r: (r["time"] == "", r["time"]))
    return rows


def owner_home_revenue(conn, today):
    """Six months of real revenue, and the owner's target if they set one."""
    months = []
    cursor = today.replace(day=1)
    for _ in range(6):
        months.append(cursor)
        cursor = (cursor - timedelta(days=1)).replace(day=1)
    months.reverse()
    out = []
    for m in months:
        nxt = (m + timedelta(days=31)).replace(day=1)
        summary = financial_month_summary(conn, m, nxt)
        out.append({"label": m.strftime("%b"), "value": summary["revenue"] or 0})
    top = max([m["value"] for m in out] + [1])
    for m in out:
        m["height_pct"] = max(4, round(m["value"] / top * 100))
    budget_row = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?", (REVENUE_BUDGET_SETTING,)).fetchone()
    try:
        budget = float(budget_row["value"]) if budget_row and budget_row["value"] else 0.0
    except (TypeError, ValueError):
        budget = 0.0
    # Where to draw the dashed line, as a percentage of the tallest bar. Off the
    # top of the chart is clamped, so an unreachable target still reads as
    # "above everything" rather than vanishing.
    budget_pct = min(100, round(budget / top * 100)) if budget else None
    return out, budget, budget_pct


def owner_home_occupancy(conn, today):
    """Every day of this month: how full the house was, and what moved."""
    first = today.replace(day=1)
    nxt = (first + timedelta(days=31)).replace(day=1)
    cap = house_guest_capacity(conn) or 1
    cells = []
    d = first
    while d < nxt:
        peak = peak_guests_in_house(conn, d, d + timedelta(days=1))
        arriving = conn.execute(
            """SELECT COUNT(*) AS c FROM bookings WHERE status = 'confirmed'
               AND arrival_date = ?""", (d.isoformat(),)).fetchone()["c"]
        leaving = conn.execute(
            """SELECT COUNT(*) AS c FROM bookings WHERE status = 'confirmed'
               AND departure_date = ?""", (d.isoformat(),)).fetchone()["c"]
        workshop = conn.execute(
            """SELECT COUNT(*) AS c FROM workshop_sessions
               WHERE start_date <= ? AND end_date >= ?""",
            (d.isoformat(), d.isoformat())).fetchone()["c"]
        marker = ("arrival" if arriving else
                  "departure" if leaving else
                  "workshop" if workshop else "none")
        cells.append({"day": d.day, "occupancy_0_1": min(1.0, peak / cap),
                      "marker": marker, "today": d == today})
        d += timedelta(days=1)
    # Monday-first, so the grid needs leading blanks for however far into the
    # week the 1st falls.
    return cells, first.weekday(), sum(c["occupancy_0_1"] for c in cells) / max(1, len(cells))


def owner_home_guests(conn, today):
    """Who is in the house right now."""
    return [{
        "name": r["guest_name"],
        "room": f"{r['room_name']} · party of {r['party_size']}",
        "checkout": format_date_human(r["departure_date"]),
        "initials": "".join(p[0] for p in (r["guest_name"] or "?").split()[:2]).upper(),
    } for r in conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.status = 'confirmed' AND bookings.arrival_date <= ?
             AND bookings.departure_date > ? AND bookings.checked_out_at IS NULL
           ORDER BY bookings.departure_date""",
        (today.isoformat(), today.isoformat())).fetchall()]


def owner_home_next_up(conn, today, day_rows):
    """The next thing with a time on it, and how long until it.

    Falls back to tomorrow's first event rather than showing an empty panel,
    because "nothing else today" is itself worth knowing at four in the
    afternoon — and a panel that disappears is a layout that jumps.
    """
    now = datetime.now(timezone.utc)
    for r in day_rows:
        if not r["time"] or r["done"]:
            continue
        try:
            hh, mm = (int(x) for x in r["time"].split(":")[:2])
        except ValueError:
            continue
        when = datetime.combine(today, dtime(hh, mm), tzinfo=timezone.utc)
        if when < now:
            continue
        mins = int((when - now).total_seconds() // 60)
        return {"time": r["time"], "title": r["title"], "room": r["detail"],
                "note": "", "countdown": f"in {mins // 60}h {mins % 60:02d}m"
                if mins >= 60 else f"in {mins}m", "tomorrow": False}
    nxt = conn.execute(
        """SELECT bookings.guest_name, bookings.party_size, bookings.arrival_date,
                  bookings.estimated_arrival_time, rooms.name AS room_name
           FROM bookings JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.status = 'confirmed' AND bookings.arrival_date > ?
           ORDER BY bookings.arrival_date LIMIT 1""", (today.isoformat(),)).fetchone()
    if not nxt:
        return None
    return {"time": nxt["estimated_arrival_time"] or "—",
            "title": f"{nxt['guest_name']} arriving",
            "room": f"{nxt['room_name']} · party of {nxt['party_size']}",
            "note": "", "countdown": format_date_human(nxt["arrival_date"]),
            "tomorrow": True}


@app.route("/")
def dashboard():
    # Two audiences, one address. A visitor gets the château's front page; a
    # signed-in member of staff gets their dashboard. The public header links the
    # brand to "/", so without this a guest clicking the château's own name
    # landed on a staff login screen.
    if not current_user():
        conn = get_db()
        # Real rooms and real dates, not category tiles. A visitor should be
        # able to see what is actually for sale — named, priced, described —
        # without clicking through first.
        # Plain dicts, not sqlite3.Row: the template reads optional keys with
        # .get('img'), .get('spec'), .get('rate') so a hand-written room can
        # override the photograph or the rate, and a Row has no .get at all —
        # it raises rather than returning None, which took the front page down.
        rooms = [dict(r) for r in conn.execute(
            """SELECT * FROM rooms WHERE active = 1
               ORDER BY sort_order, price_per_night LIMIT 4""").fetchall()]
        # Only sittings still ahead. A front page advertising a workshop that
        # finished in June is worse than one advertising none.
        upcoming = [dict(r) for r in conn.execute(
            """SELECT workshop_sessions.*, workshops.title, workshops.price_per_person,
                      workshops.nights_label, workshops.id AS workshop_id
                 FROM workshop_sessions
                 JOIN workshops ON workshops.id = workshop_sessions.workshop_id
                WHERE workshops.active = 1 AND workshop_sessions.start_date >= ?
                ORDER BY workshop_sessions.start_date LIMIT 3""",
            (datetime.now(timezone.utc).date().isoformat(),)).fetchall()]
        conn.close()
        # Both are optional in the template, so an empty house still renders.
        return render_template("home.html", rooms=rooms, upcoming=upcoming)
    return staff_dashboard()


@login_required
def staff_dashboard():
    user = current_user()
    conn = get_db()
    stats = {}
    today = datetime.now(timezone.utc).date()
    briefing = None
    my_tasks = []

    who_is_here = guests_in_residence(conn, today)
    announcements_current = current_announcements(conn, today)

    on_shift_by_user = {
        r["user_id"]: r for r in conn.execute("SELECT * FROM time_entries WHERE clock_out_at IS NULL").fetchall()
    }
    my_shift = on_shift_by_user.get(user["id"])
    my_open_break = None
    if my_shift:
        my_open_break = conn.execute(
            "SELECT * FROM breaks WHERE time_entry_id = ? AND end_at IS NULL", (my_shift["id"],)
        ).fetchone()

    if user["role"] == "owner":
        auto_prepped_count = auto_prep_upcoming_arrivals(conn, today)
        if auto_prepped_count:
            flash(
                f"Auto-prepped {auto_prepped_count} arriving booking{'' if auto_prepped_count == 1 else 's'} "
                f"— room setup tasks assigned.", "success",
            )
        expired_count = expire_stale_pending_bookings(conn)
        if expired_count:
            flash(
                f"Auto-declined {expired_count} pending booking{'' if expired_count == 1 else 's'} "
                f"with no response after {STALE_PENDING_BOOKING_HOURS}h.", "success",
            )
        team = conn.execute(
            "SELECT * FROM users WHERE role = 'employee' ORDER BY status, name"
        ).fetchall()
        on_shift_now = conn.execute(
            """SELECT time_entries.*, users.name AS user_name, users.job_role AS user_job_role
               FROM time_entries JOIN users ON users.id = time_entries.user_id
               WHERE time_entries.clock_out_at IS NULL
               ORDER BY time_entries.clock_in_at"""
        ).fetchall()
        current_tasks_by_user = {}
        for t in conn.execute(
            """SELECT * FROM tasks WHERE status != 'done' AND assigned_to_user_id IS NOT NULL
               AND (due_date IS NULL OR due_date <= ?) ORDER BY (due_date IS NULL), due_date""",
            (today.isoformat(),),
        ).fetchall():
            current_tasks_by_user.setdefault(t["assigned_to_user_id"], []).append(t)
        all_stays = stays_with_status(conn, today)
        stats["guests_current"] = sum(1 for g in all_stays if g["stay_status"] == "current")
        stats["guests_upcoming"] = sum(1 for g in all_stays if g["stay_status"] == "upcoming")
        stats["rooms_total"] = conn.execute("SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"]
        stats["bookings_pending"] = conn.execute(
            "SELECT COUNT(*) AS c FROM bookings WHERE status = 'pending'"
        ).fetchone()["c"]
        stats["expenses_pending"] = conn.execute(
            "SELECT COUNT(*) AS c FROM expenses WHERE status = 'pending'"
        ).fetchone()["c"]
        stats["leave_pending"] = conn.execute(
            "SELECT COUNT(*) AS c FROM leave_requests WHERE status = 'pending'"
        ).fetchone()["c"]
        who_is_off_today = conn.execute(
            """SELECT leave_requests.*, users.name AS employee_name FROM leave_requests
               JOIN users ON users.id = leave_requests.user_id
               WHERE leave_requests.status = 'approved'
                 AND leave_requests.start_date <= ? AND leave_requests.end_date >= ?
               ORDER BY users.name""",
            (today.isoformat(), today.isoformat()),
        ).fetchall()
        briefing = build_task_sheet(conn, "day", today)
        month_stats = compute_month_stats(conn, today)
        feedback_row = conn.execute("SELECT AVG(rating) AS avg_rating, COUNT(*) AS c FROM guest_feedback").fetchone()
        stats["feedback_avg"] = round(feedback_row["avg_rating"], 1) if feedback_row["avg_rating"] is not None else None
        stats["feedback_count"] = feedback_row["c"]
        recent_30 = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
        stats["feedback_count_recent"] = conn.execute(
            "SELECT COUNT(*) AS c FROM guest_feedback WHERE submitted_at >= ?", (recent_30,)
        ).fetchone()["c"]
        stats["waitlist_open"] = conn.execute(
            "SELECT COUNT(*) AS c FROM waitlist_entries WHERE status IN ('open', 'contacted')"
        ).fetchone()["c"]
        last_backup = conn.execute(
            "SELECT created_at FROM audit_log WHERE action IN ('backup_downloaded', 'backup_auto_sent') "
            "ORDER BY created_at DESC LIMIT 1"
        ).fetchone()
        last_backup_at = last_backup["created_at"] if last_backup else None
        backup_stale = (not last_backup_at) or (parse_date(last_backup_at[:10]) <= today - timedelta(days=30))
        current_month_financials = financial_month_summary(
            conn, today.replace(day=1),
            date(today.year + 1, 1, 1) if today.month == 12 else date(today.year, today.month + 1, 1),
        )
        financial_trend_months = financial_trend(conn, 6, today)
        financial_trend_max = max(
            [m["revenue"] for m in financial_trend_months] + [m["expenses_total"] for m in financial_trend_months] + [1]
        )
        dashboard_calendar = build_dashboard_calendar(conn, today)
        recent_30_feedback = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
        low_ratings = conn.execute(
            """SELECT guest_feedback.*, bookings.reference_code FROM guest_feedback
               LEFT JOIN bookings ON bookings.id = guest_feedback.booking_id
               WHERE rating <= 2 AND submitted_at >= ? ORDER BY submitted_at DESC""",
            (recent_30_feedback,),
        ).fetchall()
        anniversaries = upcoming_anniversaries(conn, today)
        probation_due = probation_reviews_due(conn, today)
        reviews_due = annual_reviews_due(conn, today)
        unstaffed_days = unstaffed_activity_days(conn, today)
        overtime = week_overtime(conn, today)
        activity = recent_activity(conn)
        soon = (today + timedelta(days=30)).isoformat()
        expiring_docs = (
            [dict(d, kind="Employee doc")
             for d in conn.execute(
                 """SELECT documents.*, users.name AS employee_name FROM documents
                    JOIN users ON users.id = documents.user_id
                    WHERE expiry_date IS NOT NULL AND expiry_date <= ? ORDER BY expiry_date""",
                 (soon,),
             ).fetchall()]
            + [dict(d, kind="Company doc", employee_name=None)
               for d in conn.execute(
                   "SELECT * FROM company_documents WHERE expiry_date IS NOT NULL AND expiry_date <= ? ORDER BY expiry_date",
                   (soon,),
               ).fetchall()]
            + [{"title": p["provider"] + (f" ({p['coverage_type']})" if p["coverage_type"] else ""),
                "kind": "Insurance", "employee_name": None, "expiry_date": p["expiry_date"]}
               for p in conn.execute(
                   "SELECT * FROM insurance_policies WHERE expiry_date IS NOT NULL AND expiry_date <= ? ORDER BY expiry_date",
                   (soon,),
               ).fetchall()]
            + [{"title": f"{c['label']} — €{c['amount']:.0f}", "kind": "Recurring cost",
                "employee_name": None, "expiry_date": c["next_due_date"]}
               for c in conn.execute(
                   """SELECT * FROM recurring_costs WHERE active = 1 AND next_due_date IS NOT NULL
                      AND next_due_date <= ? ORDER BY next_due_date""",
                   (soon,),
               ).fetchall()]
        )
        expiring_docs.sort(key=lambda d: d["expiry_date"])
        my_expiring_docs = []
        my_week_hours = None
        my_month_hours = None
        vehicle_alerts = (
            [{"title": v["name"], "detail": "dirty"} for v in conn.execute(
                "SELECT name FROM vehicles WHERE cleanliness = 'dirty' ORDER BY name"
            ).fetchall()]
            + [{"title": v["name"], "detail": "low fuel"} for v in conn.execute(
                "SELECT name FROM vehicles WHERE fuel_level = 'low' ORDER BY name"
            ).fetchall()]
            + [{"title": v["name"], "detail": f"service due {v['next_service_due']}"} for v in conn.execute(
                "SELECT name, next_service_due FROM vehicles WHERE next_service_due IS NOT NULL AND next_service_due <= ? ORDER BY next_service_due",
                (soon,),
            ).fetchall()]
            + [{"title": c["vehicle_name"], "detail": f"out since {c['checked_out_at'][:10]} with {c['user_name'] or 'unknown'}"}
               for c in overdue_vehicle_checkouts(conn)]
        )
        breakfast_low_stock = conn.execute(
            "SELECT name FROM breakfast_items WHERE low_stock = 1 ORDER BY name"
        ).fetchall()
        restaurant_alerts = []
        restaurant_settings_row = get_restaurant_settings(conn)
        if restaurant_settings_row:
            pending_dinners_count = conn.execute(
                "SELECT COUNT(*) AS c FROM restaurant_bookings WHERE status = 'pending'"
            ).fetchone()["c"]
            if pending_dinners_count:
                restaurant_alerts.append({"title": "Dinner reservations awaiting a decision", "detail": str(pending_dinners_count), "link": url_for("admin_restaurant")})
            opening = parse_date(restaurant_settings_row["opening_date"]) if restaurant_settings_row["opening_date"] else None
            if opening and today < opening <= today + timedelta(days=14):
                restaurant_alerts.append({"title": "Restaurant opens soon", "detail": f"{(opening - today).days} day(s) — {opening.isoformat()}", "link": url_for("admin_restaurant")})
        pending_workshop_regs = conn.execute(
            "SELECT COUNT(*) AS c FROM workshop_bookings WHERE status = 'pending'"
        ).fetchone()["c"]
        if pending_workshop_regs:
            restaurant_alerts.append({"title": "Workshop registrations awaiting a decision", "detail": str(pending_workshop_regs), "link": url_for("admin_workshop_registrations")})
        balances_due_soon = conn.execute(
            """SELECT COUNT(*) AS c FROM workshop_bookings WHERE status = 'confirmed'
               AND balance_amount > 0 AND balance_paid_at IS NULL
               AND balance_due_date IS NOT NULL AND balance_due_date <= ?""",
            ((today + timedelta(days=7)).isoformat(),),
        ).fetchone()["c"]
        if balances_due_soon:
            restaurant_alerts.append({"title": "Workshop balances due within 7 days", "detail": str(balances_due_soon), "link": url_for("admin_workshop_registrations")})
        new_event_inquiries = conn.execute(
            "SELECT COUNT(*) AS c FROM event_inquiries WHERE status = 'new'"
        ).fetchone()["c"]
        if new_event_inquiries:
            restaurant_alerts.append({"title": "New event inquiries", "detail": str(new_event_inquiries), "link": url_for("admin_events")})
    else:
        month_stats = None
        team = []
        on_shift_now = []
        who_is_off_today = []
        last_backup_at = None
        backup_stale = False
        current_month_financials = None
        low_ratings = []
        anniversaries = []
        probation_due = []
        reviews_due = []
        unstaffed_days = []
        expiring_docs = []
        overtime = []
        activity = []
        vehicle_alerts = []
        breakfast_low_stock = []
        restaurant_alerts = []
        current_tasks_by_user = {}
        financial_trend_months = []
        financial_trend_max = 1
        dashboard_calendar = {"weeks": [], "month_start": today}
        stats["my_expenses_pending"] = conn.execute(
            "SELECT COUNT(*) AS c FROM expenses WHERE submitted_by_user_id = ? AND status = 'pending'",
            (user["id"],),
        ).fetchone()["c"]
        soon = (today + timedelta(days=30)).isoformat()
        my_expiring_docs = conn.execute(
            "SELECT * FROM documents WHERE user_id = ? AND expiry_date IS NOT NULL AND expiry_date <= ? ORDER BY expiry_date",
            (user["id"], soon),
        ).fetchall()
        week_ago_iso = (datetime.now(timezone.utc) - timedelta(days=7)).isoformat()
        month_ago_iso = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
        my_hours_entries = conn.execute(
            "SELECT * FROM time_entries WHERE user_id = ? AND clock_in_at >= ? AND clock_out_at IS NOT NULL",
            (user["id"], month_ago_iso),
        ).fetchall()
        my_hours_map = net_hours_for_entries(conn, my_hours_entries)
        my_week_hours = round(sum(my_hours_map.get(r["id"], 0.0) for r in my_hours_entries
                                  if r["clock_in_at"] >= week_ago_iso), 2)
        my_month_hours = round(sum(my_hours_map.values()), 2)
        # Today's view: what's due today, overdue, or has no date yet — never
        # a future date, so this never turns into a forward-looking calendar.
        my_tasks = conn.execute(
            """SELECT * FROM tasks WHERE assigned_to_user_id = ? AND status != 'done'
               AND (due_date IS NULL OR due_date <= ?)
               ORDER BY (due_date IS NULL), due_date""",
            (user["id"], today.isoformat()),
        ).fetchall()

    my_upcoming_shifts = []
    if user["role"] != "owner":
        my_upcoming_shifts = conn.execute(
            "SELECT * FROM shifts WHERE user_id = ? AND shift_date >= ? ORDER BY shift_date, start_time LIMIT 7",
            (user["id"], today.isoformat()),
        ).fetchall()

    # The chef/partner running the restaurant are regular employees with no
    # owner access — this is their only view into tonight's covers without
    # asking the owner or waiting for the printed ops sheet.
    my_tonights_dinners = []
    is_restaurant_lead = False
    if user["role"] != "owner":
        restaurant_settings_row = get_restaurant_settings(conn)
        is_restaurant_lead = bool(restaurant_settings_row and restaurant_settings_row["lead_user_id"] == user["id"])
        if is_restaurant_lead:
            my_tonights_dinners = conn.execute(
                "SELECT * FROM restaurant_bookings WHERE status = 'confirmed' AND dinner_date = ? ORDER BY guest_name",
                (today.isoformat(),),
            ).fetchall()

    # Any employee can be assigned a dinner-service shift, not just the
    # restaurant lead — this is their own view of it, same "what do I need
    # to know" scope as my_upcoming_shifts above.
    my_restaurant_shifts = []
    if user["role"] != "owner":
        my_restaurant_shifts = conn.execute(
            "SELECT * FROM restaurant_shifts WHERE user_id = ? AND dinner_date >= ? ORDER BY dinner_date LIMIT 5",
            (user["id"], today.isoformat()),
        ).fetchall()

    # Same idea for a workshop instructor who's on staff — their own view
    # into upcoming sessions they're teaching, without owner access.
    my_upcoming_sessions = []
    my_next_session = None
    my_next_session_roster = []
    if user["role"] != "owner":
        my_upcoming_sessions = conn.execute(
            """SELECT workshop_sessions.*, workshops.title,
                   (SELECT COALESCE(SUM(party_size), 0) FROM workshop_bookings
                    WHERE session_id = workshop_sessions.id AND status = 'confirmed') AS covers
               FROM workshop_sessions JOIN workshops ON workshops.id = workshop_sessions.workshop_id
               WHERE workshops.instructor_user_id = ? AND workshop_sessions.end_date >= ?
               ORDER BY workshop_sessions.start_date LIMIT 5""",
            (user["id"], today.isoformat()),
        ).fetchall()
        if my_upcoming_sessions:
            my_next_session = my_upcoming_sessions[0]
            my_next_session_roster = conn.execute(
                """SELECT workshop_bookings.*, rooms.name AS room_name
                   FROM workshop_bookings LEFT JOIN rooms ON rooms.id = workshop_bookings.assigned_room_id
                   WHERE workshop_bookings.session_id = ? AND workshop_bookings.status = 'confirmed'
                   ORDER BY workshop_bookings.guest_name""",
                (my_next_session["id"],),
            ).fetchall()

    # The owner's Home is a different screen from a member of staff's, because
    # the questions are different: an owner opens this to decide things, and
    # staff open it to find out what they are doing. Employees keep the existing
    # dashboard untouched.
    if user["role"] == "owner":
        day_rows = owner_home_day(conn, today, user)
        revenue, revenue_budget, revenue_budget_pct = owner_home_revenue(conn, today)
        occupancy, occupancy_lead, occupancy_avg = owner_home_occupancy(conn, today)
        queue = owner_home_queue(conn)
        warnings = owner_home_warnings(conn, today)
        hour = datetime.now(timezone.utc).hour
        greeting = ("Good morning" if hour < 12 else
                    "Good afternoon" if hour < 18 else "Good evening")
        # One sentence saying whether anything needs doing, built from the same
        # figures shown below it so the two can never disagree.
        bits = []
        if queue:
            # Verb agrees with the count, or the owner's own dashboard greets
            # them with a typo every morning there is exactly one thing to do.
            bits.append(f"{len(queue)} thing needs a decision" if len(queue) == 1
                        else f"{len(queue)} things need a decision")
        # Said before the room count, because "two rooms are occupied" is
        # information and "nobody is on tomorrow" is a problem.
        if warnings:
            blockers = [w for w in warnings if w["severity"] == "blocker"]
            n = len(blockers) or len(warnings)
            word = "needs" if n == 1 else "need"
            bits.append(f"{n} thing {word} looking at" if n == 1
                        else f"{n} things {word} looking at")
        occ_now = sum(1 for g in owner_home_guests(conn, today) for _ in [1])
        rooms_n = conn.execute(
            "SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"] or 0
        if rooms_n:
            bits.append(f"{occ_now} of {rooms_n} rooms is occupied" if occ_now == 1
                        else f"{occ_now} of {rooms_n} rooms are occupied")
        # "Everything on today is done" is only true if there was something to
        # do. With an empty day it reads as an achievement rather than as an
        # empty diary, which is the opposite of what the owner needs to know.
        undone = sum(1 for r in day_rows if not r["done"])
        if not day_rows:
            bits.append("nothing is scheduled for today")
        elif undone:
            bits.append(f"{undone} thing{'s' if undone != 1 else ''} left on today")
        else:
            bits.append("everything on today is done")
        hero_line = ", and ".join([", ".join(bits[:-1]), bits[-1]]) if len(bits) > 1 else bits[0]
        hero_line = hero_line[0].upper() + hero_line[1:] + "."
        page = render_template(
            "owner_home.html", user=user, today=today,
            greeting=greeting, hero_line=hero_line,
            figures=owner_home_figures(conn, today),
            next_up=owner_home_next_up(conn, today, day_rows),
            queue=queue, warnings=warnings,
            queue_money=[q for q in queue if q["tone"] == "money"],
            queue_people=[q for q in queue if q["tone"] != "money"],
            bulk_count=sum(1 for q in queue if q["bulk_eligible"]),
            day=day_rows,
            day_done=sum(1 for r in day_rows if r["done"]),
            revenue=revenue, revenue_budget=revenue_budget,
            revenue_budget_pct=revenue_budget_pct,
            revenue_now=(revenue[-1]["value"] if revenue else 0),
            revenue_prev=(revenue[-2]["value"] if len(revenue) > 1 else 0),
            occupancy=occupancy, occupancy_lead=occupancy_lead,
            occupancy_avg=occupancy_avg,
            guests=owner_home_guests(conn, today),
            rooms_total=conn.execute(
                "SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"] or 0,
            my_shift=my_shift,
        )
        conn.close()
        return page

    conn.close()
    return render_template(
        "dashboard.html", team=team, stats=stats, briefing=briefing, my_tasks=my_tasks,
        who_is_here=who_is_here, today=today, month_stats=month_stats,
        my_upcoming_shifts=my_upcoming_shifts, who_is_off_today=who_is_off_today,
        on_shift_by_user=on_shift_by_user, on_shift_now=on_shift_now, my_shift=my_shift,
        anniversaries=anniversaries, probation_due=probation_due, unstaffed_days=unstaffed_days,
        reviews_due=reviews_due,
        expiring_docs=expiring_docs, overtime=overtime,
        my_open_break=my_open_break, activity=activity, announcements_current=announcements_current,
        my_expiring_docs=my_expiring_docs, my_week_hours=my_week_hours, my_month_hours=my_month_hours,
        backup_stale=backup_stale, last_backup_at=last_backup_at,
        current_month_financials=current_month_financials, low_ratings=low_ratings,
        vehicle_alerts=vehicle_alerts, breakfast_low_stock=breakfast_low_stock,
        restaurant_alerts=restaurant_alerts, is_restaurant_lead=is_restaurant_lead,
        my_tonights_dinners=my_tonights_dinners, my_restaurant_shifts=my_restaurant_shifts,
        my_upcoming_sessions=my_upcoming_sessions,
        my_next_session=my_next_session, my_next_session_roster=my_next_session_roster,
        current_tasks_by_user=current_tasks_by_user, financial_trend_months=financial_trend_months,
        financial_trend_max=financial_trend_max, dashboard_calendar=dashboard_calendar,
    )


@app.route("/admin/display")
def office_display():
    # A kiosk device authenticates with ?token=OFFICE_DISPLAY_TOKEN instead of a
    # login session, since it's meant to sit on a wall reloading itself
    # unattended for weeks. Anyone with a normal owner session still gets in
    # without one, same as before.
    supplied_token = request.args.get("token", "")
    token_ok = OFFICE_DISPLAY_TOKEN and hmac.compare_digest(supplied_token, OFFICE_DISPLAY_TOKEN)
    if not token_ok:
        user = current_user()
        if not user:
            return redirect(url_for("login"))
        if user["role"] != "owner":
            abort(403)

    conn = get_db()
    today = datetime.now(timezone.utc).date()

    on_shift_now = [
        dict(r, initials="".join(w[0] for w in r["user_name"].split()[:2]).upper())
        for r in conn.execute(
            """SELECT time_entries.*, users.name AS user_name, users.job_role AS user_job_role
               FROM time_entries JOIN users ON users.id = time_entries.user_id
               WHERE time_entries.clock_out_at IS NULL
               ORDER BY time_entries.clock_in_at"""
        ).fetchall()
    ]
    current_tasks_by_user = {}
    for t in conn.execute(
        """SELECT * FROM tasks WHERE status != 'done' AND assigned_to_user_id IS NOT NULL
           AND (due_date IS NULL OR due_date <= ?) ORDER BY (due_date IS NULL), due_date""",
        (today.isoformat(),),
    ).fetchall():
        current_tasks_by_user.setdefault(t["assigned_to_user_id"], []).append(t)

    who_is_here = guests_in_residence(conn, today)

    overview_today = build_overview(conn, "day", today)
    dashboard_calendar = build_dashboard_calendar(conn, today)
    today_stats = build_office_display_stats(conn, today, who_is_here)
    queues = build_office_display_queues(conn, today)
    queues_total = sum(q["count"] for q in queues)

    conn.close()
    return render_template(
        "admin_office_display.html",
        today=today,
        on_shift_now=on_shift_now,
        current_tasks_by_user=current_tasks_by_user,
        who_is_here=who_is_here,
        overview_today=overview_today,
        dashboard_calendar=dashboard_calendar,
        today_stats=today_stats,
        queues=queues,
        queues_total=queues_total,
    )


@app.route("/search")
@owner_required
def search():
    q = request.args.get("q", "").strip()
    results = {"guests": [], "employees": [], "tasks": [], "rooms": [], "vendors": [],
               "recurring_costs": [], "company_info": [], "waitlist": [], "vehicles": [],
               "restaurant_bookings": [], "workshop_bookings": [], "social_posts": [],
               "event_inquiries": [], "promo_codes": []}
    if q:
        needle = f"%{q}%"
        conn = get_db()
        results["guests"] = conn.execute(
            """SELECT * FROM guests
               WHERE name LIKE ? OR notes LIKE ? OR email LIKE ? OR phone LIKE ?
                  OR preferences LIKE ? OR dietary_notes LIKE ?
               ORDER BY name LIMIT 20""",
            (needle,) * 6,
        ).fetchall()
        results["employees"] = conn.execute(
            "SELECT * FROM users WHERE role = 'employee' AND (name LIKE ? OR job_role LIKE ?) ORDER BY name LIMIT 20",
            (needle, needle),
        ).fetchall()
        results["tasks"] = conn.execute(
            """SELECT tasks.*, users.name AS assigned_to_name FROM tasks
               LEFT JOIN users ON users.id = tasks.assigned_to_user_id
               WHERE tasks.title LIKE ? OR tasks.notes LIKE ? ORDER BY tasks.due_date DESC LIMIT 20""",
            (needle, needle),
        ).fetchall()
        results["rooms"] = conn.execute(
            "SELECT * FROM rooms WHERE name LIKE ? ORDER BY sort_order LIMIT 20", (needle,)
        ).fetchall()
        results["vendors"] = conn.execute(
            "SELECT * FROM vendors WHERE name LIKE ? OR contact_person LIKE ? OR notes LIKE ? ORDER BY name LIMIT 20",
            (needle, needle, needle),
        ).fetchall()
        results["recurring_costs"] = conn.execute(
            "SELECT * FROM recurring_costs WHERE label LIKE ? OR category LIKE ? ORDER BY label LIMIT 20",
            (needle, needle),
        ).fetchall()
        results["waitlist"] = conn.execute(
            "SELECT * FROM waitlist_entries WHERE name LIKE ? OR email LIKE ? ORDER BY created_at DESC LIMIT 20",
            (needle, needle),
        ).fetchall()
        results["vehicles"] = conn.execute(
            "SELECT * FROM vehicles WHERE name LIKE ? OR vehicle_type LIKE ? OR license_plate LIKE ? ORDER BY name LIMIT 20",
            (needle, needle, needle),
        ).fetchall()
        results["restaurant_bookings"] = conn.execute(
            "SELECT * FROM restaurant_bookings WHERE guest_name LIKE ? OR reference_code LIKE ? OR guest_email LIKE ? "
            "ORDER BY dinner_date DESC LIMIT 20",
            (needle, needle, needle),
        ).fetchall()
        results["workshop_bookings"] = conn.execute(
            """SELECT workshop_bookings.*, workshops.title AS workshop_title FROM workshop_bookings
               JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
               JOIN workshops ON workshops.id = workshop_sessions.workshop_id
               WHERE workshop_bookings.guest_name LIKE ? OR workshop_bookings.reference_code LIKE ?
                  OR workshop_bookings.guest_email LIKE ? OR workshops.title LIKE ?
               ORDER BY workshop_bookings.created_at DESC LIMIT 20""",
            (needle, needle, needle, needle),
        ).fetchall()
        results["social_posts"] = conn.execute(
            "SELECT * FROM social_posts WHERE caption LIKE ? OR platform LIKE ? "
            "ORDER BY (scheduled_date IS NULL), scheduled_date DESC LIMIT 20",
            (needle, needle),
        ).fetchall()
        results["event_inquiries"] = conn.execute(
            "SELECT * FROM event_inquiries WHERE contact_name LIKE ? OR contact_email LIKE ? "
            "OR reference_code LIKE ? OR event_type LIKE ? ORDER BY created_at DESC LIMIT 20",
            (needle, needle, needle, needle),
        ).fetchall()
        results["promo_codes"] = conn.execute(
            "SELECT * FROM promo_codes WHERE code LIKE ? OR description LIKE ? ORDER BY created_at DESC LIMIT 20",
            (needle, needle),
        ).fetchall()
        info = conn.execute("SELECT * FROM company_info WHERE id = 1").fetchone()
        if info and any(
            q.lower() in (info[f] or "").lower()
            for f in ("legal_name", "registration_number", "vat_number", "registered_address",
                       "accountant_name", "insurance_broker_name")
        ):
            results["company_info"] = [info]
        conn.close()
    total = sum(len(v) for v in results.values())
    return render_template("search_results.html", q=q, results=results, total=total)


# ---------------------------------------------------------------------------
# Directory (owner: manage everyone / employee: view own profile)
# ---------------------------------------------------------------------------

@app.route("/directory")
@login_required
def directory():
    user = current_user()
    conn = get_db()
    status_filter = request.args.get("status", "").strip()
    q = request.args.get("q", "").strip()

    period = period_from_request()
    overview = None
    if user["role"] == "owner":
        overview = employee_overview(conn, period, datetime.now(timezone.utc).date())
        employees = conn.execute(
            "SELECT * FROM users WHERE role = 'employee' ORDER BY status, name"
        ).fetchall()
    else:
        # A colleague lookup, not an admin tool — active staff only, and
        # the query itself only asks for the fields safe to show a
        # coworker (no pay/notes/etc.), rather than relying on the
        # template to not render fields off a wider SELECT *.
        employees = conn.execute(
            "SELECT id, name, job_role, phone, status, account_claimed FROM users "
            "WHERE role = 'employee' AND status = 'active' ORDER BY name"
        ).fetchall()
    on_shift_ids = {
        r["user_id"] for r in conn.execute("SELECT user_id FROM time_entries WHERE clock_out_at IS NULL").fetchall()
    }
    conn.close()

    if status_filter:
        employees = [e for e in employees if e["status"] == status_filter]
    if q:
        needle = q.lower()
        employees = [
            e for e in employees
            if needle in e["name"].lower() or needle in (e["job_role"] or "").lower()
        ]

    return render_template(
        "directory.html", employees=employees, status_filter=status_filter, q=q, on_shift_ids=on_shift_ids,
        overview=overview, period=period,
    )


