@app.route("/admin/restaurant/tables/new", methods=["POST"])
@owner_required
def new_dining_table():
    label = (request.form.get("label", "") or "").strip()
    area = (request.form.get("area", "") or "salle").strip()
    if not label:
        flash("Give the table a number or a name.", "error")
        return redirect(url_for("admin_dining_tables"))
    if area not in dict(DINING_AREAS):
        area = "salle"
    try:
        seats = max(1, int(request.form.get("seats", "2") or 2))
    except ValueError:
        seats = 2
    conn = get_db()
    # The label is what the floor screen and every closed tab shows, so two
    # tables called "4" would make the room unreadable rather than just untidy.
    if conn.execute("SELECT 1 FROM restaurant_tables WHERE label = ?", (label,)).fetchone():
        conn.close()
        flash(f"There is already a table called {label}.", "error")
        return redirect(url_for("admin_dining_tables"))
    nxt = conn.execute(
        "SELECT COALESCE(MAX(sort_order), -1) + 1 AS n FROM restaurant_tables").fetchone()["n"]
    conn.execute(
        """INSERT INTO restaurant_tables (label, area, seats, sort_order, active, created_at)
           VALUES (?, ?, ?, ?, 1, ?)""",
        (label, area, seats, nxt, datetime.now(timezone.utc).isoformat()))
    conn.commit()
    conn.close()
    flash(f"Table {label} added.", "success")
    return redirect(url_for("admin_dining_tables"))


@app.route("/admin/restaurant/tables/<int:table_id>/save", methods=["POST"])
@owner_required
def save_dining_table(table_id):
    conn = get_db()
    table = conn.execute("SELECT * FROM restaurant_tables WHERE id = ?", (table_id,)).fetchone()
    if not table:
        conn.close()
        abort(404)
    label = (request.form.get("label", "") or "").strip() or table["label"]
    area = (request.form.get("area", "") or table["area"]).strip()
    if area not in dict(DINING_AREAS):
        area = table["area"]
    try:
        seats = max(1, int(request.form.get("seats", "") or table["seats"]))
    except ValueError:
        seats = table["seats"]
    clash = conn.execute(
        "SELECT 1 FROM restaurant_tables WHERE label = ? AND id != ?", (label, table_id)).fetchone()
    if clash:
        conn.close()
        flash(f"There is already a table called {label}.", "error")
        return redirect(url_for("admin_dining_tables"))
    conn.execute(
        "UPDATE restaurant_tables SET label = ?, area = ?, seats = ? WHERE id = ?",
        (label, area, seats, table_id))
    conn.commit()
    conn.close()
    flash("Floor plan updated.", "success")
    return redirect(url_for("admin_dining_tables"))


@app.route("/admin/restaurant/tables/<int:table_id>/retire", methods=["POST"])
@owner_required
def retire_dining_table(table_id):
    """Take a table off the floor, or delete one added by mistake.

    A table that has carried a tab is retired rather than deleted: the orders
    reference it, and last August's closed tabs are payroll-grade history in the
    same way a settled total is. One nobody ever sat at is just a typo, so it
    goes.
    """
    conn = get_db()
    table = conn.execute("SELECT * FROM restaurant_tables WHERE id = ?", (table_id,)).fetchone()
    if not table:
        conn.close()
        abort(404)
    running = conn.execute(
        "SELECT 1 FROM pos_orders WHERE table_id = ? AND status = 'open'", (table_id,)).fetchone()
    if running:
        conn.close()
        flash(f"Table {table['label']} has a tab open on it. Settle that first.", "error")
        return redirect(url_for("admin_dining_tables"))
    used = conn.execute(
        "SELECT 1 FROM pos_orders WHERE table_id = ? LIMIT 1", (table_id,)).fetchone()
    if used:
        conn.execute("UPDATE restaurant_tables SET active = 0 WHERE id = ?", (table_id,))
        msg = f"Table {table['label']} taken off the floor. Its past tabs are untouched."
    else:
        conn.execute("DELETE FROM restaurant_tables WHERE id = ?", (table_id,))
        msg = f"Table {table['label']} removed."
    conn.commit()
    conn.close()
    flash(msg, "success")
    return redirect(url_for("admin_dining_tables"))


@app.route("/admin/restaurant/tables/<int:table_id>/restore", methods=["POST"])
@owner_required
def restore_dining_table(table_id):
    conn = get_db()
    if not conn.execute("SELECT 1 FROM restaurant_tables WHERE id = ?", (table_id,)).fetchone():
        conn.close()
        abort(404)
    conn.execute("UPDATE restaurant_tables SET active = 1 WHERE id = ?", (table_id,))
    conn.commit()
    conn.close()
    flash("Table back on the floor.", "success")
    return redirect(url_for("admin_dining_tables"))


@app.route("/pos/open", methods=["POST"])
@login_required
def pos_open_tab():
    label = (request.form.get("table_label", "") or "").strip()
    booking_id = (request.form.get("restaurant_booking_id", "") or "").strip()
    table_id = (request.form.get("table_id", "") or "").strip()
    try:
        covers = max(1, int(request.form.get("covers", "2") or 2))
    except ValueError:
        covers = 2
    conn = get_db()
    # Tapping a table is the normal way to open a tab: the label comes off the
    # table and the covers default to what it seats, so seating a walk-in is one
    # touch and nobody types on a tablet in the middle of service. A table that
    # is already occupied is refused rather than opening a second tab on it.
    table = None
    if table_id.isdigit():
        table = conn.execute(
            "SELECT * FROM restaurant_tables WHERE id = ? AND active = 1",
            (int(table_id),)).fetchone()
        if not table:
            conn.close()
            flash("That table is not on the floor plan.", "error")
            return redirect(url_for("pos_home"))
        busy = conn.execute(
            """SELECT id FROM pos_orders
               WHERE status = 'open'
                 AND (table_id = ?
                      OR (table_id IS NULL
                          AND lower(trim(table_label)) = lower(trim(?))))""",
            (table["id"], table["label"])).fetchone()
        if busy:
            conn.close()
            flash(f"Table {table['label']} is already open — that tab is still running.",
                  "error")
            return redirect(url_for("pos_order", order_id=busy["id"]))
        label = label or table["label"]
        if not request.form.get("covers"):
            covers = table["seats"] or covers

    booking = None
    if booking_id.isdigit():
        booking = conn.execute("SELECT * FROM restaurant_bookings WHERE id = ?",
                               (booking_id,)).fetchone()
        if booking:
            # The reservation knows how many are coming; the table only knows
            # how many it holds.
            covers = booking["party_size"] or covers
            label = label or booking["guest_name"]
    if not label:
        conn.close()
        flash("Pick a table, or name one.", "error")
        return redirect(url_for("pos_home"))
    # A deposit already taken at booking is credited to the tab, so a table
    # that paid to reserve is not charged for it twice. The old till had no
    # idea a deposit existed.
    deposit = round(booking["deposit_amount"] or 0, 2) if booking else 0
    conn.execute(
        """INSERT INTO pos_orders (table_label, table_id, covers, restaurant_booking_id, status,
           service_state, deposit_credit, service_date, opened_by_user_id, opened_at)
           VALUES (?, ?, ?, ?, 'open', 'seated', ?, ?, ?, ?)""",
        (label, table["id"] if table else None, covers,
         booking["id"] if booking else None, deposit,
         # The night it belongs to, fixed at open. A tab started at 23:50 and
         # settled at 00:10 belongs to one service, not two — which is what
         # service_day_iso() gives and the UTC calendar date does not: past
         # midnight it rolls, so a tab opened at half past one was stamped
         # with tomorrow and landed on tomorrow's takings, tomorrow's closure
         # and tomorrow's menu. That is the bug the service day exists to
         # remove, and this line was still the old way round.
         service_day_iso(),
         session.get("user_id"), datetime.now(timezone.utc).isoformat()))
    order_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
    conn.commit()
    conn.close()
    if deposit:
        flash(f"Table open. €{deposit:.2f} deposit already paid has been credited.", "success")
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>")
@login_required
def pos_order(order_id):
    conn = get_db()
    bill = pos_bill(conn, order_id)
    if not bill:
        conn.close()
        abort(404)
    menu = pos_menu(conn, service_date=bill["order"]["service_date"])
    rates = {}
    for items in menu.values():
        for i in items:
            key = i["menu_dish_id"] or i["id"]
            if key is not None:
                rates[key] = menu_vat_rate(conn, i)
    stock = stock_levels(conn, [i["stock_item_id"] for items in menu.values()
                                for i in items if i.get("stock_item_id")])
    context = pos_table_context(conn, bill["order"])
    in_house = conn.execute(
        """SELECT id, guest_name, reference_code, room_id FROM bookings
           WHERE status = 'confirmed' AND arrival_date <= ? AND departure_date >= ?
           ORDER BY guest_name""",
        (datetime.now(timezone.utc).date().isoformat(),
         datetime.now(timezone.utc).date().isoformat())).fetchall()
    payments = conn.execute(
        """SELECT pos_payments.*, users.name AS taken_by FROM pos_payments
           LEFT JOIN users ON users.id = pos_payments.taken_by_user_id
           WHERE order_id = ? ORDER BY id""", (order_id,)).fetchall()
    other_tables = conn.execute(
        "SELECT id, table_label FROM pos_orders WHERE status = 'open' AND id != ? ORDER BY table_label",
        (order_id,)).fetchall()
    # The set menu for tonight, if there is one — the panel only shows when a
    # published card actually carries a price.
    card = menu_for_date(conn, bill["order"]["service_date"]) if bill["order"]["service_date"] else None
    formule_menu = card if (card and card["formule_price"]) else None
    formules = pos_formules_for(conn, order_id)
    formule_choices = {}
    if formule_menu:
        formule_choices = menu_dishes_for(conn, formule_menu["id"], include_unavailable=False)
    packages = conn.execute(
        "SELECT * FROM drink_packages WHERE active = 1 ORDER BY name").fetchall()
    # Marks the buttons and re-checks what is already on the bill, so the note
    # taken at booking is on the screen the order is actually tapped into.
    diet = mark_dietary_risk(menu, bill["lines"], context["dietary"] if context else "")
    reader_on = terminal_ready(conn)
    conn.close()
    return render_template(
        "pos_order.html", bill=bill, order=bill["order"], lines=bill["lines"],
        menu=menu, courses=MENU_COURSES, vat_rates=rates, stock=stock,
        by_course=pos_lines_by_course([l for l in bill["lines"] if not l["voided"]]),
        context=context, in_house=in_house, payments=payments,
        payment_methods=POS_PAYMENT_METHODS, void_reasons=POS_VOID_REASONS,
        line_states=POS_LINE_STATES, service_states=POS_SERVICE_STATES,
        allergens=ALLERGENS, other_tables=other_tables,
        formule_menu=formule_menu, formules=formules, formule_choices=formule_choices,
        packages=packages, diet=diet, reader_on=reader_on)


@app.route("/pos/<int:order_id>/add", methods=["POST"])
@login_required
def pos_add_item(order_id):
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order or order["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))

    menu_item_id = (request.form.get("menu_item_id", "") or "").strip()
    extra_id = (request.form.get("extra_id", "") or "").strip()
    notes = (request.form.get("notes", "") or "").strip() or None
    seat = (request.form.get("seat_number", "") or "").strip()
    seat = int(seat) if seat.isdigit() else None
    try:
        quantity = max(1, int(request.form.get("quantity", "1") or 1))
    except ValueError:
        quantity = 1

    menu_dish_id = (request.form.get("menu_dish_id", "") or "").strip()
    if menu_dish_id.isdigit():
        # A dish off tonight's card. Priced and taxed from the card, and the
        # line keeps a pointer to the exact dish so "what did table 6 eat on
        # the 10th" survives tomorrow's menu replacing this one.
        dish = conn.execute("SELECT * FROM menu_dishes WHERE id = ?", (menu_dish_id,)).fetchone()
        if not dish:
            conn.close()
            abort(404)
        if not dish["available"]:
            conn.close()
            flash(f"{dish['name']} is off tonight"
                  + (f" — {dish['unavailable_note']}" if dish["unavailable_note"] else "") + ".",
                  "error")
            return redirect(url_for("pos_order", order_id=order_id))
        pos_add_card_line(conn, order_id, dish, quantity, notes=notes, seat=seat,
                          user_id=session.get("user_id"))
    elif menu_item_id.isdigit():
        item = conn.execute("SELECT * FROM menu_items WHERE id = ?", (menu_item_id,)).fetchone()
        if not item:
            conn.close()
            abort(404)
        if not item["available"]:
            conn.close()
            flash(f"{item['name']} is off tonight"
                  + (f" — {item['unavailable_note']}" if item["unavailable_note"] else "") + ".",
                  "error")
            return redirect(url_for("pos_order", order_id=order_id))
        pos_add_menu_line(conn, order_id, item, quantity, notes=notes, seat=seat,
                          user_id=session.get("user_id"))
    elif extra_id.isdigit():
        extra = conn.execute("SELECT * FROM extras WHERE id = ?", (extra_id,)).fetchone()
        if not extra:
            conn.close()
            abort(404)
        line_id = pos_add_line(conn, order_id, extra, quantity, notes=notes,
                               user_id=session.get("user_id"))
        conn.execute("UPDATE pos_order_lines SET course = 'drink', seat_number = ?, vat_rate = ? "
                     "WHERE id = ?", (seat, tax_rate(conn, "vat_extras"), line_id))
    else:
        name = (request.form.get("name", "") or "").strip()
        if not name:
            conn.close()
            flash("Give the item a name.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        try:
            price = float((request.form.get("unit_price", "0") or "0").replace(",", "."))
        except ValueError:
            price = 0.0
        line_id = pos_add_line(conn, order_id, name, quantity, unit_price=price,
                               notes=notes, user_id=session.get("user_id"))
        conn.execute(
            "UPDATE pos_order_lines SET course = ?, seat_number = ?, vat_rate = ? WHERE id = ?",
            (request.form.get("course", "main"), seat, tax_rate(conn, "vat_food"), line_id))
    # A new drink may fall inside the allowance, so the package has to be
    # reconsidered on every add rather than only when it was attached.
    if order["package_id"]:
        apply_package(conn, order_id)
    conn.commit()
    conn.close()
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>/package", methods=["POST"])
@login_required
def pos_set_package(order_id):
    """Put a beverage package on a table, or take it off.

    Recomputed rather than accumulated, so removing it releases everything it
    was holding — an allowance that only ever went down would quietly
    overcharge the next drink ordered.
    """
    raw = (request.form.get("package_id", "") or "").strip()
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order or order["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))
    package_id = int(raw) if raw.isdigit() else None
    if package_id and not package_for(conn, package_id):
        conn.close()
        abort(404)
    conn.execute("UPDATE pos_orders SET package_id = ? WHERE id = ?", (package_id, order_id))
    credit = apply_package(conn, order_id)
    pos_journal_append(conn, "package_set",
                       {"package_id": package_id, "covered": credit},
                       order_id=order_id, user_id=session.get("user_id"))
    conn.commit()
    conn.close()
    flash(f"Package applied — €{credit:.2f} covered." if package_id
          else "Package removed.", "success")
    return redirect(url_for("pos_order", order_id=order_id))


