    if stamp:
        conn.execute(f"UPDATE pos_order_lines SET state = ?, {stamp} = ? WHERE id = ?",
                     (state, now, line_id))
    else:
        conn.execute("UPDATE pos_order_lines SET state = ? WHERE id = ?", (state, line_id))
