@app.route("/pos/line/<int:line_id>/void", methods=["POST"])
@login_required
def pos_void_item(line_id):
    """Void a line, with a reason and a name against it.

    A void with neither is the oldest hole in any till: it is how stock walks
    out of a building and the numbers still balance. The reason is required,
    it goes in the audit log, and anything already sent to the kitchen is
    called out separately because that one has been cooked.
    """
    reason = (request.form.get("reason", "") or "").strip()
    conn = get_db()
    line = conn.execute("SELECT * FROM pos_order_lines WHERE id = ?", (line_id,)).fetchone()
    if not line:
        conn.close()
        abort(404)
    if not reason:
        conn.close()
        flash("Say why it is being voided — it goes on the record.", "error")
        return redirect(url_for("pos_order", order_id=line["order_id"]))
    was_sent = line["state"] in ("sent", "ready", "served")
    pos_void_line(conn, line_id, session.get("user_id"))
    conn.execute(
        "UPDATE pos_order_lines SET void_reason = ?, voided_by_user_id = ?, voided_at = ? "
        "WHERE id = ?", (reason, session.get("user_id"),
                         datetime.now(timezone.utc).isoformat(), line_id))
    log_audit(conn, "pos_line_voided", target=line["name"],
              details=f"€{(line['unit_price'] or 0) * line['quantity']:.2f} — {reason}"
                      + (" (already sent to the kitchen)" if was_sent else ""))
    # A void is a further entry, not an erasure: the original line_added row
    # stays in the journal and this one references it.
    pos_journal_append(conn, "line_voided", {
        "line_id": line_id, "name": line["name"],
        "amount": round((line["unit_price"] or 0) * line["quantity"], 2),
        "reason": reason, "already_sent": was_sent,
    }, order_id=line["order_id"], user_id=session.get("user_id"))
    # Voiding a covered drink releases what it was holding, so the next one
    # ordered can use the allowance instead of being charged in full.
    order_row = conn.execute("SELECT package_id FROM pos_orders WHERE id = ?",
                             (line["order_id"],)).fetchone()
    if order_row and order_row["package_id"]:
        apply_package(conn, line["order_id"])
    conn.commit()
    conn.close()
    if was_sent:
        flash("Voided — but the kitchen had already been sent it. Tell them.", "error")
    else:
        flash("Voided.", "success")
    return redirect(url_for("pos_order", order_id=line["order_id"]))


@app.route("/pos/<int:order_id>/adjust", methods=["POST"])
@login_required
def pos_adjust(order_id):
    """Service charge and discounts, both with a reason on the discount."""
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order or order["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))

    def money(field):
        try:
            return max(0.0, round(float((request.form.get(field, "0") or "0").replace(",", ".")), 2))
        except ValueError:
            return 0.0

    kind = request.form.get("kind", "")
    if kind == "discount":
        amount, reason = money("amount"), (request.form.get("reason", "") or "").strip()
        percent = (request.form.get("percent", "") or "").strip()
        if percent:
            try:
                gross = pos_bill(conn, order_id)["gross"]
                amount = round(gross * float(percent) / 100, 2)
            except ValueError:
                pass
        if amount and not reason:
            conn.close()
            flash("A discount needs a reason — it is money off the takings.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        conn.execute("UPDATE pos_orders SET discount_amount = ?, discount_reason = ? WHERE id = ?",
                     (amount, reason or None, order_id))
        if amount:
            log_audit(conn, "pos_discount", target=order["table_label"],
                      details=f"€{amount:.2f} — {reason}")
        pos_journal_append(conn, "discount_set",
                           {"amount": amount, "reason": reason or None,
                            "was": round(order["discount_amount"] or 0, 2)},
                           order_id=order_id, user_id=session.get("user_id"))
    elif kind == "service":
        percent = (request.form.get("percent", "") or "").strip()
        amount = money("amount")
        if percent:
            try:
                amount = round(pos_bill(conn, order_id)["gross"] * float(percent) / 100, 2)
            except ValueError:
                pass
        conn.execute("UPDATE pos_orders SET service_charge = ? WHERE id = ?", (amount, order_id))
        pos_journal_append(conn, "service_set",
                           {"amount": amount, "was": round(order["service_charge"] or 0, 2)},
                           order_id=order_id, user_id=session.get("user_id"))
    elif kind == "covers":
        try:
            conn.execute("UPDATE pos_orders SET covers = ? WHERE id = ?",
                         (max(1, int(request.form.get("covers", "1"))), order_id))
        except ValueError:
            pass
    conn.commit()
    conn.close()
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>/move", methods=["POST"])
@login_required
def pos_move_table(order_id):
    """Rename a table, or merge it into another.

    A party moving from the terrace to inside, or two tables becoming one, is
    ordinary. Without this it means re-ringing the whole order.
    """
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order or order["status"] != "open":
        conn.close()
        abort(404)
    target = (request.form.get("merge_into", "") or "").strip()
    if target.isdigit():
        into = conn.execute("SELECT * FROM pos_orders WHERE id = ? AND status = 'open'",
                            (target,)).fetchone()
        if not into:
            conn.close()
            flash("That table isn't open.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        conn.execute("UPDATE pos_order_lines SET order_id = ? WHERE order_id = ?",
                     (into["id"], order_id))
        conn.execute(
            # 'void' rather than a new status: the schema constrains this
            # column, and a merged tab genuinely holds nothing — every line
            # moved. merged_into_order_id says where they went.
            """UPDATE pos_orders SET status = 'void', merged_into_order_id = ?, closed_at = ?
               WHERE id = ?""", (into["id"], datetime.now(timezone.utc).isoformat(), order_id))
        conn.execute("UPDATE pos_orders SET covers = covers + ?, deposit_credit = deposit_credit + ? "
                     "WHERE id = ?", (order["covers"] or 0, order["deposit_credit"] or 0, into["id"]))
        pos_journal_append(conn, "tab_merged",
                           {"from_table": order["table_label"], "into_table": into["table_label"],
                            "into_order_id": into["id"], "covers_moved": order["covers"] or 0},
                           order_id=order_id, user_id=session.get("user_id"))
        conn.commit()
        conn.close()
        flash(f"Merged into {into['table_label']}.", "success")
        return redirect(url_for("pos_order", order_id=into["id"]))

    label = (request.form.get("table_label", "") or "").strip()
    if label:
        conn.execute("UPDATE pos_orders SET table_label = ? WHERE id = ?", (label, order_id))
        conn.commit()
    conn.close()
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>/pay", methods=["POST"])
@login_required
def pos_take_payment_route(order_id):
    """Take a payment — all of it, or part of it.

    Part of it is the point: a tab can take several, which is what splitting a
    bill is. The tab closes only when nothing is left outstanding.
    """
    method = request.form.get("method", "")
    if method not in POS_PAYMENT_METHODS:
        abort(400)
    conn = get_db()
    bill = pos_bill(conn, order_id)
    if not bill or bill["order"]["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))

    raw = (request.form.get("amount", "") or "").strip().replace(",", ".")
    try:
        amount = round(float(raw), 2) if raw else bill["outstanding"]
    except ValueError:
        amount = bill["outstanding"]
    seats = [x for x in request.form.getlist("seat") if x]
    if seats:
        # Paying for particular seats: total exactly those lines.
        amount = round(sum((l["unit_price"] or 0) * (l["quantity"] or 0) for l in bill["live"]
                           if str(l["seat_number"]) in seats), 2)
    if method == "comp":
        amount = bill["outstanding"]
    if amount <= 0 and method != "comp":
        conn.close()
        flash("Nothing left to pay on this tab.", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    if amount > bill["outstanding"] + 0.01:
        conn.close()
        flash(f"That's more than the €{bill['outstanding']:.2f} outstanding.", "error")
        return redirect(url_for("pos_order", order_id=order_id))

    # Cash: what was handed over, and what goes back. The till recorded that
    # cash had been taken and left the arithmetic to whoever was holding the
    # notes, at the end of a service, in their head. Optional -- a tab paid to
    # the penny needs nothing typed -- but when a fifty is put down for a
    # EUR 42.50 bill, the change is on the screen rather than in the arithmetic.
    change_due = None
    raw_cash = (request.form.get("cash_received", "") or "").strip().replace(",", ".")
    if method == "cash" and raw_cash:
        try:
            received = round(float(raw_cash), 2)
        except ValueError:
            conn.close()
            flash("Enter what they handed over as a number, or leave it blank.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        if received + 0.01 < amount:
            conn.close()
            flash(f"That is €{amount - received:.2f} short of the €{amount:.2f} due.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        change_due = round(received - amount, 2)

    room_booking_id = None
    if method == "room":
        rb = (request.form.get("room_booking_id", "") or "").strip()
        if not rb.isdigit():
            conn.close()
            flash("Choose which guest's room it goes on.", "error")
            return redirect(url_for("pos_order", order_id=order_id))
        room_booking_id = int(rb)
        # Onto their bill by name, so the guest can see what they had rather
        # than one lump called "restaurant".
        for l in bill["live"]:
            add_booking_extra(conn, "room", room_booking_id, l["name"], l["quantity"],
                              unit_price=l["unit_price"], user_id=session.get("user_id"),
                              notes=f"Table {bill['order']['table_label']}")

    reference = (request.form.get("reference", "") or "").strip() or None
    if change_due is not None:
        # On the payment itself, so the journal and the cash-up can both show
        # what was tendered rather than only what the bill came to.
        tendered = round(amount + change_due, 2)
        reference = " · ".join(x for x in (
            reference, f"tendered €{tendered:.2f}, change €{change_due:.2f}") if x)
    pos_take_payment(conn, order_id, amount, method,
                     reference=reference,
                     seats=seats, room_booking_id=room_booking_id,
                     user_id=session.get("user_id"))
    after = pos_close_if_settled(conn, order_id, method, user_id=session.get("user_id"))
    conn.commit()
    conn.close()
    # The change goes first and on its own. It is the one number somebody is
    # waiting on with their hand out.
    if change_due:
        flash(f"Change €{change_due:.2f}", "success")
    if after["outstanding"] > 0.01:
        flash(f"€{amount:.2f} taken. €{after['outstanding']:.2f} still to pay.", "success")
        return redirect(url_for("pos_order", order_id=order_id))
    flash(f"Settled — €{after['total']:.2f}.", "success")
    return redirect(url_for("pos_home"))


@app.route("/pos/<int:order_id>/reopen", methods=["POST"])
@owner_required
def pos_reopen(order_id):
    """Reopen a settled tab. Mistakes happen mid-service and the alternative
    is a second tab that makes the covers count wrong forever."""
    conn = get_db()
    # Refused once the day is closed. A closed period whose contents can still
    # change is not a closed period, and the whole point of the closure is that
    # yesterday's cash-up gives the same answer today.
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    # The tab's own service_date, not the first ten characters of closed_at.
    # Closures are keyed by service day; closed_at is a UTC timestamp, so past
    # midnight its date prefix is the NEXT day and this lookup found no closure
    # at all — the guard quietly did nothing and a closed day could be reopened
    # into, which is the one thing a closure exists to prevent. The fallback is
    # for rows written before service_date was stamped correctly.
    day = ""
    if order:
        day = order["service_date"] or service_day_iso(order["closed_at"]) or ""
    if day and conn.execute("SELECT 1 FROM pos_closures WHERE kind='day' AND period = ?",
                            (day,)).fetchone():
        conn.close()
        flash(f"{day} has been closed off — a tab inside a closed day cannot be reopened. "
              "Take the correction on today instead.", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    conn.execute(
        """UPDATE pos_orders SET status = 'open', closed_at = NULL, reopened_at = ?
           WHERE id = ? AND status = 'paid'""",
        (datetime.now(timezone.utc).isoformat(), order_id))
    log_audit(conn, "pos_tab_reopened", target=str(order_id))
    pos_journal_append(conn, "tab_reopened",
                       {"table": order["table_label"] if order else None,
                        "was_settled_at": order["closed_at"] if order else None},
                       order_id=order_id, user_id=session.get("user_id"))
    conn.commit()
    conn.close()
    flash("Reopened.", "success")
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>/receipt")
@login_required
def pos_receipt(order_id):
    """The bill as a guest receives it, and as the taxman expects it.

    A French note has to carry the company's name, address, SIRET and TVA
    number alongside VAT by rate — the docstring used to claim it showed
    those while the template hardcoded an address and printed neither. They
    now come from Company info, so correcting them in one place corrects
    every bill.

    It prints from the browser: the iPad has no till roll, and a page that
    prints beats one that cannot.
    """
    conn = get_db()
    bill = pos_bill(conn, order_id)
    if not bill:
        conn.close()
        abort(404)
    context = pos_table_context(conn, bill["order"])
    payments = conn.execute(
        "SELECT * FROM pos_payments WHERE order_id = ? ORDER BY id", (order_id,)).fetchall()
    # A cover on the set menu shows as one line with its dishes beneath, muted
    # — that is what a ventilated French addition actually looks like, and it
    # satisfies arrêté 83-50/A art. 1 (the itemised note) without printing one
    # blended line the ventilation requirement would not survive.
    formules = pos_formules_for(conn, order_id)
    formule_line_ids = {l["id"] for f in formules for l in f["lines"]}
    a_la_carte = pos_lines_by_course(
        [l for l in bill["live"] if l["id"] not in formule_line_ids])
    company = conn.execute(
        """SELECT legal_name, registration_number, vat_number, registered_address
           FROM company_info WHERE id = 1""").fetchone()
    conn.close()
    return render_template("pos_receipt.html", bill=bill, order=bill["order"],
                           by_course=a_la_carte, formules=formules, context=context,
                           payments=payments, courses=MENU_COURSES, company=company,
                           payment_methods=POS_PAYMENT_METHODS)


@app.route("/pos/kitchen")
@login_required
def pos_kitchen():
    """The pass. Every ticket the kitchen has been sent, oldest first, with the
    clock running on it — because a ticket with no clock is how a table waits
    forty minutes and nobody notices."""
    conn = get_db()
    tickets = pos_open_tickets(conn)
    for t in tickets:
        ctx = conn.execute(
            "SELECT guest_name, dietary_notes FROM restaurant_bookings WHERE id = ?",
            (t["booking_id"],)).fetchone() if t["booking_id"] else None
        t["guest"] = ctx["guest_name"] if ctx else None
        t["dietary"] = (ctx["dietary_notes"] or "").strip() if ctx else ""
    # The pass is where 86ing actually gets decided, so the shortfall belongs
    # here and not only on the card page the chef looked at this afternoon.
    today = service_day()
    card = menu_for_date(conn, today)
    capacity = card_capacity(conn, card["id"], today) if card else None
    short = capacity["short"] if capacity else []
    clashes = dietary_clashes(conn, card["id"], today) if card else []
    conn.close()
    return render_template("pos_kitchen.html", tickets=tickets, courses=MENU_COURSES,
                           capacity=capacity, short=short, clashes=clashes)


@app.route("/pos/day")
@owner_required
def pos_day():
    """Cash up.

    Once a day is closed this reads the frozen closure, not the live rows.
    That is the whole difference: before, voiding a line tonight silently
    changed what yesterday had taken, and a cash-up that answers differently
    on Tuesday than it did on Monday is not a cash-up.
    """
    on = parse_date(request.args.get("date", "")) or service_day()
    conn = get_db()
    closure = pos_closure_for(conn, "day", on.isoformat())
    report = pos_day_report(conn, on)
    if closure:
        # The frozen figures win. The live list of tabs is still shown beneath,
        # and any disagreement between the two is reported rather than hidden.
        report = dict(report, taken=closure["taken_total"], gross=closure["gross_total"],
                      discounts=closure["discount_total"], service=closure["service_total"],
                      covers=closure["covers"], tabs=closure["ticket_count"],
                      by_method=closure["by_method"],
                      vat=round(sum(v["vat"] for v in closure["vat"].values()), 2),
                      average_per_cover=round(closure["gross_total"] / closure["covers"], 2)
                      if closure["covers"] else 0)
    chain = pos_journal_verify(conn)
    # The window, not date(occurred_at) — the figures above run to five in the
    # morning, so a list that stopped at UTC midnight left the last hour of
    # service off the page it is meant to explain.
    win_from, win_to = service_day_window(on)
    events = conn.execute(
        """SELECT * FROM pos_journal WHERE occurred_at >= ? AND occurred_at < ?
           ORDER BY sequence DESC LIMIT 60""", (win_from, win_to)).fetchall()
    conn.close()
    overview = [
        overview_cell("Taken", euro(report["taken"])),
        overview_cell("Covers", report["covers"]),
        overview_cell("Average per cover", euro(report["average_per_cover"])),
        overview_cell("VAT within that", euro(report["vat"])),
        overview_cell("Discounts given", euro(report["discounts"]),
                      alert=report["discounts"] > 0),
    ]
    return render_template("pos_day.html", report=report, overview=overview, on=on,
                           closure=closure, chain=chain, events=events,
                           payment_methods=POS_PAYMENT_METHODS,
                           is_today=on == datetime.now(timezone.utc).date(),
                           prev_day=on - timedelta(days=1), next_day=on + timedelta(days=1))


@app.route("/pos/day/close", methods=["POST"])
@owner_required
def pos_close_day():
    """Close the day off. After this the figure cannot move."""
    on = parse_date(request.form.get("date", "")) or service_day()
    if on >= service_day() and request.form.get("confirm") != "yes":
        flash("That day isn't over. Tick the box if you really mean to close it now.", "error")
        return redirect(url_for("pos_day", date=on.isoformat()))
    conn = get_db()
    open_tabs = conn.execute(
        "SELECT COUNT(*) AS c FROM pos_orders WHERE status = 'open' AND date(opened_at) <= ?",
        (on.isoformat(),)).fetchone()["c"]
    if open_tabs:
        conn.close()
        flash(f"{open_tabs} tab{'' if open_tabs == 1 else 's'} still open. "
              "Settle or void them before closing the day.", "error")
        return redirect(url_for("pos_day", date=on.isoformat()))
    def _money(field):
        raw = (request.form.get(field, "") or "").strip().replace(",", ".")
        if not raw:
            return None
        try:
            return round(float(raw), 2)
        except ValueError:
            return "bad"

    opening_float, counted = _money("opening_float"), _money("counted_cash")
    if "bad" in (opening_float, counted):
        conn.close()
        flash("Enter the float and the count as numbers, or leave them blank.", "error")
        return redirect(url_for("pos_day", date=on.isoformat()))

    closure, created = pos_close_period(conn, "day", on.isoformat(), session.get("user_id"),
                                        opening_float=opening_float, counted_cash=counted)
    log_audit(conn, "pos_day_closed", target=on.isoformat(),
              details=f"€{closure['taken_total']:.2f} taken"
                      + ("" if closure["cash_variance"] is None
                         else f", drawer {closure['cash_variance']:+.2f}"))
    conn.commit()
    conn.close()
    if not created:
        flash(f"{on.isoformat()} was already closed.", "error")
        return redirect(url_for("pos_day", date=on.isoformat()))
    flash(f"{on.isoformat()} closed — €{closure['taken_total']:.2f} taken.", "success")
    # The difference gets its own message, and says which way it went. "Short"
    # and "over" are the words used at the end of a service; a signed number on
    # its own gets read as either.
    v = closure["cash_variance"]
    if v is not None:
        if abs(v) < 0.01:
            flash("The drawer counts exactly.", "success")
        else:
            flash(f"The drawer is €{abs(v):.2f} {'over' if v > 0 else 'short'}.", "error")
    return redirect(url_for("pos_day", date=on.isoformat()))


# Six years, from the close of the accounting year (LPF art. L. 102 B).
POS_RETENTION_YEARS = 6


def pos_archive_bundle(conn, year):
    """A year of the till as CSV, with a notice explaining it.

    Open format on purpose. The archive has to be readable by an inspector in
    2032, on a machine that has never heard of this app — so it is CSV and a
    plain-text notice in French, not a database file that needs the software
    that wrote it.
    """
    start, end = f"{year}-01-01", f"{year}-12-31"
    journal = conn.execute(
        """SELECT sequence, register_id, event_type, order_id, occurred_at, user_id,
                  payload, prev_hash, hash FROM pos_journal
           WHERE date(occurred_at) BETWEEN ? AND ? ORDER BY sequence""",
        (start, end)).fetchall()
    closures = conn.execute(
        """SELECT kind, period, first_sequence, last_sequence, gross_total, discount_total,
                  service_total, taken_total, vat_json, by_method_json, ticket_count,
                  covers, perpetual_total, prev_hash, hash, closed_at FROM pos_closures
           WHERE period LIKE ? ORDER BY closed_at""", (f"{year}%",)).fetchall()
    tickets = conn.execute(
        """SELECT receipt_number, table_label, covers, service_date, settled_total,
                  payment_method, opened_at, closed_at FROM pos_orders
           WHERE receipt_number LIKE ? ORDER BY receipt_number""", (f"{year}-%",)).fetchall()
    lines = conn.execute(
        """SELECT pos_orders.receipt_number, pos_order_lines.name, pos_order_lines.quantity,
                  pos_order_lines.unit_price, pos_order_lines.vat_rate, pos_order_lines.course,
                  pos_order_lines.seat_number, pos_order_lines.voided,
                  pos_order_lines.void_reason, pos_order_lines.package_covered
           FROM pos_order_lines JOIN pos_orders ON pos_orders.id = pos_order_lines.order_id
           WHERE pos_orders.receipt_number LIKE ?
           ORDER BY pos_orders.receipt_number, pos_order_lines.id""", (f"{year}-%",)).fetchall()

    def sheet(rows, fields):
        buf = io.StringIO()
        w = csv.DictWriter(buf, fieldnames=fields, extrasaction="ignore")
        w.writeheader()
        for r in rows:
            w.writerow({k: csv_safe_cell(r[k]) for k in fields})
        return buf.getvalue()

    broken = pos_journal_verify(conn)
    notice = f"""ARCHIVE DE CAISSE — Chateau de Gudanes
Annee : {year}
Genere le : {datetime.now(timezone.utc).isoformat()}
Caisse : {POS_REGISTER_ID}

CONTENU
  journal.csv    Le journal des evenements, dans l'ordre, non modifiable.
                 Chaque ligne porte l'empreinte (hash) de la ligne precedente.
  clotures.csv   Les clotures journalieres, mensuelles et annuelles, figees.
  tickets.csv    Les notes emises, numerotees sans rupture de sequence.
  lignes.csv     Le detail de chaque note : article, quantite, prix, taux de TVA.

CONTROLE D'INTEGRITE
  Le journal est chaine : hash = sha256(hash precedent | sequence | type | contenu).
  Pour verifier, recalculer la chaine depuis la premiere ligne. Toute ligne
  modifiee ou supprimee interrompt le calcul a partir de ce point.
  Etat au moment de l'export : {"CHAINE VERIFIEE" if not broken else
    f"ANOMALIE a la sequence {broken['sequence']} — {broken['problem']}"}

CONSERVATION
  A conserver six ans (LPF art. L. 102 B). Obligation d'inalterabilite,
  securisation, conservation et archivage : CGI art. 286, I-3 bis.
  Les prix sont exprimes TTC. La TVA est ventilee par taux dans clotures.csv.
"""

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("notice.txt", notice)
        zf.writestr("journal.csv", sheet(journal, [
            "sequence", "register_id", "event_type", "order_id", "occurred_at",
            "user_id", "payload", "prev_hash", "hash"]))
        zf.writestr("clotures.csv", sheet(closures, [
            "kind", "period", "first_sequence", "last_sequence", "gross_total",
            "discount_total", "service_total", "taken_total", "vat_json",
            "by_method_json", "ticket_count", "covers", "perpetual_total",
            "prev_hash", "hash", "closed_at"]))
        zf.writestr("tickets.csv", sheet(tickets, [
            "receipt_number", "table_label", "covers", "service_date", "settled_total",
            "payment_method", "opened_at", "closed_at"]))
        zf.writestr("lignes.csv", sheet(lines, [
            "receipt_number", "name", "quantity", "unit_price", "vat_rate", "course",
            "seat_number", "voided", "void_reason", "package_covered"]))
    return buf.getvalue(), {
        "journal": len(journal), "closures": len(closures),
        "tickets": len(tickets), "lines": len(lines), "chain_ok": not broken,
    }


@app.route("/admin/pos/archive")
@owner_required
def pos_archive():
    """Download a year of the till, or see what there is to download."""
    conn = get_db()
    years = [r["y"] for r in conn.execute(
        """SELECT DISTINCT strftime('%Y', occurred_at) AS y FROM pos_journal
           WHERE occurred_at IS NOT NULL ORDER BY y DESC""").fetchall() if r["y"]]
    wanted = (request.args.get("year", "") or "").strip()
    if not wanted:
        exports = conn.execute(
            """SELECT * FROM pos_journal WHERE event_type = 'archive_exported'
               ORDER BY sequence DESC LIMIT 20""").fetchall()
        conn.close()
        return render_template("admin_pos_archive.html", years=years, exports=exports,
                               retention_years=POS_RETENTION_YEARS)
    if not wanted.isdigit():
        conn.close()
        abort(400)

    data, counts = pos_archive_bundle(conn, wanted)
    # The export is itself an event: an archive taken and not recorded is one
    # nobody can prove was taken.
    pos_journal_append(conn, "archive_exported",
                       {"year": wanted, **counts}, user_id=session.get("user_id"))
    log_audit(conn, "pos_archive_exported", target=wanted,
              details=f"{counts['journal']} journal entries, {counts['tickets']} tickets")
    conn.commit()
    conn.close()
    return app.response_class(
        data, mimetype="application/zip",
        headers={"Content-Disposition":
                 f'attachment; filename="caisse-{wanted}-gudanes.zip"'})


@app.route("/admin/pos/journal")
@owner_required
def pos_journal_page():
    """The journal itself, and whether it still verifies.

    Worth having on screen rather than only in an export: the answer to "has
    anything been altered since it was written" should be one click, not a
    request to whoever built the system.
    """
    conn = get_db()
    lv = list_view(
        conn.execute("SELECT pos_journal.*, users.name AS who FROM pos_journal "
                     "LEFT JOIN users ON users.id = pos_journal.user_id "
                     "ORDER BY sequence DESC LIMIT 1000").fetchall(),
        request.args,
        search=["event_type", "payload", "who"],
        search_hint="Search event, table, amount or who",
        facets=[
            facet("event", "Event", lambda e: e["event_type"].replace("_", " "), limit=10),
            facet("who", "Who", lambda e: e["who"] or "System", limit=8),
        ],
        sorts=[
            sort_option("recent", "Newest first", lambda e: e["sequence"], reverse=True),
            sort_option("oldest", "Oldest first", lambda e: e["sequence"]),
        ],
        default_sort="recent",
    )
    chain = pos_journal_verify(conn)
    closures = conn.execute(
        "SELECT * FROM pos_closures ORDER BY closed_at DESC LIMIT 30").fetchall()
    perpetual = pos_perpetual_total(conn)
    total_events = conn.execute("SELECT COUNT(*) AS c FROM pos_journal").fetchone()["c"]
    conn.close()
    overview = [
        overview_cell("Entries", total_events),
        overview_cell("Chain", "Broken" if chain else "Verified", alert=bool(chain),
                      sub=chain["problem"] if chain else "recomputed just now"),
        overview_cell("Taken since the start", euro(perpetual), hint="never resets"),
        overview_cell("Periods closed", len(closures)),
    ]
    return render_template("admin_pos_journal.html", lv=lv, events=lv["rows"], chain=chain,
                           closures=closures, overview=overview, perpetual=perpetual)


@app.route("/pos/<int:order_id>/take-card", methods=["POST"])
@login_required
def pos_take_card(order_id):
    """Put the tab's total on the card reader and wait for a tap.

    The reader is driven from here — Stripe pushes the amount to it over the
    internet — so there is no app to switch to and nothing to type twice. The
    resulting payment settles the tab against its own reference.
    """
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order or order["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))
    reader = terminal_reader_id(conn)
    if not stripe_enabled() or not reader:
        conn.close()
        flash("No card reader is set up — take cash, charge it to a room, or "
              "show the QR code instead.", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    # What is left, not the whole bill. This till can split a payment, so a
    # table that has already put half on cash must not be asked to tap for all
    # of it.
    total = pos_bill(conn, order_id)["outstanding"]
    if total <= 0:
        conn.close()
        flash("Nothing to charge yet.", "error")
        return redirect(url_for("pos_order", order_id=order_id))

    # Resume rather than restart. A second press must not ask the guest to tap
    # for a second charge.
    if order["payment_intent_id"]:
        state, _msg, _intent = terminal_payment_state(order["payment_intent_id"])
        if state in ("waiting", "succeeded"):
            conn.close()
            return redirect(url_for("pos_order", order_id=order_id))

    intent_id, error = terminal_collect_payment(
        conn, order_id, total, f"Table {order['table_label']}", reader)
    if intent_id:
        conn.execute("UPDATE pos_orders SET payment_intent_id = ? WHERE id = ?",
                     (intent_id, order_id))
        conn.commit()
    conn.close()
    if error:
        flash(error, "error")
    return redirect(url_for("pos_order", order_id=order_id))


@app.route("/pos/<int:order_id>/card-status")
@login_required
def pos_card_status(order_id):
    """Polled by the till while the guest is tapping.

    Settles the tab itself the moment Stripe says the money arrived, so the
    payment cannot succeed without the tab closing — the two must not be able
    to disagree.
    """
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order:
        conn.close()
        return jsonify(state="unknown", message="No such tab."), 404
    if order["status"] != "open":
        conn.close()
        return jsonify(state="succeeded", message="Settled.", settled=True)
    if not order["payment_intent_id"]:
        conn.close()
        return jsonify(state="idle", message="")

    state, message, intent = terminal_payment_state(order["payment_intent_id"])
    settled = False
    if state == "succeeded":
        # Trust Stripe for the amount, exactly as the webhook does — the guest
        # tapped what the reader asked for, and recomputing it here would let a
        # line added mid-tap change what we record as taken.
        taken = round((sval(intent, "amount_received") or 0) / 100.0, 2) if intent else 0.0
        if taken <= 0:
            taken = pos_bill(conn, order_id)["outstanding"]
        who = current_user()
        user = who["id"] if who else None
        pos_take_payment(conn, order_id, taken, "card_terminal",
                         reference=order["payment_intent_id"], user_id=user)
        after = pos_close_if_settled(conn, order_id, "card_terminal", user_id=user)
        conn.commit()
        settled = after["outstanding"] <= 0.01
        message = (f"€{taken:.2f} taken on the reader."
                   if not settled else f"Settled — €{after['total']:.2f}.")
    elif state == "failed":
        # Clear the reference so the next attempt starts a fresh payment rather
        # than polling a dead one forever.
        conn.execute("UPDATE pos_orders SET payment_intent_id = NULL WHERE id = ?",
                     (order_id,))
        conn.commit()
    conn.close()
    return jsonify(state=state, message=message, settled=settled)


@app.route("/pos/<int:order_id>/cancel-card", methods=["POST"])
@login_required
def pos_cancel_card(order_id):
    conn = get_db()
    order = conn.execute("SELECT * FROM pos_orders WHERE id = ?", (order_id,)).fetchone()
    if not order:
        conn.close()
        abort(404)
    problems = terminal_cancel(terminal_reader_id(conn), order["payment_intent_id"])
    conn.execute("UPDATE pos_orders SET payment_intent_id = NULL WHERE id = ?", (order_id,))
    conn.commit()
    conn.close()
    flash(problems or "Card payment cancelled — the reader is clear.",
          "error" if problems else "success")
    return redirect(url_for("pos_order", order_id=order_id))


PIN_ATTEMPT_LIMIT = 5
PIN_LOCKOUT_MINUTES = 10


def pin_locked_out(conn, user_id):
    """Whether this person has failed too many PINs to try again yet.

    Counted per person, not per device. Everyone shares the château's IP on a
    kiosk, so an IP-based limit would let one fumbled PIN lock the whole kitchen
    out of clocking in.
    """
    since = (datetime.now(timezone.utc) - timedelta(minutes=PIN_LOCKOUT_MINUTES)).isoformat()
    failures = conn.execute(
        """SELECT COUNT(*) AS c FROM submission_log
           WHERE action = ? AND created_at >= ?""",
        (f"arrive_pin_fail:{user_id}", since)).fetchone()["c"]
    return failures >= PIN_ATTEMPT_LIMIT


def record_pin_failure(conn, user_id):
    """Only failures are logged. Counting successes too would lock out whoever
    signs in most often, which is the opposite of the intent."""
    conn.execute(
        "INSERT INTO submission_log (ip_address, action, created_at) VALUES (?, ?, ?)",
        (request.remote_addr or "kiosk", f"arrive_pin_fail:{user_id}",
         datetime.now(timezone.utc).isoformat()))


def initials_for(name):
    parts = [p for p in (name or "").split() if p]
    return ((parts[0][0] + parts[-1][0]) if len(parts) > 1
            else (parts[0][:2] if parts else "?")).upper()


@app.route("/arrive")
def arrive():
    """The screen on the shared iPad or a borrowed phone: tap your name, enter
    your PIN, and you are signed in and clocked on.

    Separate from /login on purpose. Signing in is not the same event as
    arriving at work — someone checking next week's rota from home at nine at
    night should not appear on the timesheet.
    """
    conn = get_db()
    staff = conn.execute(
        """SELECT id, name, job_role, quick_pin_hash FROM users
           WHERE status = 'active' ORDER BY name""").fetchall()
    on_shift = {r["user_id"] for r in conn.execute(
        "SELECT user_id FROM time_entries WHERE clock_out_at IS NULL").fetchall()}
    conn.close()
    people = [{
        "id": p["id"], "name": p["name"], "job_role": p["job_role"],
        "initials": initials_for(p["name"]),
        "has_pin": bool(p["quick_pin_hash"]),
        "here": p["id"] in on_shift,
    } for p in staff]
    return render_template("arrive.html", people=people)


@app.route("/arrive/<int:user_id>", methods=["POST"])
def arrive_signin(user_id):
    """Check the PIN, sign them in, and start their shift."""
    pin = request.form.get("pin", "").strip()
    conn = get_db()
    person = conn.execute(
        "SELECT * FROM users WHERE id = ? AND status = 'active'", (user_id,)).fetchone()
    if not person:
        conn.close()
        abort(404)

    if pin_locked_out(conn, user_id):
        conn.commit()
        conn.close()
        flash(f"Too many wrong PINs. Wait {PIN_LOCKOUT_MINUTES} minutes, or ask "
              f"the owner to reset it.", "error")
        return redirect(url_for("arrive"))
    if not person["quick_pin_hash"]:
        conn.close()
        flash(f"{person['name'].split(' ')[0]} has no PIN yet — the owner sets "
              f"one on their profile.", "error")
        return redirect(url_for("arrive"))
    if not check_password_hash(person["quick_pin_hash"], pin):
        record_pin_failure(conn, user_id)
        log_audit(conn, "arrive_pin_failed", target=person["name"])
        conn.commit()
        conn.close()
        flash("That PIN doesn't match.", "error")
        return redirect(url_for("arrive"))

    session["user_id"] = person["id"]
    # Arriving means starting work. Only start a shift if one is not already
    # running, so tapping in twice does not open a second overlapping entry.
    started = False
    if not open_shift(conn, person["id"]):
        clock_in(conn, person["id"])
        started = True
    log_audit(conn, "arrived_on_shift" if started else "arrived_already_on",
              target=person["name"])
    conn.commit()
    conn.close()
    first = (person["name"] or "").split(" ")[0]
    flash(f"Welcome, {first} — you're clocked in." if started
          else f"Welcome back, {first}. You were already clocked in.", "success")
    return redirect(url_for("staff_today"))


@app.route("/directory/<int:user_id>/set-pin", methods=["POST"])
@owner_required
def set_quick_pin(user_id):
    """Set or clear a staff member's arrival PIN."""
    pin = request.form.get("pin", "").strip()
    conn = get_db()
    person = conn.execute("SELECT name FROM users WHERE id = ?", (user_id,)).fetchone()
    if not person:
        conn.close()
        abort(404)
    if pin and (not pin.isdigit() or not 4 <= len(pin) <= 8):
        conn.close()
        flash("A PIN is 4 to 8 digits.", "error")
        return redirect(url_for("profile", user_id=user_id))

    conn.execute("UPDATE users SET quick_pin_hash = ? WHERE id = ?",
                 (generate_password_hash(pin) if pin else None, user_id))
    # Clear any lockout, so resetting a forgotten PIN lets them straight back in.
    conn.execute("DELETE FROM submission_log WHERE action = ?",
                 (f"arrive_pin_fail:{user_id}",))
    log_audit(conn, "quick_pin_set" if pin else "quick_pin_cleared", target=person["name"])
    conn.commit()
    conn.close()
    flash(f"PIN {'set' if pin else 'removed'} for {person['name']}.", "success")
    return redirect(url_for("profile", user_id=user_id))


@app.route("/admin/terminal", methods=["GET", "POST"])
@owner_required
def admin_terminal():
    """Choose which card reader the till talks to."""
    conn = get_db()
    if request.method == "POST":
        chosen = request.form.get("reader_id", "").strip()
        conn.execute(
            """INSERT INTO app_settings (key, value) VALUES ('terminal_reader_id', ?)
               ON CONFLICT(key) DO UPDATE SET value = excluded.value""", (chosen,))
        log_audit(conn, "terminal_reader_selected", target=chosen or "(none)")
        conn.commit()
        conn.close()
        flash(f"Card reader set to {chosen}." if chosen
              else "Card reader cleared — the till will offer cash and QR only.", "success")
        return redirect(url_for("admin_terminal"))

    chosen = terminal_reader_id(conn)
    conn.close()
    readers, error = list_terminal_readers()
    return render_template("admin_terminal.html", readers=readers, error=error,
                           chosen=chosen, stripe_on=stripe_enabled())


@app.route("/pos/<int:order_id>/pay-link", methods=["POST"])
@login_required
def pos_pay_link(order_id):
    """A Stripe Checkout link the guest pays on their own phone, shown as a QR.

    This is the card route that needs no hardware at all. A physical reader
    (Stripe Terminal) would be a different integration; this works today with
    nothing but the iPad.
    """
    conn = get_db()
    bill = pos_bill(conn, order_id)
    if not bill or bill["order"]["status"] != "open":
        conn.close()
        flash("That tab is closed.", "error")
        return redirect(url_for("pos_home"))
    if bill["outstanding"] <= 0:
        conn.close()
        flash("Nothing left to charge on this tab.", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    if not stripe_enabled():
        conn.close()
        flash("Card payment isn't connected — take cash, or charge it to a room.", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    try:
        session_obj = stripe.checkout.Session.create(
            mode="payment",
            line_items=[{
                "price_data": {
                    "currency": "eur",
                    "product_data": {"name": f"Table {bill['order']['table_label']}"},
                    # One line for whatever is outstanding: after a part
                    # payment the individual lines no longer add up to it.
                    "unit_amount": int(round(bill["outstanding"] * 100)),
                },
                "quantity": 1,
            }],
            success_url=url_for("pos_order", order_id=order_id, paid=1, _external=True),
            cancel_url=url_for("pos_order", order_id=order_id, _external=True),
            metadata={"kind": "pos", "pos_order_id": str(order_id)},
        )
    except Exception as e:
        conn.close()
        flash(f"Couldn't create the payment link: {e}", "error")
        return redirect(url_for("pos_order", order_id=order_id))
    conn.execute("UPDATE pos_orders SET stripe_session_id = ? WHERE id = ?",
                 (session_obj.id, order_id))
    conn.commit()
    conn.close()
    # Named session_obj, not session: Flask's own `session` is in scope here
    # and shadowing it is how a login quietly breaks.
    return redirect(session_obj.url, code=303)


# ---------------------------------------------------------------------------
# Command palette.
#
# The app has grown past 190 routes behind six nav dropdowns, and the pages
# people reach for least often are exactly the ones buried deepest. This turns
