@app.route("/book/stripe-success")
def stripe_success():
    session_id = request.args.get("session_id", "").strip()
    if not stripe_enabled() or not session_id:
        abort(404)

    conn = get_db()
    existing = conn.execute(
        "SELECT manage_token FROM bookings WHERE stripe_session_id = ?", (session_id,)
    ).fetchone()
    if existing:
        conn.close()
        return redirect(url_for("manage_booking", manage_token=existing["manage_token"]))

    try:
        session = stripe.checkout.Session.retrieve(session_id)
    except Exception:
        conn.close()
        abort(404)

    if sval(session, "payment_status") != "paid":
        conn.close()
        flash("That payment wasn't completed, so no booking was made.", "error")
        return redirect(url_for("book_rooms"))

    try:
        manage_token = create_booking_from_stripe_session(conn, session)
    except sqlite3.IntegrityError:
        # The webhook won the race and created it a moment ago. Show the guest
        # their booking rather than an error — they have paid either way.
        row = conn.execute(
            "SELECT manage_token FROM bookings WHERE stripe_session_id = ?", (session_id,)
        ).fetchone()
        manage_token = row["manage_token"] if row else None
    conn.close()
    if not manage_token:
        flash("Payment went through, but we couldn't create the booking automatically — contact the château directly with your payment reference.", "error")
        return redirect(url_for("book_rooms"))
    return redirect(url_for("booking_confirmation", manage_token=manage_token))


@app.route("/book/stripe-cancel")
def stripe_cancel():
    """Where Stripe returns a guest who abandons checkout. This existed but
    nothing pointed at it — cancel_url went straight back to the booking
    form, so the guest got no word that nothing had been booked and could
    reasonably assume it had. Returns them to the room they were booking."""
    flash("Payment was cancelled — no booking was made.", "error")
    room_id = request.args.get("room_id", type=int)
    if room_id:
        return redirect(url_for("book_room", room_id=room_id))
    return redirect(url_for("book_rooms"))


def settle_pos_from_stripe_session(conn, stripe_session, meta):
    """Record a card payment a guest made on their own phone.

    Trusts the amount Stripe actually captured rather than recomputing the
    bill: between the QR being shown and the guest paying, a waiter may have
    added a coffee. What was charged is what happened.

    Idempotent on the session id, because Stripe retries webhooks and the
    guest's success redirect can arrive first — a tab must not be credited
    twice for one payment.
    """
    order_id = (meta.get("pos_order_id") or "").strip()
    if not order_id.isdigit():
        return False
    order_id = int(order_id)
    if conn.execute("SELECT 1 FROM pos_payments WHERE stripe_session_id = ?",
                    (stripe_session["id"],)).fetchone():
        return False
    amount = (sval(stripe_session, "amount_total") or 0) / 100.0
    if amount <= 0:
        return False
    pos_take_payment(conn, order_id, amount, "card_link",
                     reference=stripe_session["id"],
                     stripe_session_id=stripe_session["id"])
    bill = pos_bill(conn, order_id)
    if bill and bill["outstanding"] <= 0.01 and bill["order"]["status"] == "open":
        conn.execute(
            """UPDATE pos_orders SET status = 'paid', settled_total = ?,
               payment_method = 'card_link', closed_at = ? WHERE id = ?""",
            (bill["total"], datetime.now(timezone.utc).isoformat(), order_id))
        log_audit(conn, "pos_tab_settled", target=bill["order"]["table_label"],
                  details=f"€{bill['total']:.2f} by card link")
        pos_journal_append(conn, "tab_settled", {
            "table": bill["order"]["table_label"], "total": bill["total"],
            "gross": bill["gross"], "discount": bill["discount"],
            "service": bill["service"], "deposit": bill["deposit"],
            "vat": {str(k): v for k, v in bill["vat_by_rate"].items()},
            "covers": bill["covers"], "method": "card_link",
            "receipt_number": pos_allocate_receipt_number(conn, order_id),
        }, order_id=order_id)
    return True


@app.route("/webhooks/stripe", methods=["POST"])
@csrf.exempt
def stripe_webhook():
    if not STRIPE_WEBHOOK_SECRET:
        abort(404)
    try:
        event = stripe.Webhook.construct_event(
            request.data, request.headers.get("Stripe-Signature", ""), STRIPE_WEBHOOK_SECRET
        )
    except Exception:
        abort(400)

    # Both events, because they mean the same thing at different times. A card
    # pays during checkout and completes the session already paid; a method
    # that settles later completes it "unpaid" and arrives days afterwards as
    # async_payment_succeeded. Listening only for the first loses the second
    # entirely — the guest has paid and there is no booking.
    if event["type"] in ("checkout.session.completed",
                         "checkout.session.async_payment_succeeded"):
        session = event["data"]["object"]
        meta = smeta(session)
        conn = get_db()
        try:
            if meta.get("kind") in ("workshop_deposit", "workshop_balance"):
                if sval(session, "payment_status") == "paid":
                    mark_workshop_payment_paid(conn, session)
            elif meta.get("kind") == "pos":
                # Without this the guest paid, Stripe took the money, and the
                # tab stayed open — the takings never appeared in the day's
                # figures and somebody would have chased them for it.
                if sval(session, "payment_status") == "paid":
                    settle_pos_from_stripe_session(conn, session, meta)
            elif meta.get("kind") == "restaurant":
                existing = conn.execute(
                    "SELECT id FROM restaurant_bookings WHERE stripe_session_id = ?", (session["id"],)
                ).fetchone()
                if not existing and sval(session, "payment_status") == "paid":
                    create_restaurant_booking_from_stripe_session(conn, session)
            elif meta.get("kind") == "room_balance":
                # Must be matched explicitly: the fall-through below CREATES a
                # booking from the session, so a guest paying off an existing
                # stay would get a second, duplicate booking out of it.
                if sval(session, "payment_status") == "paid":
                    mark_booking_payment_paid(conn, session)
            else:
                existing = conn.execute(
                    "SELECT id FROM bookings WHERE stripe_session_id = ?", (session["id"],)
                ).fetchone()
                if not existing and sval(session, "payment_status") == "paid":
                    create_booking_from_stripe_session(conn, session)
        except sqlite3.IntegrityError:
            # The guest's success redirect got there first. Nothing to do —
            # the booking exists, and this is the outcome we want.
            pass
        except Exception as e:
            # Never leave the connection open on the way out: a leaked handle
            # made the next write fail with "database is locked". Re-raise so
            # Stripe sees a 500 and retries, which is the correct behaviour
            # for a payment we may not have recorded.
            print(f"[stripe webhook] {event['type']} failed: {e}")
            raise
        finally:
            conn.close()

    elif event["type"] == "checkout.session.async_payment_failed":
        # A delayed payment that did not arrive. Nothing was created for it —
        # the branches above only act on "paid" — so there is no booking to
        # cancel. What there is, is a guest who believes they have paid and a
        # bank that has said otherwise, and nobody would ever find out.
        session = event["data"]["object"]
        meta = smeta(session)
        who = (meta.get("guest_name") or meta.get("contact_name")
               or sval(session, "customer_email") or "someone")
        conn = get_db()
        try:
            log_audit(conn, "stripe_payment_failed", target=who,
                      details=f"{meta.get('kind') or 'booking'} — "
                              f"session {session['id']}")
            # A task rather than only a log line, because the log is somewhere
            # nobody looks until they already know something is wrong.
            conn.execute(
                """INSERT INTO tasks (title, notes, priority, due_date, status,
                     origin, created_at)
                   VALUES (?, ?, 'high', ?, 'open', 'payment', ?)""",
                (f"A payment from {who} failed after checkout",
                 "They completed checkout with a method that settles later, and "
                 "the payment did not arrive. Nothing was booked. Stripe session "
                 f"{session['id']}.",
                 service_day_iso(), datetime.now(timezone.utc).isoformat()))
            conn.commit()
        except Exception as e:
            print(f"[stripe webhook] async_payment_failed handling failed: {e}")
            raise
        finally:
            conn.close()

    return jsonify(received=True), 200


@app.route("/book/manage", methods=["GET", "POST"])
def find_booking():
    if request.method == "POST":
        conn = get_db()
        if rate_limited(conn, "find_booking", BOOKING_RATE_LIMIT_PER_HOUR):
            conn.commit()
            conn.close()
            flash("Too many attempts from this connection — please try again in a bit, or contact the château directly.", "error")
            return render_template("find_booking.html")
        conn.commit()
        reference_code = request.form.get("reference_code", "").strip().upper()
        email = request.form.get("email", "").strip().lower()
        booking = conn.execute(
            "SELECT manage_token FROM bookings WHERE reference_code = ? AND guest_email = ?",
            (reference_code, email),
        ).fetchone()
        conn.close()
        if booking:
            return redirect(url_for("manage_booking", manage_token=booking["manage_token"]))
        flash("No booking found with that reference and email.", "error")
    return render_template("find_booking.html")


