@app.route("/admin/rooms")
@owner_required
def admin_rooms():
    conn = get_db()
    rooms = conn.execute("SELECT * FROM rooms ORDER BY sort_order, name").fetchall()
    sources_by_room, ics_urls, blocks_by_room = {}, {}, {}
    now = datetime.now(timezone.utc)
    for room in rooms:
        sources = conn.execute(
            "SELECT * FROM ical_sources WHERE room_id = ? ORDER BY id", (room["id"],)
        ).fetchall()
        stale, last_logs = [], []
        for s in sources:
            synced_at = parse_datetime_iso(s["last_synced_at"])
            stale.append(not synced_at or (now - synced_at) > timedelta(hours=24))
            last_logs.append(conn.execute(
                "SELECT * FROM ical_sync_log WHERE ical_source_id = ? ORDER BY id DESC LIMIT 1",
                (s["id"],),
            ).fetchone())
        sources_by_room[room["id"]] = list(zip(sources, stale, last_logs))
        ics_urls[room["id"]] = url_for("room_ics_feed", token=room["export_token"], _external=True)
        blocks_by_room[room["id"]] = conn.execute(
            "SELECT * FROM room_blocks WHERE room_id = ? ORDER BY start_date", (room["id"],)
        ).fetchall()
    conn.close()
    return render_template(
        "admin_rooms.html", rooms=rooms, sources_by_room=sources_by_room, ics_urls=ics_urls,
        blocks_by_room=blocks_by_room, today=now.date(),
    )


@app.route("/room-issues")
@login_required
def room_issues():
    conn = get_db()
    status_filter = request.args.get("status", "open")
    query = (
        """SELECT room_issues.*, rooms.name AS room_name, users.name AS reported_by_name
           FROM room_issues JOIN rooms ON rooms.id = room_issues.room_id
           LEFT JOIN users ON users.id = room_issues.reported_by_user_id"""
    )
    params = ()
    if status_filter in ("open", "resolved"):
        query += " WHERE room_issues.status = ?"
        params = (status_filter,)
    query += " ORDER BY room_issues.created_at DESC"
    issues = conn.execute(query, params).fetchall()
    rooms = conn.execute("SELECT * FROM rooms WHERE active = 1 ORDER BY sort_order, name").fetchall()
    employees = conn.execute("SELECT * FROM users WHERE role = 'employee' ORDER BY name").fetchall()
    # Counted separately rather than off `issues`, which the status filter
    # above has usually already narrowed (this page defaults to open-only).
    counts = {
        r["status"]: r["c"] for r in conn.execute(
            "SELECT status, COUNT(*) AS c FROM room_issues GROUP BY status"
        ).fetchall()
    }
    rooms_affected = conn.execute(
        "SELECT COUNT(DISTINCT room_id) AS c FROM room_issues WHERE status = 'open'"
    ).fetchone()["c"]
    # Who is walking into each of these rooms, and when. One query for the
    # whole page, and before the connection closes.
    arrivals = arrivals_by_room(conn, [i["room_id"] for i in issues if i["status"] == "open"])
    conn.close()

    today = datetime.now(timezone.utc).date().isoformat()

    def age(i):
        """How long it has been sitting there. A tap that has dripped for six
        weeks is a different conversation from one reported this morning, and
        on a list sorted by date they read the same."""
        if i["status"] != "open":
            return None
        raised = (i["created_at"] or "")[:10]
        if not raised:
            return None
        if raised >= _iso_plus_days(today, -2):
            return "Just raised"
        if raised >= _iso_plus_days(today, -14):
            return "Open a while"
        return "Open over a fortnight"

    def guest_coming(i):
        if i["status"] != "open":
            return None
        a = arrivals.get(i["room_id"])
        if not a:
            return None
        days = days_until(a["arrival_date"])
        return "Guest arriving this week" if (days or 99) <= 7 else "Guest arriving soon"

    lv = list_view(
        issues, request.args,
        search=["title", "description", "room_name", "reported_by_name"],
        search_hint="Search fault, room or who reported it",
        facets=[
            # First, because it is the only one that has a date attached to it.
            facet("arriving", "Someone coming", guest_coming,
                  order=["Guest arriving this week", "Guest arriving soon"]),
            facet("age", "How long open", age,
                  order=["Open over a fortnight", "Open a while", "Just raised"]),
            facet("room", "Room", lambda i: i["room_name"], limit=10),
            facet("who", "Reported by", lambda i: i["reported_by_name"], limit=8),
        ],
        sorts=[
            # Default: whoever is arriving soonest into a broken room comes
            # first. Longest-open is a fair second, but a fault nobody is
            # about to meet is not the most urgent thing on the list.
            sort_option("arriving", "Guest arriving soonest",
                        lambda i: (arrivals[i["room_id"]]["arrival_date"]
                                   if i["room_id"] in arrivals and i["status"] == "open"
                                   else "9999", i["created_at"] or "")),
            sort_option("oldest", "Longest open first", lambda i: i["created_at"] or ""),
            sort_option("recent", "Newest first", lambda i: i["created_at"] or "", reverse=True),
            sort_option("room", "Room",
                        lambda i: ((i["room_name"] or "").lower(), i["created_at"] or "")),
        ],
        default_sort="arriving",
    )
    return render_template(
        "room_issues.html", issues=lv["rows"], lv=lv, rooms=rooms,
        status_filter=status_filter, employees=employees, counts=counts,
        rooms_affected=rooms_affected, arrivals=arrivals, days_until=days_until,
        in_words=in_words,
    )


