@app.route("/admin/rooms/new", methods=["GET", "POST"])
@owner_required
def new_room():
    if request.method == "POST":
        f = room_fields_from_form()
        if not f["name"]:
            flash("Give the room a name.", "error")
            return render_template("room_form.html", room=None)

