    conn.execute(
        "INSERT INTO room_blocks (room_id, start_date, end_date, reason, created_at) VALUES (?, ?, ?, ?, ?)",
        (room_id, start.isoformat(), end.isoformat(), reason or None, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
