# ---------------------------------------------------------------------------
# Money ahead.
#
# Every figure below already exists, on five different screens: a room booking
# knows what it is worth and what has been paid, a workshop registration knows
# its balance and the date that balance falls due, recurring costs know when
# they next go out, insurance knows its renewal. Nobody has ever put them on
# one timeline, so the question a house funding a restoration actually asks —
# what is coming in, what is going out, and which month is tight — has no
# answer anywhere in the app.
#
# What this deliberately does NOT claim: that it knows the bank balance. It
# does not. Without an opening figure the running line is a CHANGE, not a
# balance, and saying otherwise would be inventing the most important number
# on the page. The opening balance is a setting; until it is set, the page
# says so plainly rather than implying a total it cannot know.
# ---------------------------------------------------------------------------

OPENING_BALANCE_SETTING = "money_ahead_opening_balance"
# Wages, as a figure the owner sets rather than one this app works out.
#
# It could try: there are hours, shifts and pay rates. But pay_rate and
# pay_type are free text, estimated_hourly_cost() says in its own docstring
# that it is "never a payroll or payslip figure", and most people on the books
# have no usable rate at all. Deriving a wage bill from that would put a guess
# on the one page that promises only money somebody has committed to. A figure
# the owner types is worth more than a figure we infer, because they know
# which it is.
MONTHLY_STAFF_COST_SETTING = "money_ahead_monthly_staff"


def _month_starts(first, last):
    """Every month start from first to last inclusive, as dates."""
    out, cur = [], first.replace(day=1)
    while cur <= last:
        out.append(cur)
        cur = (date(cur.year + 1, 1, 1) if cur.month == 12
               else date(cur.year, cur.month + 1, 1))
    return out


def _recurring_dates(next_due, frequency, first, last):
    """When a standing cost falls due inside the window.

    Walked forward from its own next-due date rather than from today, so a
    cost due on the 8th stays on the 8th. A cost whose next-due date is in the
    past is treated as due now — it has not stopped being owed.
    """
    if not next_due:
        return []
    step_months = 12 if frequency == "annual" else 1
    out, cur = [], next_due
    while cur < first:
        cur = _add_months(cur, step_months)
    while cur <= last:
        out.append(cur)
        cur = _add_months(cur, step_months)
    return out


def _add_months(d, months):
    total = d.month - 1 + months
    year, month = d.year + total // 12, total % 12 + 1
    return date(year, month, min(d.day, monthrange(year, month)[1]))


def money_ahead(conn, *, days=90, today=None):
    """What is expected in and out over the window, and when.

    Only money that is genuinely expected: a confirmed booking with something
    still to pay, a workshop balance with a due date, a standing cost, an
    insurance renewal. Nothing is forecast from averages or last year — a
    guess dressed as a figure is worse than a gap, because it gets budgeted
    against.
    """
    today = today or datetime.now(LOCAL_TZ).date()
    if isinstance(today, str):
        today = parse_date(today)
    last = today + timedelta(days=max(1, min(730, days)))
    incoming, outgoing = [], []

    # Rooms. Settled on arrival, so that is the date the money is expected.
    for b in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
                 LEFT JOIN rooms ON rooms.id = bookings.room_id
                WHERE bookings.status = 'confirmed'
                  AND bookings.arrival_date >= ? AND bookings.arrival_date <= ?""",
            (today.isoformat(), last.isoformat())).fetchall():
        due = round((b["total_price"] or 0) + (b["city_tax"] or 0)
                    - (b["discount_amount"] or 0) - (b["amount_paid"] or 0), 2)
        if due > 0.01:
            incoming.append({"date": b["arrival_date"], "amount": due,
                             "label": f"{b['guest_name']} — {b['room_name'] or 'room'}",
                             "kind": "Room", "ref": b["reference_code"]})

    # Workshops. The deposit is due when they register and the balance on its
    # own date, so an unpaid one of either is money genuinely still to come.
    for w in conn.execute(
            """SELECT workshop_bookings.*, workshops.title,
                      workshop_sessions.start_date
                 FROM workshop_bookings
                 JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
                 JOIN workshops ON workshops.id = workshop_sessions.workshop_id
                WHERE workshop_bookings.status IN ('confirmed', 'pending')""").fetchall():
        if (w["deposit_amount"] or 0) > 0 and not w["deposit_paid_at"]:
            when = w["balance_due_date"] or w["start_date"]
            if when and today.isoformat() <= when <= last.isoformat():
                incoming.append({"date": when, "amount": round(w["deposit_amount"], 2),
                                 "label": f"{w['guest_name']} — {w['title']} deposit",
                                 "kind": "Workshop", "ref": w["reference_code"]})
        if (w["balance_amount"] or 0) > 0 and not w["balance_paid_at"]:
            when = w["balance_due_date"] or w["start_date"]
            if when and today.isoformat() <= when <= last.isoformat():
                incoming.append({"date": when, "amount": round(w["balance_amount"], 2),
                                 "label": f"{w['guest_name']} — {w['title']} balance",
                                 "kind": "Workshop", "ref": w["reference_code"]})

    # The restaurant. Paid on the night, less any deposit already taken.
    for r in conn.execute(
            """SELECT * FROM restaurant_bookings
                WHERE status = 'confirmed' AND no_show_at IS NULL
                  AND dinner_date >= ? AND dinner_date <= ?
                  AND COALESCE(total_price, 0) > 0""",
            (today.isoformat(), last.isoformat())).fetchall():
        due = round((r["total_price"] or 0) - (r["discount_amount"] or 0)
                    - (r["deposit_amount"] or 0), 2)
        if due > 0.01 and r["payment_status"] != "paid":
            incoming.append({"date": r["dinner_date"], "amount": due,
                             "label": f"{r['guest_name']} — dinner, {r['party_size']} covers",
                             "kind": "Restaurant", "ref": r["reference_code"]})

    # Standing costs, expanded across the window on their own dates.
    for c in conn.execute(
            "SELECT * FROM recurring_costs WHERE active = 1").fetchall():
        for when in _recurring_dates(parse_date(c["next_due_date"] or ""),
                                     c["frequency"], today, last):
            outgoing.append({"date": when.isoformat(), "amount": round(c["amount"] or 0, 2),
                             "label": c["label"], "kind": "Standing cost", "ref": None})

    # Insurance renewals. The premium falls due when the policy expires.
    for p in conn.execute(
            "SELECT * FROM insurance_policies WHERE COALESCE(premium, 0) > 0").fetchall():
        for when in _recurring_dates(parse_date(p["expiry_date"] or ""),
                                     p["premium_frequency"] or "annual", today, last):
            outgoing.append({"date": when.isoformat(), "amount": round(p["premium"], 2),
                             "label": f"{p['provider']} — {p['coverage_type'] or 'insurance'}",
                             "kind": "Insurance", "ref": p["policy_number"]})

    # Supplier invoices waiting on a decision. They carry no due date, so they
    # sit on today rather than being invented onto a date — they are owed now,
    # which is exactly why they are still on the approvals queue.
    for e in conn.execute(
            """SELECT * FROM expenses WHERE status = 'pending'
                 AND COALESCE(amount, 0) > 0""").fetchall():
        outgoing.append({"date": today.isoformat(), "amount": round(e["amount"], 2),
                         "label": f"{e['vendor_name']} — awaiting your decision",
                         "kind": "Awaiting approval", "ref": None})

    # Wages, if a monthly figure has been set. Dated to the end of each month,
    # which is when French salaries are usually paid, and only for whole months
    # inside the window — half a month of wages on a part month would be a
    # figure nobody could check against a bank statement.
    staff = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?",
        (MONTHLY_STAFF_COST_SETTING,)).fetchone()
    try:
        staff = round(float(staff["value"]), 2) if staff and staff["value"] else None
    except (TypeError, ValueError):
        staff = None
    if staff:
        for start in _month_starts(today, last):
            payday = date(start.year, start.month, monthrange(start.year, start.month)[1])
            if today <= payday <= last:
                outgoing.append({"date": payday.isoformat(), "amount": staff,
                                 "label": "Wages — the monthly figure you set",
                                 "kind": "Wages", "ref": None})

    incoming.sort(key=lambda x: (x["date"], -x["amount"]))
    outgoing.sort(key=lambda x: (x["date"], -x["amount"]))

    opening = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?",
        (OPENING_BALANCE_SETTING,)).fetchone()
    try:
        opening = round(float(opening["value"]), 2) if opening and opening["value"] else None
    except (TypeError, ValueError):
        opening = None

    months, running = [], opening or 0.0
    for start in _month_starts(today, last):
        end = _add_months(start, 1)
        window = (max(start, today).isoformat(), min(end, last + timedelta(days=1)).isoformat())
        m_in = round(sum(i["amount"] for i in incoming if window[0] <= i["date"] < window[1]), 2)
        m_out = round(sum(o["amount"] for o in outgoing if window[0] <= o["date"] < window[1]), 2)
        running = round(running + m_in - m_out, 2)
        months.append({"label": start.strftime("%B %Y"), "start": start.isoformat(),
                       "in": m_in, "out": m_out, "net": round(m_in - m_out, 2),
                       "running": running,
                       # Only meaningful once an opening balance is known. Without
                       # one this is a change, and calling a change a shortfall
                       # would be the page's first lie.
                       "short": opening is not None and running < 0})

    total_in = round(sum(i["amount"] for i in incoming), 2)
    # Work already on the upkeep schedule that falls due inside the window.
    #
    # Kept OUT of the totals and out of the running line, deliberately. The
    # rest of this page is money somebody has committed to; this is money the
    # house has committed to SPENDING, priced from what the same job cost last
    # time. That is a projection from last year, which is exactly what the
    # figures above promise not to be — so it sits in its own list, with its
    # own subtotal, and the reader is told which is which.
    upcoming_work = []
    for sched in conn.execute(
            "SELECT * FROM maintenance_schedules WHERE active = 1").fetchall():
        due = maintenance_next_due(sched)
        if not due or not (today <= due <= last):
            continue
        # Only where a real cost was recorded. Inventing a price for a job
        # nobody has ever paid for would be a guess inside a guess.
        priced = conn.execute(
            """SELECT cost, done_on FROM maintenance_visits
               WHERE schedule_id = ? AND COALESCE(cost, 0) > 0
               ORDER BY done_on DESC LIMIT 1""", (sched["id"],)).fetchone()
        upcoming_work.append({
            "date": due.isoformat(), "label": sched["name"],
            "amount": round(priced["cost"], 2) if priced else None,
            "since": priced["done_on"] if priced else None,
            "required": sched["required_by"] != "none",
        })
    upcoming_work.sort(key=lambda w: w["date"])
    work_total = round(sum(w["amount"] for w in upcoming_work if w["amount"]), 2)
    work_unpriced = len([w for w in upcoming_work if not w["amount"]])

    total_out = round(sum(o["amount"] for o in outgoing), 2)
    return {
        "upcoming_work": upcoming_work, "work_total": work_total,
        "work_unpriced": work_unpriced,
        "from": today.isoformat(), "to": last.isoformat(), "days": (last - today).days,
        "incoming": incoming, "outgoing": outgoing, "months": months,
        "total_in": total_in, "total_out": total_out,
        "net": round(total_in - total_out, 2),
        "opening": opening, "monthly_staff": staff,
        "closing": round((opening or 0) + total_in - total_out, 2) if opening is not None else None,
    }


@app.route("/management/outlook")
@owner_required
def management_outlook():
    """Committed out against expected in, by month.

    Sits beside the financials rather than inside them because it answers a
    different question: not what the house made, but what it has already
    promised and been promised.
    """
    try:
        months = max(1, min(12, int(request.args.get("months", "6"))))
    except ValueError:
        months = 6
    conn = get_db()
    outlook = cash_outlook(conn, months=months)
    costs = conn.execute(
        """SELECT * FROM recurring_costs WHERE active = 1
           ORDER BY frequency, amount DESC""").fetchall()
    conn.close()
    negative = [r for r in outlook["rows"] if r["net"] < 0]
    overview = [
        overview_cell("Expected in", euro(outlook["money_in"]),
                      sub=f"over {months} month{'s' if months != 1 else ''}",
                      hint="already booked, not a forecast"),
        overview_cell("Committed out", euro(outlook["money_out"]),
                      hint="contracts and the rota"),
        overview_cell("Difference", euro(outlook["net"]),
                      alert=outlook["net"] < 0),
        overview_cell("Months in the red", len(negative), alert=len(negative),
                      hint="on committed figures alone"),
    ]
    return render_template("management_outlook.html", outlook=outlook,
                           overview=overview, months=months, costs=costs)


@app.route("/management/financials")
@owner_required
def management_financials():
    today = datetime.now(timezone.utc).date()
    conn = get_db()
    months = []
    cursor = today.replace(day=1)
    for _ in range(6):
        month_end = date(cursor.year + 1, 1, 1) if cursor.month == 12 else date(cursor.year, cursor.month + 1, 1)
        summary = financial_month_summary(conn, cursor, month_end)
        summary["occupancy_rate"] = compute_month_stats(conn, cursor)["occupancy_rate"]
        months.append(summary)
        cursor = date(cursor.year - 1, 12, 1) if cursor.month == 1 else date(cursor.year, cursor.month - 1, 1)
    months.reverse()
    current = months[-1]
    month_end_for_current = date(today.year + 1, 1, 1) if today.month == 12 else date(today.year, today.month + 1, 1)
    room_revenue = room_revenue_breakdown(conn, today.replace(day=1), month_end_for_current)
    expense_breakdown = expense_category_breakdown(conn, today.replace(day=1), month_end_for_current)
    ytd = financial_month_summary(conn, date(today.year, 1, 1), today + timedelta(days=1))

    last_year_start = date(today.year - 1, today.month, 1)
    last_year_end = date(last_year_start.year + 1, 1, 1) if last_year_start.month == 12 else date(last_year_start.year, last_year_start.month + 1, 1)
    last_year = financial_month_summary(conn, last_year_start, last_year_end)
    last_year["occupancy_rate"] = compute_month_stats(conn, last_year_start)["occupancy_rate"]

    def pct_change(now_val, then_val):
        if not then_val:
            return None
        return round((now_val - then_val) / then_val * 100, 1)

    yoy = {
        "revenue_pct": pct_change(current["revenue"], last_year["revenue"]),
        "occupancy_pct": pct_change(current["occupancy_rate"], last_year["occupancy_rate"]),
    }
    conn.close()
    return render_template(
        "management_financials.html", months=months, current=current, today=today,
        room_revenue=room_revenue, ytd=ytd, expense_breakdown=expense_breakdown,
        last_year=last_year, last_year_start=last_year_start, yoy=yoy,
    )


@app.route("/management/financials/annual-summary")
@owner_required
def annual_summary():
    try:
        year = int(request.args.get("year", "") or datetime.now(timezone.utc).year)
    except ValueError:
        year = datetime.now(timezone.utc).year
    year_start = date(year, 1, 1)
    year_end = date(year + 1, 1, 1)

    conn = get_db()
    financials = financial_month_summary(conn, year_start, year_end)

    room_count = conn.execute("SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"]
    days_in_year = (year_end - year_start).days
    overlapping = conn.execute(
        """SELECT arrival_date, departure_date FROM bookings
           WHERE status = 'confirmed' AND room_id IN (SELECT id FROM rooms WHERE active = 1)
           AND arrival_date < ? AND departure_date > ?""",
        (year_end.isoformat(), year_start.isoformat()),
    ).fetchall()
    booked_nights = 0
    for b in overlapping:
        b_start, b_end = parse_date(b["arrival_date"]), parse_date(b["departure_date"])
        if not b_start or not b_end:
            continue
        overlap_start, overlap_end = max(b_start, year_start), min(b_end, year_end)
        booked_nights += max(0, (overlap_end - overlap_start).days)
    total_possible_nights = days_in_year * room_count
    occupancy_rate = round(booked_nights / total_possible_nights * 100) if total_possible_nights else 0

    room_revenue = room_revenue_breakdown(conn, year_start, year_end)
    expense_breakdown = expense_category_breakdown(conn, year_start, year_end)
    top_vendors = conn.execute(
        """SELECT vendor_name, SUM(amount) AS total FROM expenses
           WHERE kind = 'supplier_invoice' AND status IN ('approved','paid') AND vendor_name IS NOT NULL
           AND submitted_at >= ? AND submitted_at < ? GROUP BY vendor_name ORDER BY total DESC LIMIT 10""",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchall()
    feedback_row = conn.execute(
        "SELECT AVG(rating) AS a, COUNT(*) AS c FROM guest_feedback WHERE submitted_at >= ? AND submitted_at < ?",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchone()
    booking_count = conn.execute(
        "SELECT COUNT(*) AS c FROM bookings WHERE status = 'confirmed' AND arrival_date >= ? AND arrival_date < ?",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchone()["c"]
    conn.close()

    return render_template(
        "annual_summary.html", year=year, financials=financials, occupancy_rate=occupancy_rate,
        room_revenue=room_revenue, expense_breakdown=expense_breakdown, top_vendors=top_vendors,
        feedback_avg=round(feedback_row["a"], 1) if feedback_row["a"] is not None else None,
        feedback_count=feedback_row["c"], booking_count=booking_count,
    )


@app.route("/management/financials/export.csv")
@owner_required
def export_financials_csv():
    today = datetime.now(timezone.utc).date()
    conn = get_db()
    months = []
    cursor = today.replace(day=1)
    for _ in range(12):
        month_end = date(cursor.year + 1, 1, 1) if cursor.month == 12 else date(cursor.year, cursor.month + 1, 1)
        months.append(financial_month_summary(conn, cursor, month_end))
        cursor = date(cursor.year - 1, 12, 1) if cursor.month == 1 else date(cursor.year, cursor.month - 1, 1)
    conn.close()
    months.reverse()
    rows = [
        {
            "month": m["month"].strftime("%Y-%m"),
            "revenue": m["revenue"],
            "staff_expenses": m["staff_expenses"],
            "supplier_expenses": m["supplier_expenses"],
            "expenses_total": m["expenses_total"],
            "estimated_labour_cost": m["labour_cost"] if m["labour_cost"] is not None else "",
            "net": m["net"],
        }
        for m in months
    ]
    fieldnames = ["month", "revenue", "staff_expenses", "supplier_expenses", "expenses_total",
                  "estimated_labour_cost", "net"]
    return csv_response(fieldnames, rows, f"financials_{today.isoformat()}.csv")


