def delete_vehicle_transfer(transfer_id):
    conn = get_db()
    transfer = conn.execute("SELECT vehicle_id FROM vehicle_transfers WHERE id = ?", (transfer_id,)).fetchone()
    if not transfer:
        conn.close()
