@app.route("/management/company-info", methods=["GET", "POST"])
@owner_required
def management_company_info():
    conn = get_db()
    if request.method == "POST":
        fields = [
            "legal_name", "registration_number", "vat_number", "registered_address",
            "incorporation_date", "accountant_name", "accountant_phone", "accountant_email",
            "insurance_broker_name", "insurance_broker_phone", "insurance_broker_email",
        ]
        values = [request.form.get(f, "").strip() or None for f in fields]
        conn.execute(
            f"""INSERT INTO company_info (id, {', '.join(fields)}, updated_at)
                VALUES (1, {', '.join(['?'] * len(fields))}, ?)
                ON CONFLICT(id) DO UPDATE SET {', '.join(f'{f} = excluded.{f}' for f in fields)}, updated_at = excluded.updated_at""",
            (*values, datetime.now(timezone.utc).isoformat()),
        )
        # Lives in app_settings rather than company_info: it isn't a fact about
        # the company, it's a number the booking forms enforce, and it belongs
        # with the other single-value settings the app already reads that way.
        capacity_raw = request.form.get("house_guest_capacity", "").strip()
        if capacity_raw.isdigit() and int(capacity_raw) > 0:
            conn.execute(
                """INSERT INTO app_settings (key, value) VALUES ('house_guest_capacity', ?)
                   ON CONFLICT(key) DO UPDATE SET value = excluded.value""",
                (capacity_raw,))
        log_audit(conn, "company_info_updated")
        conn.commit()
        conn.close()
        flash("Company info updated.", "success")
        return redirect(url_for("management_company_info"))
    info = conn.execute("SELECT * FROM company_info WHERE id = 1").fetchone()
    capacity = house_guest_capacity(conn)
    # Insurance lives here rather than on a page of its own. The broker was
    # already listed on this form while the policies sat somewhere else, which
    # is two places to look for one answer.
    policies = conn.execute(
        "SELECT * FROM insurance_policies ORDER BY expiry_date IS NULL, expiry_date").fetchall()
    conn.close()
    return render_template("management_company_info.html", info=info,
                           house_guest_capacity=capacity, policies=policies)


